(window.GIM_TS=window.GIM_TS||{})["Taanit.0"]={"from":0,"a":[["\u0003מאימתי,\u0004 מאיזה יום בשנה, \u0003מזכירין גבורות גשמים,\u0004 שאומר: \"משיב הרוח ומוריד הגשם\" בתוך התפילה? \u0003ר' אליעזר אומר: מיום טוב הראשון של חג\u0004 הסוכות. \u0003ר' יהושע אומר: מיום טוב האחרון של חג\u0004 זה.","\u0003אמר לו ר' יהושע: הואיל ואין הגשמים אלא סימן קללה בחג,\u0004 שהרי אם יורדים גשמים כאשר הכל יושבים בסוכה, הרי זה סימן של קללה לישראל, ואם כן \u0003למה הוא מזכיר\u0004 גשמים בחג? \u0003אמר לו ר' אליעזר: אף אני לא אמרתי לשאול\u0004 ולהתפלל בלשון בקשה שירדו גשמים \u0003אלא להזכיר \"משיב הרוח ומוריד הגשם\" בעונתו. אמר לו\u0004 ר' יהושע: \u0003אם כן\u0004 שההזכרה היא לשיטתך רק זיכרון בלא בקשה כלל, \u0003לעולם יהא מזכיר\u0004 את הגשמים בכל ימות השנה גם בקיץ!","כלל הוא לכל הדעות: \u0003אין שואלים את הגשמים\u0004 בלשון בקשה \u0003אלא סמוך לגשמים. ר' יהודה אומר: העובר לפני התיבה\u0004 (שליח ציבור המתפלל) \u0003ביום טוב האחרון של חג\u0004 הסוכות (שמיני עצרת), \u0003האחרון\u0004 זה המתפלל תפילת המוסף \u0003מזכיר\u0004 בה את הגשמים, ואילו \u0003הראשון\u0004 המתפלל תפילת שחרית \u0003אינו מזכיר.\u0004 ולהיפך עושים בסיום תקופת בקשת הגשמים; \u0003ביום טוב\u0004 ה\u0003ראשון של פסח\u0004 שהוא סוף זמן שאילת גשמים, \u0003הראשון\u0004 המתפלל שחרית, עדיין \u0003מזכיר,\u0004 ו\u0003האחרון\u0004 המתפלל מוסף שוב \u0003אינו מזכיר.\u0004","תחילה שואלים: ה\u0003תנא\u0004 שבמשנתנו \u0003היכא קאי\u0004 \u0005[היכן הוא עומד],\u0006 על מה הוא נסמך, \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003\"מאימתי\",\u0004 שנראה שהוא ממשיך מהנחה ברורה שיש חובה של תפילה על הגשמים, והוא ממשיך בשאלה מאימתי מזכירים זאת? ומשיבים: ה\u0003תנא התם קאי\u0004 \u0005[שם הוא עומד]\u0006 על מקור זה הוא נסמך,","\u0003דקתני\u0004 \u0005[ששנה]\u0006 במסכת הראשונה בשישה סדרי משנה, ברכות: \u0003מזכירים גבורות גשמים ב\u0004ברכה על \u0003תחיית המתים, ושואלין\u0004 (מבקשים שירדו גשמים) \u0003בברכת השנים, והבדלה\u0004 של מוצאי שבת וחג אומרים \u0003ב\u0004ברכת \u0003\"חונן הדעת\".\u0004 ועל סמך משנה זו שקבעה את חיוב הבקשה שבחזרה \u0003קתני\u0004 \u0005[שנה]\u0006 כאן \u0003מאימתי מזכירים גבורות גשמים.\u0004","ושואלים: אם כן, \u0003וליתני התם\u0004 \u0005[ושישנה\u0006 פרטי הלכה זו \u0005שם]\u0006 ו\u0003מאי שנא דשבקיה עד הכא\u0004 \u0005[במה שונה,\u0006 מדוע, \u0005שהניח\u0006 את הדבר \u0005עד כאן]\u0006 מתחילת סדר זרעים עד מסכת זו שבסוף סדר מועד?!","\u0003אלא\u0004 עלינו לחזור בנו מתירוץ זה, ולומר כי ה\u0003תנא\u0004 שלנו \u0003מ\u0004מסכת \u0003ראש השנה סליק\u0004 \u0005[עולה,\u0006 ממשיך\u0005],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה שם\u0005]:\u0006 \u0003ובחג\u0004 הסוכות \u0003נידונין\u0004 כל באי עולם \u0003על המים. ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 שם \u0003ובחג נידונים על המים,\u0004 סמך על כך שראוי שיזכירו בקשת המים סמוך לדין, ולכן \u0003תנא\u0004 \u0005[שנה]\u0006 כאן \u0003מאימתי מזכירין גבורות גשמים.\u0004","על לשון המשנה שואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 לשון \u0003\"מאימתי מזכירים על הגשמים\" מאי\u0004 \u0005[מה\u0006 פירוש הלשון\u0005]\u0006 \u0003\"גבורות גשמים\"\u0004 שאמר? \u0003אמר ר' יוחנן: מפני שיורדים בגבורה\u0004 והם מגלים את גבורת ה' בעולם. \u0003שנאמר: \"עשה גדלות עד אין חקר ונפלאות עד אין מספר\"\u0004 (איוב ה, ט) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 סמוך לו: \u0003\"הנתן מטר על פני הארץ ושלח מים על פני חוצות\"\u0004 (איוב ה, י).","על ראיה זו שואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות,\u0006 מה היא ההוכחה\u0005]\u0006 מפסוקים אלה שירידת הגשם נחשבת לגבורה? \u0003אמר רבה בר שילא: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"חקר\" \"חקר\" מברייתו של עולם.\u0004","\u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בגשמים \u0003\"עשה גדלות עד אין חקר\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בבריאת העולם \u0003\"הלוא ידעת אם לא שמעת אלהי עולם ה' בורא קצות הארץ לא ייעף ולא ייגע אין חקר לתבונתו\"\u0004 (ישעיהו מ, כח) משמע שהכתוב משווה שני דברים אלה זה לזה, ובבריאת העולם \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"מכין הרים בכחו נאזר בגבורה\"\u0004 (תהלים סה, ז) ולכן נקשר מושג הגבורה גם לגשמים.","ושואלים: \u0003ומנא לן\u0004 \u0005[ומניין לנו]\u0006 ש\u0003בתפלה\u0004 דווקא צריך להזכיר את הגשמים? ומסבירים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"לאהבה את ה' אלהיכם ולעבדו בכל לבבכם\"\u0004 (דברים יא, יג) והסבירו חכמים בכמה מקומות \u0003איזו היא עבודה\u0004 את ה' \u0003שהיא בלב — הוי אומר: זו תפלה. וכתיב בתריה\u0004 \u0005[ונאמר\u0006 בפסוק \u0005אחריו]:\u0006 \u0003\"ונתתי מטר ארצכם בעתו יורה ומלקוש\"\u0004 (דברים יא, יד), ונלמד מכאן כי כאשר עוסקים בעבודה שהיא בלב, בתפילה, ראוי להתפלל על הגשמים.","אגב הזכרת גבורת ה' שיש בירידתם של גשמים מביאים מאמרות בענין זה. \u0003אמר ר' יוחנן: שלשה מפתחות\u0004 מצויים \u0003בידו של הקדוש ברוך הוא שלא נמסרו\u0004 כרגיל \u0003ביד שליח,\u0004 אלא הוא בעצמו דואג להם. \u0003ואלו הן: מפתח של גשמים, ומפתח של חיה\u0004 (יולדת), \u0003ומפתח של תחיית המתים.\u0004","וראיות לדבר: \u0003מפתח של גשמים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יפתח ה' לך את אוצרו הטוב את השמים לתת מטר ארצך בעתו\"\u0004 (דברים כח, יב), משמע שמפתח זה ביד ה' הוא. \u0003מפתח של חיה\u0004 (יולדת) \u0003מנין — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויזכר אלהים את רחל וישמע\u0004"],["\u0003אליה אלהים ויפתח את רחמה\"\u0004 (בראשית ל, כב). \u0003מפתח של תחיית המתים מנין — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידעתם כי אני ה' בפתחי את קברותיכם\u0004 ובהעלותי אתכם מקברותיכם עמי\u0003\"\u0004 (יחזקאל לז, יג).","\u0003במערבא\u0004 (במערב, בארץ ישראל) \u0003אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003אף מפתח של פרנסה\u0004 הוא בידי ה', \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פותח את ידך\u0004 ומשביע לכל חי רצון\u0003\"\u0004 (תהלים קמה, טז). ושואלים: \u0003ור' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא קא חשיב להא\u0004 \u0005[החשיב את זה]?\u0006 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003גשמים היינו פרנסה,\u0004 שהרי גשמים הם ענין כולל, והם מפתח לכל ענייני הפרנסה בכללה.","שנינו במשנה ש\u0003ר' אליעזר אומר\u0004 ש\u0003מיום טוב הראשון של חג\u0004 מזכירין גשמים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003ר' אליעזר מהיכא גמיר לה\u0004 \u0005[מהיכן למד אותה,\u0006 את ההלכה הזו\u0005]?\u0006 האם \u0003מ\u0004דין \u0003לולב גמר לה\u0004 \u0005[למד אותה]\u0006 \u0003או מניסוך המים גמר לה\u0004 \u0005[למד אותה],\u0006 כשהוא סבור להתחיל את הזכרת הגשם מחג הסוכות בדומה למצוות אלה הקשורות אף הן בגשם.","ובהסברת ההבדל מאיזה דין למד הלכה זו, מפרטים: \u0003מלולב גמר לה\u0004 \u0005[למד אותה],\u0006 ולכן: \u0003מה לולב ביום,\u0004 שמצוותו רק ביום ולא בלילה, \u0003אף הזכרה\u0004 של הגשם מתחילה רק \u0003ביום\u0004 החג הראשון. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מניסוך המים גמר לה\u0004 \u0005[למד אותה],\u0006 ואם כן יש לומר: \u0003מה ניסוך המים\u0004 המצוה היא \u0003מאורתא\u0004 \u0005[מן הלילה]\u0006 הראשון, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מה שנאמר \u0003\"ומנחתם ונסכיהם\"\u0004 (במדבר כט, יח) בא ללמדנו שאף שהקרבת הקרבן אינה נעשית אלא ביום, אולם הקרבת המנחות וניסוך הנסכים, יכולים להיעשות \u0003אפילו בלילה,\u0004 אם כן, \u0003אף הזכרה\u0004 של גשמים צריכה שתיעשה כבר \u0003מאורתא\u0004 \u0005[מן הלילה]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ש\u0003אמר ר' אבהו: לא למדה ר' אליעזר אלא מלולב.\u0004 ומקור דבריו: \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 ש\u0003ר' אבהו גמרא גמיר לה\u0004 \u0005[במסורת למד אותה]\u0006 שזוהי שיטת רבי אליעזר, \u0003ואיכא דאמרי מתניתא שמיע ליה\u0004 \u0005[ויש אומרים\u0006 שמ\u0005ברייתא למד זאת].\u0006","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה ברייתא — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מאימתי מזכירין על הגשמים? ר' אליעזר אומר: משעת נטילת לולב.\u0004 כלומר, משעה שבה מצוה ליטול אותו ביום הראשון של חג הסוכות, \u0003ר' יהושע אומר: משעת הנחתו.\u0004 כלומר, משעה שבה מניחים ושוב אין נוטלים אותו.","\u0003אמר ר' אליעזר: הואיל וארבעת מינין הללו,\u0004 הלולב והמינים הבאים עמו \u0003אינן באין אלא לרצות על המים\u0004 שהם קשורים לתפילה שיירדו גשמים בשנה הזו, \u0003וכשם שארבע מינין הללו אי אפשר בהם בלא מים,\u0004 שהרי צומחים הם על המים וזקוקים להם — \u0003כך אי אפשר לעולם\u0004 כולו \u0003בלא מים,\u0004 ולכן יש להזכירם בתפילה מזמן מצות הלולב.","\u0003אמר לו ר' יהושע: והלא גשמים בחג אינו אלא סימן קללה! אמר לו ר' אליעזר: אף אני לא אמרתי לשאול אלא להזכיר\u0004 בלבד, \u0003וכשם שתחיית המתים מזכיר כל השנה כולה ואינה אלא בזמנה\u0004 בזמן שיעלה רצון מלפני ה' לעשות זאת, \u0003כך מזכירין גבורות גשמים כל השנה ואינן\u0004 באים \u0003אלא בזמנן. ולפיכך\u0004 לפי שיטה זו, \u0003אם בא להזכיר\u0004 גשמים \u0003כל השנה כולה\u0004 — \u0003מזכיר.\u0004 ואילו \u0003רבי אומר: אומר אני, משעה שמפסיק לשאלה,\u0004 כלומר, באותו זמן שמפסיק להתפלל ולבקש על ירידת גשמים — \u0003כך מפסיק להזכרה,\u0004 ולא כדברי ר' אליעזר.","\u0003ר' יהודה בן בתירה אומר:\u0004 לא מתחילת החג אלא \u0003בשני בחג הוא מזכיר, ר' עקיבא אומר: בששי בחג הוא מזכיר.\u0004 ואילו \u0003ר' יהודה משום ר' יהושע אומר: העובר לפני התיבה ביום טוב האחרון של חג\u0004 (שמיני עצרת), \u0003האחרון\u0004 המתפלל תפילת מוסף \u0003מזכיר\u0004 גשמים, ואילו \u0003הראשון\u0004 המתפלל שחרית \u0003אינו מזכיר.\u0004 וכנגדו ביום שמסיימים בהזכרת גשמים, העובר לפני התיבה \u0003ביום טוב ראשון של פסח\u0004 — \u0003הראשון מזכיר\u0004 ו\u0003האחרון אינו מזכיר.\u0004 עד כאן הברייתא.","ומעירים: \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' אליעזר לר' יהושע\u0004 שהוכיח שיש להזכיר גם כשאינו בזמנו, כדרך שמזכירים תחיית המתים אף שלא בזמנה! ומשיבים: \u0003אמר לך\u0004 \u0005[היה יכול לומר לך]\u0006 \u0003ר' יהושע: בשלמא\u0004 \u0005[נניח]\u0006 \u0003תחיית המתים מזכיר\u0004 בכל עת, שאף שאינה מתקיימת בכל יום, בכל זאת \u0003דכולי יומא זמניה\u0004 \u0005[ש\u0006ב\u0005כל יום זמנה]\u0006 \u0003הוא,\u0004 שראוי הדבר להיות בכל יום.","\u0003אלא גשמים, כל אימת דאתיין זמנייהו היא\u0004 \u0005[כל זמן שהם באים זמנם הוא]?!\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003יצא\u0004 חודש \u0003ניסן ו\u0004אחר כך \u0003ירדו גשמים — סימן קללה הם,\u0004 וראיה לדבר, ממה \u0003שנאמר: \"הלוא קציר חטים היום\u0004 אקרא אל ה' ויתן קולות ומטר ודעו וראו כי רעתכם רבה\u0003\"\u0004 (שמואל א' יב, יז).","שנינו שם: \u0003ר' יהודה בן בתירה אומר: בשני בחג הוא מזכיר.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטתו של \u0003ר' יהודה בן בתירה? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה בן בתירה אומר:\u0004 רמז לניסוך המים מן התורה,","\u0003נאמר ב\u0004קרבנות יום ה\u0003שני\u0004 של חג הסוכות בשינוי מבשאר הימים, שבשאר הימים כתוב \"ונסכה\" וביום שני נאמר \u0003\"ונסכיהם\"\u0004 (במדבר כט, יט), \u0003ונאמר בששי\u0004 גם כן שינוי \u0003\"ונסכיה\"\u0004 (במדבר כט, לא), \u0003ונאמר בשביעי \"כמשפטם\"\u0004 (במדבר כט, לג) (ולא כבשאר הימים \"כמשפט\"),","\u0003הרי\u0004 לנו כאן \u0003מ\"ם יו\"ד מ\"ם\u0004 שיש בהם שינוי, \u0003הרי\u0004 הם מצטרפים יחד למלה \u0003מים,\u0004 ו\u0003מכאן רמז לניסוך המים מן התורה.\u0004","ומסבירים לפי זה: \u0003ומאי שנא בשני דנקט\u0004 \u0005[ומה שונה,\u0006 מדוע \u0005נקט\u0006 שמזכירים את הגשמים \u0005ב\u0006יום \u0005השני],\u0006 \u0003דכי רמיזי להו בקרא\u0004 \u0005[שכאשר רמוזים הם בכתוב] —\u0006 \u0003בשני הוא דרמיזי\u0004 \u0005[שנרמזים]\u0006 \u0003הלכך\u0004 \u0005[לכן]\u0006 \u0003ב\u0004יום ה\u0003שני מדכרינן\u0004 \u0005[מזכירים אנו].\u0006","\u0003ר' עקיבא אומר: בששי בחג הוא מזכיר,\u0004 שכאן הוא הרמז לניסוך המים, \u0003שנאמר בששי: \"ונסכיה\"\u0004 בלשון רבים, ומכאן למדים ש\u0003בשני ניסוכין הכתוב מדבר, אחד ניסוך המים ואחד ניסוך היין.\u0004","ומקשים: אמנם נאמרו שם שני ניסוכים \"נסכיה\" אבל \u0003אימא תרוייהו דחמרא\u0004 \u0005[אמור\u0006 ש\u0005שניהם\u0006 הם ניסוכים \u0005של יין]?\u0006 ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 גם \u0003כ\u0004שיטת \u0003ר' יהודה בן בתירה\u0004 ש\u0003אמר: רמיזי מיא\u0004 \u0005[\u0006ש\u0005רמוזים\u0006 על כל פנים \u0005מים]\u0006 בכתוב על פי צירוף האותיות הנוספות, וכיון שנאמר \"נסכיה\" למדים שהכוונה שיש להוסיף עוד ניסוך אחד של מים."],["\u0003אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 ר' עקיבא \u0003כ\u0004שיטת \u0003ר' יהודה בן בתירה\u0004 — \u0003נימא כוותיה\u0004 \u0005[שיאמר כמותו]\u0006 בכל דבר, ואף בכך שמזכיר ביום השני ולא בראשון! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' עקיבא: כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 \u0003\"ניסוך\" יתירא\u0004 \u0005[יתר]\u0006 — \u0003ב\u0004יום ה\u0003ששי הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שנאמר \"ונסכיה\" (במדבר כט, לא) בלשון רבים ללמד על שני ניסוכים, ומשום כך יש לעשות את הניסוך הנוסף של המים ביום השישי.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת באותו ענין, \u0003ר' נתן אומר:\u0004 נאמר: \u0003\"בקדש הסך נסך שכר לה'\"\u0004 (במדבר כח, ז), ושינוי הלשון כאן מלמד כי \u0003בשני ניסוכין הכתוב מדבר; אחד ניסוך המים ואחד ניסוך היין.\u0004 ושואלים: \u0003אימא תרוייהו דחמרא\u0004 \u0005[אמור\u0006 כי \u0005שניהם של יין]!\u0006 ומשיבים: \u0003אם כן לכתוב קרא\u0004 \u0005[שיכתוב הכתוב]\u0006 באותו ענין \u0003או \"הסך הסך\" או \"נסך נסך\", מאי\u0004 \u0005[מה]\u0006 הלשון הכפולה והשונה \u0003\"הסך נסך\"\u0004 — \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]:\u0006 \u0003חד דמיא וחד דחמרא\u0004 \u0005[אחד של מים ואחד של יין].\u0006","ושואלים: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 \u0003ניסוך המים\u0004 נעשה \u0003כל שבעה\u0004 ימים של חג הסוכות, \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהושע — נימא חד יומא\u0004 \u0005[שיאמר יום אחד]\u0006 בלבד, \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' עקיבא\u0004 — \u0003תרי יומי\u0004 \u0005[שני ימים]\u0006 שישי ושביעי, \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' יהודה בן בתירה — שיתא יומי\u0004 \u0005[שישה ימים]\u0006 מהיום השני והלאה!","ומשיבים: \u0003לעולם\u0004 תפרש כי שיטת \u0003ר' יהודה בן בתירה היא, וסבירא ליה\u0004 \u0005[וסבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה דמתניתין\u0004 \u0005[של המשנה].\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 (סוכה מח,ב) \u0003ר' יהודה אומר: בלוג היה מנסך כל שמונה,\u0004 לא רק בחג הסוכות, אלא גם בשמיני עצרת. ואילו ר' יהודה בן בתירה \u0003מפיק\u0004 \u0005[מוציא]\u0006 את היום ה\u0003ראשון\u0004 שבו לא היה מנסך \u0003ומעייל\u0004 \u0005[ומכניס]\u0006 את היום ה\u0003שמיני\u0004 שבו הוא מנסך, ואם כן שבעה ימים הם לניסוך המים.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 היום ה\u0003ראשון\u0004 ש\u0003לא\u0004 מנסכים בו, \u0003דכי רמיזי מיא\u0004 \u0005[שכאשר רמוזים מים]\u0006 \u0003ב\u0004יום ה\u0003שני הוא דרמיזי\u0004 \u0005[שרמוזים],\u0006 אם כן \u0003שמיני נמי\u0004 \u0005[גם כן]\u0006 אין סיבה לנסך, שהרי \u0003כי רמיזי\u0004 \u0005[כאשר רמוזים]\u0006 \u0003מים, ב\u0004יום ה\u0003שביעי הוא דרמיזי\u0004 \u0005[שרמוזים]\u0006 אבל לא בשמיני, ואף בשמיני אינו בכלל זה!","\u0003אלא,\u0004 יש לחזור בנו ממה שפירשנו ויש לומר כי משנתנו כדעת \u0003ר' יהושע היא,\u0004 אלא שלדעתו \u0003ניסוך המים כל שבעה הלכתא גמירי לה\u0004 \u0005[\u0006מ\u0005הלכה\u0006 למשה מסיני \u0005לומדים אותה]\u0006 שמסורת שבעל־פה היא ואינה נסמכת על המקראות,","ש\u0003אמר ר' אמי אמר ר' יוחנן משום ר' נחוניא איש בקעת בית חורתן:\u0004 דין \u0003עשר נטיעות\u0004 שאם היו עשרה עצים צעירים (נטיעות) הזקוקים למים בתוך שטח של בית סאה, מותר לחרוש בגללם את כל השדה עד שנת השביעית (אף שאסור לחרוש שדות אחרים משלושים יום לפני השביעית) וכן המצוה של הקפת המזבח ונטילת \u0003ערבה\u0004 בהושענא רבא, \u0003ו\u0004דיני \u0003ניסוך המים\u0004 — כולם \u0003הלכה למשה מסיני.\u0004","באותה ברייתא שנינו: \u0003ר' יהודה אומר משום ר' יהושע: העובר לפני התיבה ביום טוב האחרון של חג, האחרון\u0004 המתפלל מוסף \u0003מזכיר\u0004 גשמים, \u0003הראשון אינו מזכיר.\u0004 המתפלל \u0003ביום טוב הראשון של פסח\u0004 שהוא סוף זמן תפילת הגשם \u0003הראשון\u0004 בשחרית \u0003מזכיר\u0004 את הגשם, \u0003האחרון אינו מזכיר.\u0004","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' יהושע,\u0004 כלומר, היכן אמר רבי יהושע דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' יהושע דמתניתין\u0004 \u0005[של משנתנו],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 ר' יהושע במשנתנו ש\u0003ביום טוב האחרון של חג הוא מזכיר,\u0004 ומשמע שמזכיר מתחילת היום, מתפילת ערבית והלאה.","\u0003אלא\u0004 תאמר שהוא סומך על שיטת \u0003ר' יהושע\u0004 הנזכרת ב\u0003ברייתא, הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 שם שמתחילים להזכיר \u0003משעת הנחתו\u0004 של הלולב, וכיון שהנחתו בסוף היום השביעי של חג הסוכות משמע שמזכירים מליל של שמיני עצרת והלאה.","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005],\u0006 ש\u0003ר' יהודה אומר משום בן בתירה: העובר לפני התיבה ביום טוב האחרון של חג האחרון מזכיר, הי\u0004 \u0005[איזה]\u0006 \u0003בן בתירה\u0004 הוא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ר' יהודה בן בתירה\u0004 הוא — \u0003הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר\u0004 כי \u0003בשני בחג הוא מזכיר!\u0004","\u0003אמר רב נחמן בר יצחק: תהא\u0004 (תתפרש) הסוגיה שכאן מדובר \u0003בר' יהושע בן בתירה,\u0004 שבשמו מסר רבי יהודה את ההלכה, ועל ידי כך נתרץ את שתי השאלות כאחת \u0003זמנין דקרי ליה בשמיה\u0004 \u0005[פעמים שקורא אותו בשמו]\u0006 רבי יהושע (ואינו רבי יהושע סתם, שהוא רבי יהושע בן חנניא) ובשמו אמר רבי יהודה, \u0003וזימנין דקרי ליה בשמיה דאבא\u0004 \u0005[ופעמים שקורא אותו בשמו של אביו],\u0006 בן בתירא, והוא הוא התנא שבשמו מסר רבי יהודה את הברייתא השניה. ומסבירים מה הטעם בשינוי השם: \u0003והא\u0004 \u0005[וזה]\u0006 שקראו אותו בשם אביו, בן בתירה, היה זה \u0003מקמי דליסמכוהו\u0004 \u0005[לפני שסמכוהו]\u0006 בתואר רבי, \u0003והא\u0004 \u0005[וזה]\u0006 שקראוהו ר' יהושע, היה זה \u0003לבתר דליסמכוהו\u0004 \u0005[אחרי שסמכוהו].\u0006","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003בטל וברוחות, לא חייבו חכמים להזכיר\u0004 או להתפלל \"מוריד הטל ומשיב הרוח\" \u0003ואם בא להזכיר — מזכיר.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הלכה זו? \u0003אמר ר' חנינא: לפי שאין נעצרין\u0004 ותמיד הם מצויים, ולכן אין סיבה להזכירם.","ומסבירים: \u0003וטל מנלן דלא מיעצר\u0004 \u0005[מנין לנו שאיננו נעצר]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אליהו התשבי מתשבי גלעד אל אחאב חי ה' אלהי ישראל אשר עמדתי לפניו אם יהיה השנים האלה טל ומטר כי אם לפי דברי\"\u0004 (מלכים א' יז, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לך הראה אל אחאב ואתנה מטר על פני האדמה\"\u0004 (מלכים א' יח, א), \u0003ואילו טל לא קאמר ליה\u0004 \u0005[אמר לו]\u0006 שיחזיר, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003משום\u0004"],["\u0003דלא מיעצר\u0004 \u0005[שאינו נעצר]\u0006 לעולם ואפילו באותו זמן המשיך להיות טל. ושואלים: \u0003וכי מאחר דלא מיעצר\u0004 \u0005[שאין\u0006 הטל \u0005נעצר]\u0006 לעולם, \u0005אם כן\u0006 \u0003אליהו אשתבועי\u0004 \u0005[להשבע]\u0006 \u0003למה ליה\u0004 \u0005[לו],\u0006 למה הועילה שבועתו שלא יהיה טל? ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 אליהו: \u0003אפילו טל\u0004 של \u0003ברכה נמי\u0004 \u0005[גם כן]\u0006 המסייע לגידולי האדמה \u0003לא אתי\u0004 \u0005[יבוא],\u0006 ודבר זה אכן נתקיים. ושואלים: אם כן, \u0003ליהדריה\u0004 \u0005[שיחזיר]\u0006 אחר כך גם את \u0003טל\u0004 ה\u0003ברכה\u0004 ויאמר \"ואתנה טל ומטר\", ומדוע נאמר רק על הגשם? ומשיבים: \u0003משום דלא מינכרא מילתא\u0004 \u0005[שאין הדבר ניכר],\u0006 שהרי אין הבריות רואים אם אמנם טל זה של ברכה הוא כפי שאמר לו, אם לא, והיה אחאב יכול לומר כי זה אותו טל שלא הפסיק כלל ולא טל הברכה.","ושואלים: \u0003אלא רוחות מנא לן דלא מיעצרי\u0004 \u0005[מנין לנו שאינן נעצרות]\u0006 ונושבות תמיד? \u0003אמר ר' יהושע בן לוי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי כארבע רוחות השמים פרשתי אתכם נאם ה'\"\u0004 (זכריה ב, י), ונברר: \u0003מאי קאמר להו\u0004 \u0005[מה אמר להם]?\u0006 \u0003אילימא הכי קאמר להו\u0004 \u0005[אם תאמר\u0006 כי \u0005כך אמר להם]\u0006 \u0003הקדוש ברוך הוא לישראל: דבדרתינכו בארבע רוחי דעלמא\u0004 \u0005[שפיזרתי אתכם בארבע רוחות העולם],\u0006 \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון \u0003\"כארבע\"\u0004 איננה נכונה, ו\u0003\"בארבע\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כשם שאי אפשר לעולם בלא רוחות,\u0004 שהרי בלעדיהם יתמלא העולם חום והבל — \u0003כך אי אפשר לעולם בלא ישראל,\u0004 שכל זכות קיומו אינה אלא בשביל ישראל, משמע שרוחות השמים נושבות תמיד.","\u0003אמר ר' חנינא: הלכך,\u0004 מתוך קביעות אלה אנו למדים כי \u0003בימות החמה\u0004 אם \u0003אמר \"משיב הרוח\"\u0004 — \u0003אין מחזירין אותו\u0004 להתפלל שוב, שהרי הרוח נושבת גם אז. ואם \u0003אמר\u0004 בקיץ \u0003\"מוריד הגשם\"\u0004 — \u0003מחזירים אותו,\u0004 שהרי סימן קללה הוא.","\u0003בימות הגשמים,\u0004 אם \u0003לא אמר \"משיב הרוח\"\u0004 — \u0003אין מחזירין אותו\u0004 שבין כה וכה תהיה רוח. \u0003לא אמר \"מוריד הגשם\"\u0004 — \u0003מחזירין אותו,\u0004 שהרי החורף הוא זמן הגשם. \u0003ולא עוד אלא אפילו אמר\u0004 בטעות \u0003\"מעביר הרוח ומפריח הטל\",\u0004 כלומר, שלא יהיה לא רוח ולא טל — \u0003אין מחזירין אותו,\u0004 שהרי הם מצויים תמיד.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בדומה לזה: \u0003בעבים\u0004 (עננים) \u0003וברוחות לא חייבו חכמים להזכיר, ואם בא להזכיר\u0004 — \u0003מזכיר, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003משום דלא מיעצרי\u0004 \u0005[שאינם נעצרים]\u0006 ותמיד יש עננים ורוחות.","ושואלים: \u0003ולא מיעצרי\u0004 \u0005[וכי אינם נעצרים]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: מה שנאמר \u0003\"ועצר את השמים\"\u0004 (דברים יא, יז), כוונתו שימנע אותם \u0003מן העבים ומן הרוחות. אתה אומר\u0004 ש\"עצר את השמים\" הוא \u0003מן העבים ומן הרוחות, או אינו אלא מן המטר\u0004 שלא ירד? \u0003כשהוא אומר\u0004 בסופו של אותו פסוק \u0003\"ולא יהיה מטר\"\u0004 — \u0003הרי מטר אמור\u0004 במפורש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 ומסביר את דברי הכתוב \u0003\"ועצר את השמים\"\u0004 — \u0003מן העבים ומן הרוחות.\u0004","ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003רוחות\u0004 על \u0003רוחות\u0004 שבברייתא זו נאמר שהן נעצרות, ו\u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003עבים\u0004 על \u0003עבים!\u0004 ומשיבים: מ\u0003עבים\u0004 על \u0003עבים לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שיש עננים — \u0003בחרפי\u0004 \u0005[במוקדמים],\u0006 שעננים המוקדמים, הבאים לפני הגשם, תמיד הם באים, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין עננים — \u0003באפלי\u0004 \u0005[במאוחרים],\u0006 שלא תמיד באים העננים שלאחר הגשם.","אף מ\u0003רוחות\u0004 על \u0003רוחות לא קשיא\u0004 \u0005[אינו קשה]\u0006; \u0003הא\u0004 \u0005[זה]\u0006 — \u0003ברוח מצויה\u0004 אינה נעצרת, \u0003הא\u0004 \u0005[זו]\u0006 — \u0003ברוח שאינה מצויה\u0004 שהיא תפסיק לנשוב. ושואלים: הלא \u0003רוח שאינה מצויה חזיא לבי דרי\u0004 \u0005[ראויה לגורן]\u0006 לזריית התבואה, ואף היא נחוצה לעולם וצריך להתפלל עליה! ומשיבים: דבר זה אינו חשוב כל כך, כי \u0003אפשר\u0004 לזרות את התבואה \u0003בנפוותא\u0004 \u0005[בנפות]\u0006 אף בלא רוח, ולכן אין שינוי גדול על ידי עצירת הרוחות הללו.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003העבים והרוחות שניות למטר.\u0004 כלומר, תועלתן מרובה עד שהן שניות רק למטר. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק],\u0006 באלו מקרים מדובר? \u0003אמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יהודה:\u0004 מדובר בעבים ורוח \u0003דבתר מיטרא\u0004 \u0005[\u0006הבאים \u0005אחרי הגשם].\u0006 ותוהים: \u0003למימרא דמעליותא\u0004 \u0005[האם לומר שמעלה]\u0006 \u0003היא\u0004 זו בעבים ורוחות שלאחר הגשם? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתוכחה: \u0003\"יתן ה' את מטר ארצך אבק ועפר\"\u0004 (דברים כח, כד) \u0003ואמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יהודה:\u0004 הכוונה היא ל\u0003זיקא דבתר מטרא\u0004 \u0005[רוח שאחרי הגשם]\u0006 שעושה אבק ועפר, משמע שהיא ענין של קללה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא דאתא ניחא\u0004 \u0005[זה שבא בקלות]\u0006 הוא יפה, \u0003הא דאתא רזיא\u0004 \u0005[זה שבא בחוזק]\u0006 יוצר אבק ועפר ואינו מועיל. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כש\u0003מעלה אבק,\u0004 ו\u0003הא\u0004 \u0005[זו]\u0006 רוח המועילה \u0003דלא\u0004 \u0005[\u0006כ\u0005שאינו]\u0006 \u0003מעלה אבק.\u0004","\u0003ואמר רב יהודה\u0004 מעין זה: \u0003זיקא דבתר מיטרא\u0004 \u0005[רוח שלאחר הגשם] —\u0006 יפה \u0003כמיטרא\u0004 \u0005[כגשם]\u0006 עצמו מפני שהיא מועילה לאדמה. \u0003עיבא דבתר מיטרא\u0004 \u0005[ענן שלאחר הגשם] —\u0006 יפה \u0003כמיטרא\u0004 \u0005[כגשם].\u0006 \u0003שימשא דבתר מיטרא\u0004 \u0005[שמש שלאחר הגשם]\u0006 — מועילה \u0003כתרי מטרי\u0004 \u0005[כשני גשמים].\u0006 ושואלים: אם גם רוח גם ענן וגם שמש טובים ומועילים, אם כן \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003למעוטי גילהי דליליא\u0004 \u0005[זוהר שבלילה]\u0006 \u0003ושמשא דביני קרחי\u0004 \u0005[ושמש\u0006 שזורחת ביום \u0005מבין\u0006 העננים, במקומות שבהם אין עננים, ונראים כ\u0005קרחות],\u0006 ששניהם אינם טובים לאחר הגשם.","באותו ענין \u0003אמר רבא: מעלי תלגא לטורי כחמשה מטרי לארעא\u0004 \u0005[מעולה השלג להרים כחמישה גשמים לארץ]\u0006 של מישור, \u0003שנאמר: \"כי לשלג יאמר הוא ארץ וגשם מטר וגשם מטרות עזו\"\u0004 (איוב לז, ו), שבפסוק זה רמוזים חמש פעמים גשם (\"וגשם\" \"מטר\" \"וגשם\" ו\"מטרות\" שהם שניים — בסך הכל חמישה) ללמד שהשלג יפה להר, וכל שכן לארץ מישור, כחמישה גשמים.","\u0003ואמר רבא\u0004 עוד בענין זה: \u0003תלגא לטורי\u0004 \u0005[שלג\u0006 יפה \u0005להרים],\u0006 \u0003מטרא רזיא לאילני\u0004 \u0005[גשם עז\u0006 יפה \u0005לאילנות],\u0006 \u0003מטרא ניחא לפירי\u0004 \u0005[גשם נוח\u0006 יפה \u0005לפירות],\u0006"],["\u0003עורפילא\u0004 (גשם דק מאוד) \u0003אפילו לפרצידא דתותי קלא מהניא ליה\u0004 \u0005[לגרגיר שתחת רגב\u0006 אדמה, \u0005מועיל לו],\u0006 לפי שהוא מגיע לכל מקום ואינו מזיק כלל. ורמז לדבר: \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003עורפילא — עורו פילי\u0004 \u0005[יתעוררו\u0006 הגרגרים \u0005בסדקים\u0006 של הארץ\u0005].\u0006 אגב מאמר זה מביאים דבר אחר שאף בו השתמשו באותו דימוי. \u0003ואמר רבא: האי צורבא מרבנן דמי לפרצידא דתותי קלא\u0004 \u0005[תלמיד חכם דומה לגרגר שתחת רגב\u0006 אדמה\u0005],\u0006 \u0003כיון דנבט נבט\u0004 \u0005[ש\u0006הוא \u0005צומח —\u0006 \u0005צומח\u0006 והולך\u0005]\u0006 וגדל מאז והלאה, שכאשר מתחיל הוא להתפרסם — הולך שמו וגדל.","\u0003ו\u0004בענין דומה \u0003אמר רבא: האי צורבא מרבנן דרתח\u0004 \u0005[תלמיד חכם שכועס]\u0006 \u0003אורייתא הוא דקא מרתחא ליה\u0004 \u0005[התורה היא שמרתיחה אותו]\u0006 ולכן צריך לדון אותו לכף זכות, \u0003שנאמר: \"הלוא כה דברי כאש נאם ה'\"\u0004 (ירמיהו כג, כט), \u0003ו\u0004כיוצא בו \u0003אמר רב אשי: כל תלמיד חכם שאינו קשה כברזל\u0004 שאינו תקיף ומוותר על דברים — \u0003אינו תלמיד חכם, שנאמר\u0004 באותו פסוק: \u0003\"וכפטיש יפצץ סלע\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: אתון, מהתם מתניתו לה\u0004 \u0005[אתם, משם אתם שונים,\u0006 לומדים, \u0005אותה]\u0006 \u0003אנן מהכא מתנינן לה\u0004 \u0005[אנחנו, מכאן אנו שונים,\u0006 לומדים, \u0005אותה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ארץ אשר אבניה ברזל\"\u0004 (דברים ח, ט), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"אבניה\", אלא בוניה,\u0004 והכוונה לתלמידי חכמים שהם הבונים את הארץ ברוחניות, והם קשים כברזל. ועם זאת \u0003אמר רבינא: אפילו הכי\u0004 \u0005[כך]\u0006 ששבחו של תלמיד חכם שהוא קשה כברזל \u0003מיבעי ליה לאיניש למילף נפשיה בניחותא\u0004 \u0005[צריך לו לאדם ללמד עצמו\u0006 לנהוג \u0005בנעימות],\u0006 \u0003שנאמר \"והסר כעס מלבך\u0004 והעבר רעה מבשרך\u0003\"\u0004 (קהלת יא, י).","כהקדמה לדברי ר' ברכיה להלן, מבארים מה ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: שלשה שאלו\u0004 (בקשו) מה' \u0003שלא כהוגן,\u0004 שלא פירשו את בקשתם בלשון ראויה, \u0003לשנים\u0004 מהם \u0003השיבוהו כהוגן, לאחד השיבוהו שלא כהוגן. ואלו הן: אליעזר עבד אברהם, ושאול בן קיש, ויפתח הגלעדי.\u0004","כיצד: \u0003אליעזר עבד אברהם, דכתיב\u0004 \u0005[שנאמר]\u0006 שהתפלל ליד הבאר, \u0003\"והיה הנערה אשר אמר אליה הטי נא כדך\u0004 אותה הוכחת לעבדך ליצחק\u0003\"\u0004 (בראשית כד, יד), וכיון שעשה זאת כתנאי, \u0003יכול אפילו\u0004 תימצא הנערה \u0003חיגרת, אפילו סומא\u0004 (עיוורת) ומכל מקום יקחנה אליעזר ליצחק. ומכל מקום \u0003השיבו\u0004 לו \u0003כהוגן, ונזדמנה לו רבקה\u0004 שהיו בה כל המעלות.","\u0003שאול בן קיש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר],\u0006 שכאשר התגרה גלית הפלישתי בישראל, אמר שאול: \u0003\"והיה האיש אשר יכנו יעשרנו המלך עשר גדול ואת בתו יתן לו\"\u0004 (שמואל א' יז, כה), \u0003יכול אפילו\u0004 יהא אותו אדם \u0003עבד, אפילו ממזר\u0004 שאסור לו לשאת את ישראלית, ואם כן נמצא שמבטיח את בתו לאדם שאינו ראוי, מכל מקום \u0003השיבו\u0004 לו \u0003כהוגן ונזדמן לו דוד.\u0004","אף \u0003יפתח הגלעדי\u0004 אמר דבר שלא כהוגן, שאמר בצאתו למלחמה: \u0003\"והיה היוצא אשר יצא מדלתי ביתי\u0004 לקראתי בשובי בשלום... והיה לה' והעליתיהו עולה\u0003\"\u0004 (שופטים יא, לא), \u0003יכול אפילו\u0004 יצא \u0003דבר טמא\u0004 יקריב אותו, ו\u0003השיבו\u0004 לו \u0003שלא כהוגן, ונזדמנה לו בתו\u0004 שלו.","ובענין יפתח מעירים: \u0003והיינו דקאמר להו\u0004 \u0005[והוא שאמר להם]\u0006 ה\u0003נביא לישראל: \"הצרי אין בגלעד אם רפא אין שם\u0004 כי מדוע לא עלתה ארוכת בת עמי\u0003\"\u0004 (ירמיהו ח, כב), לומר, שאילו היו מחפשים היו מוצאים דרך להתיר לו את נדרו.","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בענין קרבנות אדם: \u0003\"\u0004ובנו את במות הבעל לשרוף את בניהם באש עולות לבעל \u0003אשר לא צויתי ולא דברתי ולא עלתה על לבי\"\u0004 (ירמיהו יט, ה),","ומפרשים: \u0003\"אשר לא צויתי\"\u0004 — \u0003זה בנו של מישע מלך מואב\u0004 שהקריבו אביו, \u0003שנאמר: \"ויקח את בנו הבכור אשר ימלך תחתיו ויעלהו עלה\"\u0004 (מלכים ב' ג, כז), \u0003\"ולא דברתי\"\u0004 — \u0003זה יפתח,\u0004 שמעצמו הקריב קרבן כזה, \u0003\"ולא עלתה על לבי\"\u0004 — \u0003זה יצחק בן אברהם\u0004 שאמנם אמר ה' להעלותו אבל לא עלתה על לבו, שהרי נועד הדבר לנסיון בלבד.","ובהמשך לדברי ר' שמואל בר נחמני \u0003אמר ר' ברכיה: אף כנסת ישראל שאלה שלא כהוגן, והקדוש ברוך הוא השיבה כהוגן, שנאמר: \"ונדעה נרדפה לדעת את ה' כשחר נכון מצאו ויבוא כגשם לנו\"\u0004 (הושע ו, ג), וכתשובה לשאלתה","\u0003אמר לה הקדוש ברוך הוא: בתי, את שואלת\u0004 גשם שהוא \u0003דבר שפעמים מתבקש\u0004 ורצוי \u0003ופעמים אינו מתבקש,\u0004 כגון בחדשי הקיץ, \u0003אבל אני אהיה לך דבר המתבקש לעולם, שנאמר: \"אהיה כטל לישראל\"\u0004 (הושע יד, ו), שהטל תמיד הוא בא, ותמיד הוא לברכה.","\u0003ועוד שאלה\u0004 כנסת ישראל \u0003שלא כהוגן, אמרה לפניו: רבונו של עולם! \"שימני כחותם על לבך כחותם על זרועך\"\u0004 (שיר השירים ח, ו), וכתשובה לבקשתה \u0003אמר לה הקדוש ברוך הוא: בתי, את שואלת דבר שפעמים נראה ופעמים אינו נראה,\u0004 שהרי הלב והזרוע לא תמיד הם גלויים, \u0003אבל אני אעשה לך דבר שנראה לעולם, שנאמר: \"הן על כפים חקתיך\u0004 חומותיך נגדי תמיד\u0003\"\u0004 (ישעיהו מט, טז).","שנינו במשנה: \u0003אין שואלין את הגשמים\u0004 אלא סמוך לעונת הגשמים. \u0003סברוה\u0004 \u0005[סברו]\u0006 הלומדים, כי \u0003שאלה והזכרה חדא מילתא היא\u0004 \u0005[דבר אחד הוא]\u0006 ואינן אלא מילים נרדפות, ולפי הנחה זו \u0003מאן\u0004 \u0005[מי הוא]\u0006 \u0003תנא\u0004 זה, הסבור כך? \u0003אמר רבא:\u0004 שיטת \u0003ר' יהושע היא,\u0004 ש\u0003אמר\u0004 ש\u0003משעת הנחתו\u0004 של הלולב, שהוא הזמן שאין נוטלים אותו עוד, כלומר: בשמיני עצרת, מזכירים את הגשמים והוא אכן הזמן הסמוך לעונת הגשמים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003ר' אליעזר\u0004 הסובר כי מזכירים גשמים ביום טוב הראשון של חג הסוכות, אלא יש לחלק: \u0003שאלה\u0004 היא ענין \u0003לחוד, והזכרה\u0004 היא ענין \u0003לחוד,\u0004 וגם לדעת רבי אליעזר אין שואלים גשמים אלא סמוך לגשמים ממש, ואף הוא לא אמר אלא מענין הזכרה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שמועה זו בגירסה שונה: \u0003לימא\u0004 \u0005[האם לומר]\u0006"],["\u0003ר' יהושע היא,\u0004 ש\u0003אמר\u0004 כי \u0003משעת הנחתו\u0004 של הלולב מזכירים גבורות גשמים ולא כשיטת ר' אליעזר?! \u0003אמר רבא: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהמשנה כשיטת \u0003ר' אליעזר,\u0004 ועם כל זה יש לחלק ולומר כי \u0003שאלה לחוד\u0004 ובזה גם ר' אליעזר מודה, \u0003והזכרה לחוד.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר: העובר לפני התיבה\u0004 ביום טוב האחרון של חג, רק המתפלל מוסף מתחיל להזכיר את הגשם, וכשמפסיקים להזכיר — ביום טוב ראשון של פסח — המתפלל שחרית עדיין מזכיר והמתפלל מוסף כבר אינו מזכיר.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003עד מתי שואלין את הגשמים? ר' יהודה אומר: עד שיעבור הפסח, ר' מאיר אומר: עד שיעבור ניסן.\u0004 הרי שלדעת ר' יהודה שואלים את הגשמים עד אחרי הפסח, ולא עד תחילתו!","\u0003אמר רב חסדא: לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003כאן\u0004 בברייתא שאמרו עד שיעבור הפסח הוא לענין \u0003לשאול\u0004 גשמים, ו\u0003כאן\u0004 במשנה מדובר \u0003להזכיר,\u0004 ושיטת ר' יהודה היא: \u0003מישאל שאיל ואזיל\u0004 \u0005[לשאול\u0006 הוא \u0005שואל והולך]\u0006 עד סוף הפסח, \u0003להזכיר\u0004 — \u0003ביום טוב הראשון פסיק\u0004 \u0005[פוסק]\u0006 ואינו מזכיר עוד.","\u0003אמר עולא: הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב חסדא קשיא\u0004 \u0005[קשה],\u0006 אם להשתמש בדימוי שבכתוב: \u0003\"כחמץ לשנים וכעשן לעינים\"\u0004 (משלי י, כו). שהרי, \u0003מה במקום שאינו שואל\u0004 עדיין, וכגון ביום טוב האחרון של חג הסוכות — בכל זאת כבר \u0003מזכיר, במקום ששואל,\u0004 בימי חול המועד פסח, \u0003אינו דין שיהא\u0004 גם \u0003מזכיר?\u0004 ואיך אפשר לומר ששאלה תמשך בזמן שאין הזכרה!","\u0003אלא אמר עולא:\u0004 יש לתרץ כי כאן \u0003תרי תנאי\u0004 \u0005[שני תנאים\u0006 הם\u0005]\u0006 שנחלקו \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יהודה,\u0004 לדעת אחד מהם, שיטת ר' יהודה היא ששואלים עד לאחר הפסח וכל שכן שכל אותו זמן אף מזכירים, ולדעת האחר, שיטת ר' יהודה היא שאין שואלים אלא עד הפסח וביום טוב הראשון של פסח בשחרית עדיין מזכירים ופוסקים במוסף.","\u0003רב יוסף אמר:\u0004 יש להסביר את הדבר באופן אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד שיעבור הפסח\"\u0004 — כוונתו: \u0003עד שיעבור שליח צבור ראשון\u0004 (המתפלל שחרית) \u0003היורד\u0004 לפני התיבה \u0003ביום טוב ראשון של פסח.\u0004 ועל ידי הסבר זה הדברים במשנה ובברייתא זהים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: שאלה ביום טוב מי איכא\u0004 \u0005[האם יש]?\u0006 שהרי שאלת הגשם היא בברכת השנים, וברכת השנים אינה נאמרת לא בשבת ולא ביום טוב. ואם מפרשים אנו שמדובר כאן בפסח במשמעות הרחבה של כל החג כולו — הרי יש בו ימי חול המועד שבהם מברכים ברכת השנים, אבל אם, כדבריך, מדובר ביום החג הראשון, היכן אם כן יש בו מקום לשאלה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 ולא מדובר בשאלה בתפילה אלא \u0003שואל מתורגמן.\u0004 שהמתורגמן המתרגם את הפרשה, היה שואל אחרי התפילה גם על הגשמים. ותוהים: \u0003וכי\u0004 ה\u0003מתורגמן שואל דבר שאינו צריך לצבור?\u0004 שהרי בפסח כבר אין צריכים לגשמים, ולשם מה יאמר המתורגמן דבר שאינו בזמנו? \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005],\u0006 \u0003כ\u0004דברי \u0003עולא,\u0004 שיש פה מחלוקת תנאים כשיטת ר' יהודה.","\u0003רבה אמר\u0004 הסבר אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד שיעבור הפסח\"\u0004 — כוונתו \u0003עד שיעבור זמן שחיטת הפסח\u0004 (חצות יום ארבעה עשר בניסן), שבמנחה של ערב פסח כבר אינו שואל, אף על פי שממשיך להזכיר עד שחרית של יום חמישה עשר בניסן. ולשיטה זאת \u0003כתחילתו כן סופו,\u0004 שאנו נוהגים מנהג דומה בתחילה ובסוף זמן התפילה על הגשם, \u0003מה תחילתו,\u0004 במוסף של יום טוב האחרון של חג הסוכות, \u0003מזכיר אף על פי שאינו שואל, אף סופו,\u0004 בשחרית יום טוב הראשון של פסח, \u0003מזכיר אף על פי שאינו שואל\u0004 עוד, שאת השאלה מפסיקים קודם ליל פסח, אבל מזכירים עוד בתפילת השחר למחרת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בשלמא\u0004 \u0005[נניח]\u0006 \u0003תחילתו מזכיר\u0004 לפני ששואל, כי \u0003הזכרה נמי\u0004 \u0005[גם כן]\u0006 \u0003ריצוי שאלה היא,\u0004 שההזכרה בתחילה באה לריצוי פני ה' כדי שיוכל אחר כך לשאול ולבקש, \u0003אלא סופו מאי\u0004 \u0005[מה]\u0006 \u0003ריצוי שאלה איכא\u0004 \u0005[יש\u0006 כאן\u0005]?\u0006 ואם אינו רוצה לשאול לאחריה גשמים — לשם מה יזכיר אותם? \u0003אלא מחוורתא\u0004 \u0005[מחוור\u0006 וברור\u0005]\u0006 \u0003כ\u0004דברי \u0003עולא.\u0004","\u0003אמר ר' אסי אמר ר' יוחנן: הלכה כר' יהודה,\u0004 שהמתפלל מוסף ביום טוב האחרון של חג הסוכות מתחיל להזכיר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בשלשה במרחשוון שואלין את הגשמים, רבן גמליאל אומר: בשבעה בו. ואמר ר' אלעזר\u0004 שהוא תלמידו המובהק של ר' יוחנן: \u0003הלכה כרבן גמליאל!\u0004","\u0003אמר\u0004 לו: \u0003גברא אגברא קא רמית\u0004 \u0005[\u0006מ\u0005אדם\u0006 אחד \u0005על אדם\u0006 אחר \u0005אתה משליך,\u0006 מקשה\u0005]?!\u0006 ואף שהיה ר' אלעזר תלמידו של ר' יוחנן אין זאת אומרת ששיטותיהם צריכות להיות תמיד זהות. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003כאן,\u0004 כשפסק ר' אלעזר, היה זה לענין \u0003לשאול,\u0004 ואכן אף לפי ר' יוחנן אין שואלים אלא בשבעה בחשוון, \u0003כאן\u0004 בדברי ר' יוחנן הרי זה לענין \u0003להזכיר,\u0004 ולדבריו אכן מתחיל להזכיר כבר ביום טוב האחרון של חג הסוכות.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: במקום ששואל מזכיר,\u0004 משמע שאין הבדל בזמן בין זה לזה! ומשיבים: \u0003ההיא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003ל\u0004ענין \u0003הפסקה איתמר\u0004 \u0005נאמר],\u0006 שאז אין הבדל בין שאלה והזכרה, ומפסיקים להזכיר ולשאול באותו זמן. ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: התחיל להזכיר\u0004 — \u0003מתחיל לשאול, פסק מלשאול\u0004 — \u0003פוסק מלהזכיר.\u0004 הרי שאף לענין תחילת זמן הזכרתם דינם זהה!","\u0003אלא\u0004 יש לחזור מהתירוץ הקודם ולומר: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא לן\u0004 \u0005[זו\u0006 \u0005לנו]\u0006 לבני בבל, שאין אנו אוספים את התבואה והפירות מן השדות כל חודש תשרי, לכך איננו מזכירים את הגשמים אלא בשבעה בחשוון ואז גם מתחילים לשאול, \u0003והא להו\u0004 \u0005[וזו להם]\u0006 לבני ארץ ישראל, שהם אוספים את התבואה מן השדות כבר בתשרי, לכן הם מתחילין להזכיר כבר ביום טוב האחרון של חג הסוכות וכשיטת רב יהודה, שפסק ר' אסי הלכה כמותו. ושואלים: \u0003מאי שנא לדידן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005לנו],\u0006 לבני בבל, שאין שואלים מיד אחר החג — \u0003דאית לן פירי בדברא\u0004 \u0005[שיש לנו פירות בשדה]\u0006 עדיין, ואין אנחנו רוצים שירד הגשם מיד לאחר החג, \u0003לדידהו נמי אית להו\u0004 \u0005[להם,\u0006 לבני ארץ ישראל, \u0005גם כן\u0006 הלא \u0005יש להם]\u0006 \u0003עולי רגלים,\u0004 שצריכים ללכת עוד זמן ניכר אחר החג עד שיגיעו לביתם, ואינם רוצים להתפלל שירדו גשמים עליהם!","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 היה זה \u0003בזמן שאין בית המקדש קיים,\u0004 שאז יכולים בני ארץ ישראל להתפלל מיד על הגשם. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 לתירוץ זה, אפשר לומר \u0003הא והא לדידהו\u0004 \u0005[זה וזה\u0006 נאמר \u0005להם]\u0006 לבני ארץ ישראל, \u0003ולא קשיא\u0004 \u0005[ואין זה קשה],\u0006 כי \u0003כאן\u0004 מדובר \u0003בזמן שבית המקדש קיים,\u0004 אכן אין שואלים אלא בשבעה בחשוון, \u0003כאן\u0004 — \u0003בזמן שאין בית המקדש קיים,\u0004 שואלים מיד לאחר החג.","ושואלים: \u0003ואנן\u0004 \u0005[ואנחנו]\u0006 בני הגולה, \u0003דאית לן תרי יומי היכי עבדינן\u0004 \u0005[שיש לנו שני ימים\u0006 של שמיני עצרת \u0005כיצד אנו עושים]\u0006 לענין הזכרת הגשמים? שהרי שמיני עצרת בחוץ לארץ הוא ספק שביעי של סוכות! \u0003אמר רב: מתחיל\u0004 להזכיר גשם \u0003במוספין\u0004 ביום הראשון של שמיני עצרת, \u0003ופוסק\u0004 לומר \u0003במנחה\u0004 ו\u0003ערבית\u0004 של אותו יום \u0003ו\u0004כן ב\u0003שחרית\u0004 שלמחרת מחמת הספק, שהרי יום שמיני בגולה הוא ספק שמיני ספק שביעי, \u0003וחוזר\u0004 שוב לומר \u0003במוספין\u0004 של היום השני של החג (שמחת תורה).","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמואל\u0004 לאנשים שמסרו לו דברי רב: \u0003פוקו\u0004 \u0005[צאו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לאבא\u0004 (שמו הפרטי של רב): וכי \u0003אחר שעשיתו\u0004 את היום הראשון \u0003קודש\u0004 תחזור ו\u0003תעשהו חול\u0004 ותחשוב כאילו איננו יום החג? \u0003אלא אמר שמואל: מתחיל במוספין ו\u0004מזכיר גם \u0003במנחה\u0004 שלאחר מכן, \u0003ופוסק ערבית ושחרית,\u0004 שהרי גם בארץ ישראל אין מזכירים גשם בערבית ושחרית של שמיני עצרת \u0003וחוזר ומתחיל במוספין\u0004 שביום השני."],["\u0003רבא אמר: כיון שהתחיל — שוב אינו פוסק, וכן אמר רב ששת: כיון שהתחיל שוב אינו פוסק\u0004 ולכן מתחילים במוסף ביום הראשון של שמיני עצרת, וממשיכים ואומרים מאז והלאה.","\u0003ואף רב הדר ביה\u0004 \u0005[חזר בו\u0006 מדבריו\u0005].\u0006 ש\u0003אמר רב חננאל אמר רב: מונה עשרים ואחד יום\u0004 מראש השנה \u0003כדרך שמונה עשרה ימים מראש השנה עד יום הכפורים, ומתחיל\u0004 אחרי עשרים ואחד יום להזכיר את הגשמים, \u0003וכיון שהתחיל\u0004 — \u0003שוב אינו פוסק,\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא: \u0003כיון שהתחיל שוב אינו פוסק.\u0004","\u0003עד מתי שואלין את הגשמים? ר' יהודה אומר:\u0004 שואלים אותם \u0003עד שיעבור הפסח, ר' מאיר אומר: עד שיצא\u0004 כל חודש \u0003ניסן,\u0004 וראיה לדבר, ממה \u0003שנאמר: \"ויורד לכם גשם מורה ומלקוש בראשון\"\u0004 (יואל ב, כג), כלומר, ירד הגשם בחודש הראשון, חודש ניסן, משמע שהוא זמן גשמים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק:\u0004 וכי \u0003יורה\u0004 (\"מורה... בראשון\") \u0003בניסן?\u0004 הלא \u0003יורה במרחשון הוא! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יורה במרחשון ומלקוש בניסן! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 אכן היורה בחשוון הוא, וענין כתוב זה יש לומר כי \u0003בימי יואל בן פתואל\u0004 הנביא \u0003נתקיים מקרא זה, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"יתר הגזם אכל הארבה\" וגו'\u0004 (יואל א, ד), ולא נשארה בידם תבואה כלל. \u0003אותה שנה יצא\u0004 חודש \u0003אדר ולא ירדו גשמים\u0004 כל השנה, \u0003ירדה להם רביעה\u0004 (עונת גשמים) \u0003ראשונה באחד בניסן,\u0004","\u0003אמר להם נביא לישראל: צאו וזרעו\u0004 עכשיו! \u0003אמרו לו: מי שיש לו קב חטים או קבים שעורין\u0004 שנשארו עדיין בידו \u0003יאכלנו ויחיה\u0004 בהם, \u0003או יזרענו וימות?\u0004 כלומר, חבל לנו לזרוע, שספק הוא אם תצמח התבואה, ומזון ההכרחי לנו מוטב שנאכלנו. \u0003אמר להם: אף על פי כן צאו וזרעו, נעשה להם נס ונתגלה להם מה שבכתלין ומה שבחורי נמלים,\u0004 שהיו שם עוד גרגירי חיטה ושעורה שהחביאו העכברים.","\u0003יצאו וזרעו\u0004 ביום \u0003שני ושלישי ורביעי\u0004 בניסן, \u0003וירדה להם רביעה שניה בחמשה בניסן,\u0004 וצמחה התבואה מהר כל כך עד ש\u0003הקריבו עומר בששה עשר בניסן, נמצאת תבואה הגדילה\u0004 כרגיל \u0003בששה חדשים, גדילה\u0004 אז \u0003באחד עשר יום. נמצא עומר הקרב מתבואה של ששה חדשים קרב\u0004 באותה שנה \u0003מתבואה של אחד עשר יום.\u0004","\u0003ועל אותו הדור הוא אומר: \"הזרעים בדמעה ברנה יקצרו. הלוך ילך ובכה נשא משך הזרע\u0004 בא יבוא ברנה נושא אלומותיו\u0003\"\u0004 (תהלים קכו, ה-ו), שמאחר וכמעט לא היה להם מה לאכול, הרי שאת המעט שהיה בידם זרעו בדמעה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הלוך ילך ובכה נשא משך\u0004 הזרע \u0003\"? אמר ר' יהודה: שור כשהוא חורש — הולך ובוכה\u0004 שהרי הוא מצטער בעבודתו, \u0003ובחזירתו\u0004 באותו תלם כבר \u0003אוכל חזיז\u0004 (שחת, עשבים) מהתבואה הצומחת \u0003מן התלם. וזהו\u0004 מה שנאמר: \u0003\"בא יבא ברנה\".\u0004","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נשא אלמתיו\"\u0004 בענין זה? \u0003אמר רב חסדא ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 ש\u0005בברייתא\u0006 היא \u0005שנויה],\u0006 שהצמח שהיה אז \u0003קנה\u0004 של שיבולת באורך \u0003זרת,\u0004 וה\u0003שיבולת\u0004 עצמה היתה \u0003זרתים\u0004 (שתי זרתות) שהם שתי אלומות (שבלים) כנגד כל קנה, ודבר זה הוא נס גדול, שהרי בדרך כלל אורך הקנה מגיע לכדי פי שלוש וארבע מן השיבולת עצמה.","אגב ביאורי מקראות אלה באים לבאר כמה פסוקים אחרים, מתחילה בענין הרעב, ואחר כך לשאלות אחרות של רב נחמן לרבי יצחק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי קרא ה' לרעב וגם בא אל הארץ שבע שנים\"\u0004 (מלכים ב' ח, א), \u0003בהנך\u0004 \u0005[באותן]\u0006 \u0003שבע שנים מאי אכול\u0004 \u0005[מה אכלו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: שנה ראשונה אכלו מה שבבתים,\u0004 שנה \u0003שניה אכלו מה שבשדות, שלישית\u0004 אכלו \u0003בשר בהמה טהורה\u0004 שנותרה, \u0003רביעית\u0004 אכלו \u0003בשר בהמה טמאה, חמישית\u0004 אכלו \u0003בשר שקצים ורמשים\u0004 שמצאו, \u0003ששית\u0004 אכלו \u0003בשר בניהם ובנותיהם, שביעית\u0004 אכלו \u0003בשר זרועותיהם\u0004 שלהם, \u0003לקיים מה שנאמר: \"איש בשר זרעו יאכלו\"\u0004 (ישעיהו ט, יט).","\u0003ו\u0004עוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה פירוש הכתוב: \u0003\"בקרבך קדוש ולא אבוא בעיר\"\u0004 (הושע יא, ט), והרי תמוה הוא: \u0003משום\u0004 ש\u0003בקרבך קדוש\u0004 לכן \u0003לא אבוא בעיר? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אמר הקדוש ברוך הוא לא אבוא בירושלים של מעלה\u0004 (שבעולם העליון) \u0003עד שאבוא\u0004 בזמן הגאולה \u0003לירושלים של מטה!\u0004","ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003ירושלים למעלה?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ירושלים הבנויה כעיר שחברה לה יחדו\"\u0004 (תהלים קכב, ג), משמע שירושלים עיר כפולה היא, למעלה ולמטה, והן מתחברות כאחת.","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' נחמן לר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה פירוש הכתוב: \u0003\"ובאחת יבערו ויכסלו מוסר הבלים עץ הוא\"\u0004 (ירמיהו י, ח)? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אחת היא\u0004 העבירה \u0003שמבערת רשעים בגיהנם, מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 עבירה זו — \u0003עבודה זרה.\u0004 וראיה לדבר, מגזירה שווה: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"מוסר הבלים עץ הוא\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 על הפסילים והאלילים: \u0003\"הבל המה מעשה תעתעים\"\u0004 (ירמיהו י, טו).","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה פירוש הכתוב: \u0003\"כי שתים רעות עשה עמי\"\u0004 (ירמיהו ב, יג) \u0003תרתין הוא דהוו\u0004 \u0005[שתים הן שהיו]\u0006 שעברו עליהם? ושאר \u0003עשרין וארבע\u0004 המנויות בספר יחזקאל \u0003שביקא להו\u0004 \u0005[נעזבו,\u0006 הותרו \u0005להם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אחת שהיא\u0004"],["\u0003שקולה כשתים, ומאי ניהו\u0004 \u0005[ומה זו]\u0006 — \u0003עבודה זרה, דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"כי שתים רעות עשה עמי אתי עזבו מקור מים חיים לחצב להם בארות בארות נשברים\"\u0004 (ירמיהו ב, יג). \u0003וכתיב בהו\u0004 \u0005[ונאמר בהם]\u0006 בישראל \u0003\"כי עברו איי כתיים וראו וקדר שלחו והתבוננו מאד\u0004 וראו הן היתה כזאת. \u0003ההימיר גוי אלהים והמה לא אלהים ועמי המיר כבודו בלוא יועיל\"\u0004 (ירמיהו י-יא).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005],\u0006 שכוונת הנביא לומר כך: \u0003כותיים\u0004 (תושבי איי כתים) \u0003עובדים לאש, וקדריים\u0004 (הגרים בקדר) \u0003עובדין למים, ואף על פי שיודעים שהמים מכבין את האש\u0004 מכל מקום \u0003לא המירו אלהיהם, ו\u0004אולם \u0003\"עמי המיר כבודו בלוא יועיל\".\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה פירוש הכתוב: \u0003\"ויהי כאשר זקן שמואל\"\u0004 (שמואל א' ח, א) \u0003ומי סיב\u0004 \u0005[והאם זקן]\u0006 \u0003שמואל כולי האי\u0004 \u0005[כל כך]?\u0006 \u0003והא בר חמישים ותרתין הוה\u0004 \u0005[והלא בן חמישים ושתים\u0006 שנה \u0005היה]\u0006 שמואל במותו, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מי ש\u0003מת\u0004 בן \u0003חמישים ושתים שנה —\u0004 אין זה סימן רע לו, שאין זו מיתה בקיצור שנים כעין מיתת כרת, כי \u0003זהו מיתתו של שמואל הרמתי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: זקנה קפצה עליו,\u0004 על שמואל, שהלבין שערו ונראה היה זקן מגילו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נחמתי כי המלכתי את שאול\u0004 למלך כי שב מאחרי ואת דברי לא הקים ויחר לשאול ויזעק אל ה' כל הלילה\u0003\"\u0004 (שמואל א' טו, יא). \u0003אמר לפניו\u0004 שמואל: \u0003רבונו של עולם!\u0004 אתה \u0003שקלתני כמשה ואהרן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"משה ואהרן בכהניו ושמואל בקראי שמו\"\u0004 (תהלים צט, ו), \u0003מה משה ואהרן — לא בטלו מעשה ידיהם\u0004 בחייהם, שמה שעשו, נשאר על כל פנים קיים \u0003בחייהם, אף אני לא יתבטל מעשה ידי בחיי\u0004 וכיון שהמלכתי את שאול — לא תתבטל מלכותו.","\u0003אמר הקדוש ברוך הוא: היכי אעביד\u0004 \u0005[איך אעשה]?\u0006 \u0003לימות\u0004 \u0005[שימות]\u0006 \u0003שאול\u0004 עכשיו — \u0003לא קא שביק\u0004 \u0005[יניח]\u0006 לי \u0003שמואל\u0004 לעשות כן, שהרי הוא מתפלל שלא ימות, \u0003לימות\u0004 \u0005[שימות]\u0006 \u0003שמואל אדזוטר\u0004 \u0005[\u0006בעודו \u0005צעיר]\u0006 וימות שאול מיד אחר כך — \u0003מרנני אבתריה\u0004 \u0005[ירננו\u0006 אנשים \u0005אחריו]\u0006 שמא עבירה שהיתה בשמואל גרמה שימות בקיצור ימים. \u0003לא לימות\u0004 \u0005[ימות]\u0006 \u0003שאול ולא לימות\u0004 \u0005[ימות]\u0006 \u0003שמואל,\u0004 הרי \u0003כבר הגיעה\u0004 תקופת \u0003מלכות דוד, ואין מלכות נוגעת בחברתה\u0004 ונוטלת ממנה \u0003אפילו כמלא נימה\u0004 (חוט).","\u0003אמר הקדוש ברוך הוא: אקפיץ עליו זקנה,\u0004 שילבינו שערותיו ויחשבו כולם שהוא זקן מאוד. \u0003היינו דכתיב\u0004 \u0005[\u0006ו\u0005הוא שנאמר]:\u0006 \u0003\"ושאול יושב בגבעה תחת האשל ברמה\"\u0004 (שמואל א' כב, ו), \u0003ו\u0004לכאורה: \u0003כי מה ענין גבעה\u0004 (גבעת בנימין) \u0003אצל רמה\u0004 (הר אפרים), שהרי אינן באותו מקום? \u0003אלא לומר לך: מי גרם לשאול שישב בגבעה שתי שנים ומחצה — תפלתו של שמואל הרמתי.\u0004","ושואלים: \u0003ומי מידחי גברא מקמי גברא\u0004 \u0005[האם נדחה אדם בפני אדם]?\u0006 כלומר, האם משום שהגיע זמנו של דוד למלוך יידחה שמואל מלפניו? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 הוא, ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"על כן חצבתי בנביאים הרגתים באמרי פי\"\u0004 (הושע ו, ה) \u0003\"במעשיהם\" — לא נאמר, אלא \"באמרי פי\",\u0004 משמע, שפעמים בגלל גזירת ה' (\"אמרי פי\") חייב אדם למות, אף אם אין מעשיו מצדיקים זאת, \u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003מידחי גברא מקמי גברא\u0004 \u0005[\u0006ש\u0005נדחה אדם בפני אדם].\u0006","אגב שאלות אלה של רב נחמן לר' יצחק, מסופר עוד: \u0003רב נחמן ור' יצחק הוו יתבי בסעודתא\u0004 \u0005[היו יושבים בסעודה]\u0006 ואוכלים יחד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לר' יצחק: לימא מר מילתא\u0004 \u0005[יאמר אדוני דבר\u0006 תורה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אין מסיחין\u0004 (מדברים) \u0003ב\u0004זמן ה\u0003סעודה, שמא יקדים קנה לושט\u0004 שהרי האוכל נכנס לושט, אבל תוך כדי שיחה נפתח גם הקנה, ויכול להיכנס לתוכו מאכל \u0003ויבא לידי סכנה\u0004 של חנק.","\u0003בתר דסעוד\u0004 \u0005[אחרי שסעדו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: יעקב אבינו לא מת. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בתמיהה: \u0003וכי בכדי\u0004 \u0005[לחינם]\u0006 \u0003ספדו ספדניא וחנטו חנטייא וקברו קברייא\u0004 \u0005[ספדו הספדנים וחנטו החונטים וקברו הקוברים]?\u0006 שהרי לדבריך יעקב אבינו לא מת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מקרא אני דורש, שנאמר: \"ואתה אל תירא עבדי יעקב נאם ה' ואל תחת ישראל כי הנני מושיעך מרחוק ואת זרעך מארץ שבים\"\u0004 (ירמיהו ל, י), \u0003מקיש\u0004 (משווה) בפסוק זה \u0003הוא לזרעו, מה זרעו בחיים — אף הוא בחיים,\u0004 משמע שהוא עצמו לא מת.","ועוד \u0003אמר ר' יצחק: כל האומר \"רחב\" \"רחב\" מיד נקרי\u0004 \u0005[רואה קרי]\u0006 מחמת תאווה, ללמד כמה יפה היתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: אנא אמינא\u0004 \u0005[אני אומר]\u0006 \"רחב\" \u0003ולא איכפת לי,\u0004 שלי אין הזכרה זו גורמת דבר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי קאמינא\u0004 \u0005[כאשר אמרתי]\u0006 זאת, הרי זה דווקא \u0003ב\u0004אדם שהיה \u0003יודעה ומכירה,\u0004 שכיון שהכירוה פעם, הרי הזכרת שמה בלבד גרמה להם להתאוות לה.","ומסופר: \u0003כי הוו מיפטרי מהדדי\u0004 \u0005[כאשר נפרדו זה מזה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבי יצחק: \u0003ליברכן מר\u0004 \u0005[יברכני אדוני]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי יצחק: \u0003אמשול לך משל, למה הדבר דומה? לאדם שהיה הולך במדבר והיה רעב ועיף וצמא, ומצא\u0004 שם \u0003אילן שפירותיו מתוקין וצלו נאה, ואמת\u0004 (תעלת) \u0003המים עוברת תחתיו. אכל מפירותיו\u0004 של אותו אילן, \u0003ושתה ממימיו\u0004 של המעין \u0003וישב בצילו\u0004 של האילן.","\u0003וכשביקש לילך, אמר: אילן אילן, במה אברכך? אם אומר לך שיהו פירותיך מתוקין\u0004 — \u0003הרי\u0004 כבר \u0003פירותיך מתוקין, שיהא צילך נאה — הרי צילך נאה, שתהא אמת המים עוברת תחתיך — הרי אמת המים\u0004 כבר \u0003עוברת תחתיך, אלא\u0004 ברכה זו אברכך: \u0003יהי רצון שכל נטיעות שנוטעין ממך\u0004"],["\u0003יהיו כמותך. אף אתה\u0004 שרוצה בברכה ממני, \u0003במה אברכך? אם בתורה — הרי\u0004 יש לך \u0003תורה, אם בעושר — הרי עושר, אם בבנים הרי\u0004 יש לך \u0003בנים, אלא יהי רצון שיהיו צאצאי מעיך כמותך.\u0004","ושוב לענין הגשמים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"ונתתי מטר ארצכם בעתו יורה ומלקוש\" (דברים יא, יד), \u0003\"יורה\"\u0004 נקרא על שום \u0003שמורה\u0004 (מלמד) \u0003את הבריות\u0004 שעליהם \u0003להטיח\u0004 (לשים טיח) על \u0003גגותיהן\u0004 ולסתום את הסדקים בהם, \u0003ולהכניס את פירותיהן\u0004 מן השדות לבתים, \u0003ולעשות כל צרכיהן,\u0004 לפני שיבואו גשמים מרובים. \u0003דבר אחר:\u0004 נקרא \"יורה\" משום \u0003שמרוה את הארץ ומשקה עד תהום, שנאמר: \"תלמיה רוה נחת גדודה ברביבים תמגגנה צמחה תברך\"\u0004 (תהלים סה, יא). \u0003דבר אחר: \"יורה\"\u0004 כוונתו \u0003שיורד בנחת ואינו יורד בזעף.\u0004","\u0003או אינו \"יורה\" אלא\u0004 משום שיורד בזעף באופן \u0003שמשיר את הפירות\u0004 שבאילן \u0003ומשטיף את הזרעים\u0004 שבשדות ממקומם \u0003ומשטיף\u0004 (מלשון יריה) \u0003את האילנות?\u0004 — \u0003תלמוד לומר: \"מלקוש\", מה מלקוש\u0004 אי אפשר לפרשו לרעה, שהוא משבר את גרנות ומשיר את הפירות, שהרי בזמן שהוא יורד אין אלו בנמצא, ואין לך לפרשו אלא \u0003לברכה — אף יורה\u0004 אין לך לפרשו אלא \u0003לברכה. או אינו אלא \"מלקוש\"\u0004 — שירד גשם עז \u0003שמפיל את הבתים ומשבר את האילנות ומעלה את הסקאין\u0004 (החגבים)? — \u0003תלמוד לומר: \"יורה\",\u0004 וכוונתו: \u0003מה יורה לברכה\u0004 — \u0003אף מלקוש לברכה.\u0004","ושואלים: \u0003ויורה גופיה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שהוא לברכה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובני ציון גילו ושמחו בה' אלהיכם כי נתן לכם את המורה לצדקה ויורד לכם גשם מורה ומלקוש בראשון\"\u0004 (יואל ב, כג), הרי נאמר בפסוק זה שהיורה (\"מורה\") הוא לצדקה, הוה אומר שהוא לברכה בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת באותו ענין: זמן ה\u0003יורה\u0004 הוא \u0003במרחשון, ומלקוש\u0004 זמנו \u0003בניסן. אתה אומר יורה במרחשון ומלקוש בניסן, או אינו אלא יורה בתשרי ומלקוש באייר? תלמוד לומר \"\u0004ונתתי מטר ארצכם \u0003בעתו\"\u0004 והעת הראויה ליורה היא בחשוון, שהיא העונה שבה צריכים לגשמים כדי להצמיח את התבואה, ולמלקוש בניסן.","ובפירוש המלה \u0003\"מלקוש\" אמר רב נהילאי בר אידי אמר שמואל: דבר שמל קשיותיהן של ישראל,\u0004 כלומר: דבר שחותך את קשי לבם של ישראל, שכשאינו יורד בזמנו חוזרים ישראל בתשובה. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \"מלקוש\" נקרא כך, משום שהוא \u0003דבר שממלא\u0004 את ה\u0003תבואה בקשיה,\u0004 כלומר, אף שיש כבר קש, הרי התבואה גדלה עוד קצת ומתמלאה בתוכו. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003דבר שיורד על המלילות ועל הקשין\u0004 (מל־קוש).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 זמן ה\u0003יורה\u0004 הוא \u0003במרחשון ומלקוש בניסן. אתה אומר יורה במרחשון, או אינו אלא בחדש כסליו? תלמוד לומר: \"\u0004ונתתי מטר ארצכם \u0003בעתו יורה ומלקוש\"\u0004 (דברים יא, יד), \u0003מה מלקוש בעתו — אף יורה בעתו,\u0004 ומלקוש הרי אמרנו שהוא יורד על הקשים, משמע — בעתו, ש\u0003כיון שיצא ניסן וירדו גשמים — אינו סימן ברכה\u0004 אלא להיפך, וכמו כן עתו של היורה, כלומר, הזמן הראוי לו, הוא בחשוון.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003יורה במרחשון ומלקוש בניסן,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: יורה\u0004 זמנו \u0003בכסליו.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה? \u0003אמר רב חסדא: ר' יוסי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזו היא רביעה\u0004 (עונת גשמים) \u0003ראשונה\u0004 — אין זמניה קבועים תמיד, אלא \u0003הבכירה,\u0004 כלומר, המוקדמת ביותר היא כשמגיעה \u0003בשלשה במרחשון, בינונית\u0004 מגיעה \u0003בשבעה בו, אפילה\u0004 (מאוחרת) — \u0003בשבעה עשר בו,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בשבעה\u0004 בחשוון היא הבכירה, \u0003ובשבעה עשר\u0004 בו היא הבינונית, \u0003ובעשרים ושלשה\u0004 בו היא האפילה.","\u0003ר' יוסי אומר:\u0004 הרביעה הראשונה זמנה \u0003בשבעה עשר, ובעשרים ושלשה\u0004 במרחשון, \u0003ובראש חדש כסליו. וכן היה ר' יוסי אומר: אין היחידים,\u0004 הם תלמידי החכמים שמקדימים להתפלל לפני הציבור ולבקש על הגשמים, \u0003מתענין\u0004 על הגשמים \u0003עד שיגיע ראש חדש כסליו,\u0004 שהרי עד אז הוא עדיין בתוך זמנה של רביעה ראשונה.","\u0003אמר רב חסדא: הלכה כר' יוסי. אמימר מתני להא\u0004 \u0005[היה שונה את\u0006 השמועה \u0005הזו]\u0006 של \u0003רב חסדא בהא לישנא\u0004 \u0005[בלשון זו]\u0006 ששנינו: \u0003בשלשה במרחשון שואלין את הגשמים, רבן גמליאל אומר: בשבעה בו,\u0004 ועל כך \u0003אמר רב חסדא: הלכה כרבן גמליאל.\u0004","ושואלים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 \u0003הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו],\u0006 \u0003רבן שמעון בן גמליאל אומר: גשמים שירדו שבעה ימים זה אחר זה אתה מונה בהם רביעה ראשונה ושניה ושלישית,\u0004 כלומר, שהם נחשבים לשתי רביעות, או ראשונה ושניה או שניה ושלישית, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 שהרי רק הוא עושה רווח זמן קבוע של שבעה ימים בין רביעה לרביעה, \u0003אמר רב חסדא: הלכה כר' יוסי.\u0004","לעצם קביעת זמני הרביעה שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שמזכירים ויודעים את זמנה של ה\u0003רביעה\u0004 ה\u0003ראשונה —\u0004 הרי זה \u0003לשאול,\u0004 כדי לדעת מהו הזמן הראוי להתפלל על הגשמים (\"ותן טל ומטר\"). זמנה של רביעה \u0003שלישית\u0004 צריכים לדעת — כדי \u0003להתענות,\u0004 שאם לא ירדו גשמים עד זמן רביעה שלישית — צריך להתענות. אולם זמן רביעה \u0003שניה למאי\u0004 \u0005[למה],\u0006 לאיזו צורך הוזכרה? \u0003אמר ר' זירא: ל\u0004ענין \u0003נדרים, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003הנודר\u0004 נדר מסויים ואוסר דבר על עצמו \u0003עד הגשמים\u0004 — הרי זמן הנדר \u0003משירדו\u0004 ה\u0003גשמים\u0004 ובדיוק \u0003עד שתרד רביעה שניה,\u0004 שאז בודאי קרוי הוא זמן הגשמים.","\u0003רב זביד אמר:\u0004 זמן רביעה שניה הוא לקבוע מועד \u0003ל\u0004ענין \u0003זיתים. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאימתי כל אדם מותרין בלקט בשכחה ובפאה\u0004 שכל אלה הן מתנות לעניים ואסור לכל אדם שאיננו עני ליטול מהם, אלא לאחר שאין עניים באים יותר לשדות ליטלן. וזמן זה לגבי לקט שכחה ופאה הוא מוגדר; \u0003משילכו הנמושות.\u0004 שלאחר שהנמושות שהם אחרוני העניים כבר עברו בשדה, ודאי שלא נותר דבר בשדה ומתייאשים שאר העניים ושוב אינם באים לאותם שדות, ומזמן זה והלאה מותר לכל אדם ליטול מהם. \u0003ובפרט ובעוללות\u0004 שהם מתנות עניים מן הגפנים — \u0003משילכו עניים בכרם ויבואו\u0004 פעם שניה, ואז ברור שנטלו כל מה שהם רוצים ליטול. \u0003בזיתים\u0004 — מותר לכל אדם \u0003משתרד רביעה שניה.\u0004","כיון שהוזכרה מלה לא מובנת במשנה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נמושות\"? אמר ר' יוחנן: סבי דאזלי אתיגרא\u0004 \u0005[זקנים שהולכים על מקל]\u0006 וכיון שהם מהלכים לאיטם ודאי ראו כל דבר, ונטלו כל צרכם. \u0003ריש לקיש אמר:\u0004 \"נמושות\" אלה הם \u0003לקוטי בתר לקוטי\u0004 \u0005[המלקטים אחר המלקטים].\u0006","\u0003רב פפא אמר\u0004 שצריך לדעת זמן רביעה שניה, \u0003כדי\u0004 לדעת עד מתי מותר \u0003להלך בשבילי הרשות.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מהלכין כל אדם בשבילי הרשות\u0004 שבילים שבתוך השדות, שאינן דרך הרבים, אלא שמותר (כאחד מן התנאים שהתנה יהושע לישראל טרם בואם לארץ) ללכת בהם כל זמן שאין בכך נזק לשדה — \u0003עד שתרד רביעה שניה,\u0004 שאם הולך אז הריהו דורס על האדמה החרושה ומזיק לצמחים.","\u0003רב נחמן בר יצחק אמר:\u0004 זמן רביעה שניה נחוץ כדי לדעת מתי \u0003לבער פירות שביעית\u0004 מרשותו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עד מתי נהנין ושורפין בתבן ובקש של שביעית\u0004 — \u0003עד שתרד רביעה שניה.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בשנת השמיטה: \u0003\"ולבהמתך ולחיה אשר בארצך\u0004 תהיה כל תבואתה לאכול\u0003\"\u0004 (ויקרא כה, ז), ולמדים מכאן: \u0003כל זמן שחיה אוכלת בשדה,\u0004 שאותם פירות מצויים גם בשדות — \u0003האכל\u0004 מאותו מין גם \u0003לבהמתך בבית,\u0004 אולם אם \u0003כלה\u0004 מין זה \u0003לחיה מן השדה\u0004 שצמחים אלה כבר אינם מצויים בשדה — \u0003כלה\u0004 גם \u0003לבהמתך מן הבית,\u0004 ואחר זמן רביעה שניה שוב אין התבן מצוי בשדות.","ולענין הגשמים בכלל. \u0003אמר ר' אבהו: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לשון \"רביעה\"\u0004 בגשמים — כוונתו: \u0003דבר שרובע\u0004 (בועל) \u0003את הקרקע,\u0004 ומפרה אותה. ו\u0003כ\u0004דברי \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: מיטרא\u0004 \u0005[הגשם]\u0006 \u0003בעלה דארעא\u0004 \u0005[של הקרקע]\u0006 \u0003הוא, שנאמר: \"כי כאשר ירד הגשם והשלג מן השמים ושמה לא ישוב כי אם הרוה את הארץ והולידה והצמיחה\"\u0004 (ישעיהו נה, י), משמע שהגשם הוא שמפרה את האדמה ובועלה כבעל לאשה.","\u0003ואמר ר' אבהו: רביעה ראשונה\u0004 שיעורה \u0003כדי שתרד בקרקע\u0004 ותירטב זו עד לעומק \u0003טפח\u0004 אחד. רביעה \u0003שניה\u0004 שיעורה \u0003כדי לגוף בה פי חבית,\u0004 שהאדמה מתרככת כל כך, שאפשר להשתמש בה כמו בטיט כדי לסתום את חיבור המגופה (הכיסוי) והחבית. \u0003אמר רב חסדא: גשמים שירדו כדי לגוף בהן פי חבית\u0004 — \u0003אין בהן משום\u0004 קללת \u0003\"ועצר\u0004 את השמים\u0003\".\u0004 כלומר, אם ירדו גשמים בכמות זו, כבר אין לומר שבאותה שנה נתקיים \"ועצר את השמים ולא יהיה מטר\" (דברים יא, יז).","\u0003ואמר רב חסדא: גשמים שירדו קודם \"ועצר\",\u0004 כלומר, גשם שירד עוד לפני שקראו בקריאת שמע את הפסוק \"ועצר את השמים\", שוב \u0003אין בהן משום \"ועצר\u0004 את השמים\u0003\",\u0004 גם אם לא ירדו גשמים נוספים.","\u0003אמר אביי: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה, \u0003אלא קודם \"ועצר\" דאורתא\u0004 \u0005[של הערב],\u0006 כלומר שירדו ביום, קודם זמן קריאת שמע של הערב, \u0003אבל קודם \"ועצר\" דצפרא\u0004 \u0005[של הבוקר] —\u0006 \u0003יש בהם משום \"ועצר\",\u0004 שכן \u0003אמר רב יהודה בר יצחק: הני ענני דצפרא לית בהו מששא\u0004 \u0005[אלה, ענני הבוקר, אין בהם ממש],\u0006 שאינם מורידים גשמים, או שמורידים רק גשם מועט. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מה אעשה לך אפרים מה אעשה לך יהודה וחסדכם כענן בקר\"\u0004 (הושע ו, ד), משמע שענן כזה אין בו ממש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: והא אמרי אינשי\u0004 \u0005[והרי אומרים אנשים]\u0006 והוא מקובל בידם: \u0003במפתח בבי מיטרא\u0004 \u0005[כאשר פותחים את הדלתות\u0006 בבוקר ויורד \u0005גשם] —\u0006 \u0003בר חמרא, מוך שקך וגני\u0004 \u0005[החמר, קפל את שקך ולך לישון],\u0006 שודאי ירד גשם כל היום כולו, ותהיה זו שנה ברוכה בגשמים ויהיה מחיר התבואה זול ולא ירוויח החמר ממכירה אלא מעט. משמע שענני בוקר מביאים גשמים לכל היום כולו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא דקטיר בעיבא\u0004 \u0005[כאן\u0006 \u0005שנקשרו\u0006 שמים \u0005בעב]\u0006 ענן אפל וכבד — יירד גשם כל היום, \u0003הא דקטיר בענני\u0004 \u0005[זה שנקשרו\u0006 שמים \u0005בעננים]\u0006 קלים שלא יהא גשם אחריהם.","\u0003אמר רב יהודה: טבא לשתא\u0004 \u0005[טוב לשנה]\u0006 שבה חודש \u0003טבת\u0004 הוא \u0003ארמלתא\u0004 \u0005[אלמן],\u0006 כלומר, שאין גשמים יורדים בו. ומסבירים את טעם הדבר, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 ש\u0003לא ביירי תרביצי\u0004 \u0005[יוברו,\u0006 ייעשו שממה, \u0005הגנות],\u0006 שריבוי גשמים מזיק לירקות הגינה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 ש\u0003לא שקיל שודפנא\u0004 \u0005[יגיע שידפון]\u0006 מחמת ריבוי גשמים. ושואלים: \u0003איני\u0004 \u0005[האם כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: טבא לשתא\u0004 \u0005[טוב לשנה]\u0006 שבה חודש \u0003טבת\u0004 הוא \u0003מנוולתא\u0004 \u0005[מנוול],\u0006 כלומר, שהדרכים מלאים בוץ מחמת הגשמים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא דאתא מיטרא מעיקרא\u0004 \u0005[זה כשבא גשם מתחילה],\u0006 לפני חודש טבת, שאז לא טוב שירד גשם בטבת, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא אתא מיטרא מעיקרא\u0004 \u0005[בא הגשם מתחילה]\u0006 שאז טובה ירידת הגשם בטבת.","\u0003ואמר רב חסדא: גשמים שירדו על מקצת מדינה ועל מקצת מדינה לא ירדו\u0004 — \u0003אין בהן משום\u0004 קללת \u0003\"ועצר\u0004 את השמים \u0003\"\u0004. ותוהים: \u0003איני\u0004 \u0005[האם כך הוא]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וגם אנכי מנעתי מכם את הגשם בעוד שלשה חדשים לקציר והמטרתי על עיר אחת ועל עיר אחת לא אמטיר, חלקה אחת תמטר\u0004 וחלקה אשר לא תמטיר עליה תיבש\u0003\"\u0004 (עמוס ד, ז). \u0003ואמר רב יהודה אמר רב: שתיהן לקללה,\u0004 בין לגבי המקום שירד בו גשם ובין לגבי המקום שלא ירד בו הגשם. ועל כל פנים למדים מכאן שגשמים היורדים רק בחלק מן המדינה סימן קללה הם!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא דאתא טובא\u0004 \u0005[זה שבא\u0006 גשם \u0005הרבה\u0006 מאוד\u0005]\u0006 במקום אחד שמזיק, \u0003הא דאתא כדמבעי ליה\u0004 \u0005[זה שבא\u0006 כשיורד גשם \u0005כראוי לו]\u0006 אז אין לומר שהיא קללה, אלא שנתברך מקום אחד. \u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 מלשון הכתוב שמדובר על גשמים מרובים מדי במקום אחד, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"תמטר\"\u0004 שיש להבינו: \u0003תהא מקום מטר,\u0004 כלומר, מקום זה כולו מטר ומים, יותר מכפי הצורך. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר ר' אבהו: מאימתי מברכין על הגשמים\u0004 ברכת הודאה — \u0003משיצא חתן לקראת כלה.\u0004 כלומר, שיורדים גשם בכמות כזו שלעומת הטיפות היורדות קופצות כנגדן טיפות מהשלוליות שבקרקע.","ושואלים: \u0003מאי\u0004 \u0005[מה],\u0006 איזו ברכה \u0003מברך\u0004 על הגשמים? \u0003אמר רב יהודה אמר רב,\u0004 אומרים: \u0003\"מודים אנחנו לך ה' אלהינו על כל טפה וטפה שהורדת לנו\". ור' יוחנן מסיים\u0004 בה, באותה ברכה, \u0003הכי\u0004 \u0005[כך],\u0006 בלשון זו: \u0003אילו פינו מלא שירה כים ולשוננו רנה כהמון גליו וכו'\u0004 (כפי שנאמר בתפילת \"נשמת\"), \u0003עד \"אל יעזבונו רחמיך ה' אלהינו ולא עזבונו, ברוך רוב ההודאות\".\u0004","ותוהים: מדוע נאמר בלשון זו \u0003\"רוב ההודאות\" ולא \"כל ההודאות\"? אמר רבא: אימא\u0004 \u0005[אמור]\u0006 בלשון שונה: \"\u0003אל ההודאות\"\u0004 ובכך כולל כל ההודאות. \u0003אמר רב פפא: הלכך\u0004 \u0005[לכן],\u0006 כיון שיש חילוקי דעות בדבר,"],["\u0003נימרינהו לתרוייהו\u0004 \u0005[נאמר את שניהם]\u0006 את שני הנוסחים יחד: \u0003\"אל ההודאות\" ו\"רוב ההודאות\".\u0004","כיון שהוזכרו הגשמים, מדברים בשבחם. \u0003אמר ר' אבהו: גדול יום הגשמים\u0004 יותר \u0003מ\u0004יום \u0003תחיית המתים\u0004 ובמה הוא גדול, ש\u0003אילו תחיית המתים\u0004 אינה אלא \u0003לצדיקים\u0004 בלבד, \u0003ואילו גשמים בין לצדיקים ובין לרשעים.\u0004 ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003רב יוסף,\u0004 ש\u0003אמר רב יוסף: מתוך\u0004 שירידת הגשמים חשובה \u0003שהיא שקולה כתחיית המתים\u0004 — \u0003קבעוה\u0004 את הזכרת הגשמים \u0003ב\u0004ברכת \u0003תחיית המתים.\u0004 משמע שהיא שקולה, ולא עדיפה מתחיית המתים.","כיוצא בו \u0003אמר רב יהודה: גדול יום הגשמים כיום שניתנה בו תורה, שנאמר: \"יערף כמטר לקחי\"\u0004 (דברים לב, ב), \u0003ואין \"לקח\" אלא תורה, שנאמר: \"כי לקח טוב נתתי לכם תורתי אל תעזבו\"\u0004 (משלי ד, ב). \u0003רבא אמר:\u0004 ירידת הגשמים גדולה \u0003יותר מיום שניתנה בו תורה, שנאמר: \"יערף כמטר לקחי\", מי נתלה במי?\u0004 כלומר, כיצד בדרך כלל מדמים אנו דבר לדבר, \u0003הוי אומר: קטן נתלה בגדול,\u0004 ואם נמשלה התורה לגשם — משמע שהגשם גדול ממנה.","כיון שהזכרנו כתוב זה מביאים אותו בהקשר שונה, \u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"יערף כמטר לקחי\"\u0004 בלשון קשה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק: \u0003\"תזל כטל אמרתי\"\u0004 בלשון רכה! וכך יש לפרש: \u0003אם תלמיד חכם הגון הוא\u0004 — הרי הוא \u0003כטל, ואם לאו\u0004 — \u0003עורפהו\u0004 (הרגהו) \u0003כמטר\u0004 היורד בכוח.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין זה, \u0003היה ר' בנאה אומר: כל העוסק בתורה לשמה\u0004 — \u0003תורתו נעשית לו סם חיים, שנאמר: \"עץ חיים היא למחזיקים בה\"\u0004 (משלי ג, יח), \u0003ואומר: \"רפאות תהי לשרך\"\u0004 (משלי ג, ח), \u0003ואומר: \"כי מצאי מצא חיים\"\u0004 (משלי ח, לה). \u0003וכל העוסק בתורה שלא לשמה\u0004 כדי להתגדל על הבריות — תורתו \u0003נעשית לו סם המות, שנאמר: \"יערף כמטר לקחי\", ואין עריפה אלא\u0004 לשון \u0003הריגה, שנאמר: \"וערפו שם את העגלה בנחל\"\u0004 (דברים כא, ד).","מסופר: פעם \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: ליתי מר ליתני\u0004 \u0005[יבוא אדוני\u0006 ו\u0005ישנה\u0006 לנו\u0005]\u0006 דבר הלכה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חלש לבאי\u0004 \u0005[לבי]\u0006 \u0003ולא יכילנא\u0004 \u0005[ואין אני יכול]\u0006 להתאמץ ולעסוק בהלכה. אמר לו: אם כן, \u0003לימא מר מילתא דאגדתא\u0004 \u0005[\u0006ש\u0005יאמר אדוני דבר אגדה],\u0006 שאינו דורש מאמץ גדול כל כך, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי האדם עץ השדה\"\u0004 (דברים כ, יט), ויש להבין: \u0003וכי\u0004 ה\u0003אדם עץ השדה הוא?\u0004","\u0003אלא משום דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"כי ממנו תאכל ואתו לא תכרת\"\u0004 (דברים כ, יט), \u0003וכתיב\u0004 \u0005[נאמר]\u0006 סמוך לו: \u0003\"אתו תשחית וכרת\"\u0004 (שם כ, כ), משמע, שיש עצים הנכרתים ועצים שאינם נכרתים, \u0003הא\u0004 \u0005[זה]\u0006 \u0003כיצד? אם תלמיד חכם הגון הוא\u0004 — \u0003\"ממנו תאכל ואתו לא תכרת\", ואם לאו\u0004 \u0005[לא],\u0006 שאינו הגון — \u0003\"אתו תשחית וכרת\".\u0004","ועוד ממדרשי המקראות בענין לימוד התורה; \u0003אמר ר' חמא אמר ר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ברזל בברזל יחד\u0004 ואיש יחד פני רעהו\u0003\"\u0004 (משלי כז, יז), כתוב זה בא \u0003לומר לך: מה\u0004 כלי \u0003ברזל זה אחד מחדד את חבירו\u0004 כשמשפשפים אותם זה בזה, \u0003אף שני תלמידי חכמים\u0004 העוסקים כאחד בתורה \u0003מחדדין זה את זה בהלכה.\u0004","\u0003אמר רבה בר חנה: למה נמשלו דברי תורה כאש, שנאמר: \"הלוא כה דברי כאש נאם ה'\"\u0004 (ירמיהו כג, כט), \u0003לומר לך: מה אש אינו דולק יחידי,\u0004 שאין גזיר עץ גדול בוער לבדו ודרושה מדורה שיש בה עצים מרובים, \u0003אף דברי תורה אין מתקיימין ביחידי.\u0004","\u0003והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר ר' יוסי בר חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"חרב אל הבדים ונאלו\"\u0004 (ירמיהו נ, לו), יש לפרשו: \u0003חרב\u0004 תבוא \u0003על שונאיהן של תלמידי חכמים\u0004 (בלשון נקיה, וכוונתו לתלמידי החכמים עצמם) \u0003שעוסקין בד בבד\u0004 ביחידות, לבד ולא בחבורה (שפירש \"בדים\" = בודדים) \u0003בתורה. ולא עוד אלא שמטפשין\u0004 (נעשים טפשים) על ידי לימוד התורה ביחידות, \u0003שנאמר: \"ונאלו\".\u0004","\u0003ולא עוד אלא שחוטאין.\u0004 וראיה לדבר, \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ונאלו\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"אשר נואלנו ואשר חטאנו\"\u0004 (במדבר יב, יא). \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור\u0006 ראיה \u0005מכאן]:\u0006 מה משמעות \"נואלו\" — שנאמר: \u0003\"נואלו שרי צען... והתעו את מצרים\"\u0004 (ישעיהו יט, יג).","ובדומה לזה, \u0003אמר רב נחמן בר יצחק: למה נמשלו דברי תורה כעץ, שנאמר: \"עץ חיים היא למחזיקים בה\"\u0004 (משלי ג, יח), \u0003לומר לך: מה עץ קטן מדליק את הגדול, אף תלמידי חכמים קטנים מחדדים את הגדולים\u0004 וגורמים להם לגדול בתורה. \u0003והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר ר' חנינא: הרבה למדתי מרבותי, ומחבירי\u0004 למדתי \u0003יותר מרבותי, ומתלמידי יותר מכולן.\u0004","\u0003ר' חנינא בר פפא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק אחר: \u0003\"לקראת צמא התיו מים\"\u0004 (ישעיהו כא, יד), משמע שצריך ללכת לקראתו ולהשקותו, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר: \u0003\"הוי כל צמא לכו למים\"\u0004 (ישעיהו נה, א)! ויש לישב כך: \u0003אם תלמיד הגון הוא\u0004 — \u0003\"לקראת צמא התיו מים\",\u0004 שהרב צריך ללכת לקראתו וללמדו, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הגון הוא — \u0003\"הוי כל צמא לכו למים\",\u0004 שאם רצונו בכך — יבוא וילמד.","\u0003ר' חנינא בר חמא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד: \u0003\"יפוצו מעינתיך חוצה\"\u0004 (משלי ה, טז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"יהיו לך לבדך\"\u0004 (משלי ה, יז)! וכך יש ליישב: \u0003אם תלמיד הגון הוא\u0004 היושב לפניך — \u0003\"יפוצו מעינתיך חוצה\"\u0004 ולמדהו, \u0003ואם לאו\u0004 — \u0003\"יהיו לך לבדך\".\u0004","\u0003אמר ר' חנינא בר אידי: למה נמשלו דברי תורה למים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הוי כל צמא לכו למים\"\u0004 (ישעיהו נה, א) \u0003לומר לך: מה מים מניחין מקום גבוה והולכין למקום נמוך, אף דברי תורה אין מתקיימין אלא במי שדעתו שפלה,\u0004 מי שנמוך ושפל בעיני עצמו.","\u0003אמר ר' אושעיא: למה נמשלו דברי תורה לשלשה משקין הללו: במים, ביין, ובחלב.\u0004 במים \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הוי כל צמא לכו למים\" וכתיב\u0004 \u0005[ונאמר]\u0006 גם שם: \u0003\"לכו שברו ואכלו ולכו שברו בלוא כסף ובלוא מחיר יין וחלב\"\u0004 (ישעיהו נה, א), \u0003לומר לך: מה שלשה משקין הללו אין מתקיימין\u0004 ונשמרים \u0003אלא בפחות שבכלים,\u0004 כגון כלי חרס, ולא בכלי כסף וזהב, שבהם הם מאבדים את טעמם — \u0003אף דברי תורה אין מתקיימין אלא במי שדעתו שפלה.\u0004","ובענין זה מסופר: \u0003כדאמרה ליה ברתיה\u0004 \u0005[כפי שאמרה לו בתו]\u0006 של ה\u0003קיסר\u0004 הרומי \u0003לר' יהושע בן חנניה\u0004 כשהיה ברומי: \u0003אי\u0004 \u0005[אוי]\u0006 ל\u0003חכמה מפוארה\u0004 כשלך שהיא מונחת \u0003בכלי מכוער!\u0004 שרבי יהושע אף שהיה חכם גדול, לא היה יפה מראה. \u0003אמר לה\u0004 כאילו שלא מן העניין: \u0003אביך רמי חמרא במני דפחרא\u0004 \u0005[אביך שם יין בכלי חרס]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אלא במאי נירמי\u0004 \u0005[במה נשים]?\u0006 \u0003אמר לה: אתון דחשביתו, רמו במאני דהבא וכספא\u0004 \u0005[אתם שאתם חשובים, שימו\u0006 אותם \u0005בכלי זהב וכסף].\u0006","\u0003אזלה ואמרה ליה לאבוה רמייא לחמרא במני דהבא וכספא, ותקיף\u0004 \u0005[הלכה ואמרה לו לאביה\u0006 לעשות כן \u0005ושמו את היין בכלי זהב וכסף, והחמיץ].\u0006 \u0003אתו ואמרו ליה\u0004 \u0005[באו ואמרו לו]\u0006 לקיסר שהחמיץ היין. \u0003אמר לה לברתיה\u0004 \u0005[לבתו]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמר לך הכי\u0004 \u0005[\u0006לעשות \u0005כך],\u0006 מי יעץ לך עצה זו? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ר' יהושע בן חנניה. קריוהו\u0004 \u0005[קראו לו]\u0006 לבוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמרת לה הכי\u0004 \u0005[כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי היכי\u0004 \u0005[כפי]\u0006 ש\u0003אמרה לי\u0004 כך \u0003אמרי\u0004 \u0005[אמרתי]\u0006 \u0003לה,\u0004 להוכיח שדברים משובחים אין משתמרים אלא בכלי פחות. אמר לו: \u0003והא איכא שפירי דגמירי\u0004 \u0005[והרי יש\u0006 אנשים \u0005יפים שלמדו]\u0006 ומלאים חכמה!"],["\u0003אי הוו סנו\u0004 \u0005[אילו היו מכוערים] —\u0006 \u0003טפי הוו גמירי\u0004 \u0005[יותר היו לומדים].\u0006 \u0003דבר אחר\u0004 באותו נושא למה נמשלה תורה לשלושה משקים אלה: \u0003מה שלשה משקין הללו אין נפסלין אלא בהיסח הדעת,\u0004 שאם אין שומרים אותם הם נשפכים ומתקלקלים — \u0003אף דברי תורה אין משתכחין אלא בהיסח הדעת,\u0004 שאם אדם מסיח דעתו מהם, הריהו מאבדם.","ושוב לענין גשמים. \u0003אמר ר' חמא בר' חנינא: גדול יום הגשמים כיום שנבראו\u0004 בו \u0003שמים וארץ, שנאמר: \"הרעיפו שמים ממעל ושחקים יזלו צדק תפתח ארץ ויפרו ישע וצדקה תצמיח יחד אני ה' בראתיו\"\u0004 (ישעיהו מה, ח). ומסבירים: \u0003\"בראתים\"\u0004 בלשון רבים \u0003לא נאמר, אלא \"בראתיו\"\u0004 בלשון יחיד, ואם כן ודאי שאינו מתייחס בפסוק לשחקים ולארץ, אלא לגשם, ללמד שירידת הגשם חשובה כבריאת העולם.","\u0003אמר ר' אושעיא: גדול יום הגשמים, שאפילו ישועה פרה ורבה בו,\u0004 ששעת רצון היא, ובאה בו ישועה לעולם, \u0003שנאמר: \"תפתח ארץ ויפרו ישע\"\u0004 (ישעיהו מה, ח). \u0003אמר ר' תנחום בר חנילאי: אין הגשמים יורדים אלא אם כן נמחלו עונותיהן של ישראל, שנאמר: \"רצית ה' ארצך שבת שבות יעקב. נשאת עון עמך כסית כל חטאתם סלה\"\u0004 (תהלים פה, ב-ג) ואחר כך מדבר בירידת הגשמים (\"וצדק משמים נשקף\". תהלים פה, יג).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003זעירי, מ\u0004מקום שנקרא \u0003דיהבת, לרבינא: אתון, מהכא מתניתו לה\u0004 \u0005[אתם, מכאן אתם לומדים אותה]\u0006 \u0003אנן, מהכא מתנינן לה\u0004 \u0005[\u0006ו\u0005אנחנו, מכאן אנחנו לומדים אותה]\u0006 סברה עצמה, שנאמר: \"בהיעצר שמים ולא יהיה מטר כי יחטאו לך והתפללו אל המקום הזה והודו את שמך ומחטאתם ישובון כי תענם. \u0003ואתה תשמע השמים וסלחת לחטאת\u0004 עבדיך ועמך ישראל כי תורם את הדרך הטובה אשר ילכו בה ונתתה מטר על ארצך אשר נתתה לעמך לנחלה\" (מלכים א' ח, לה-לו).","\u0003אמר ר' תנחום בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא איש כפר עכו: אין הגשמים נעצרין אלא אם כן נתחייבו שונאיהן של ישראל\u0004 (כלומר, בלשון נקיה: ישראל) \u0003כליה, שנאמר: \"ציה גם חם יגזלו מימי שלג שאול חטאו\"\u0004 (איוב כד, יט), כלומר, נגזלים מימי שלג, שאין הגשם והשלג יורדים, כאשר אנשים חטאו חטא מוות (= \"שאול\"). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003זעירי מדיהבת לרבינא: אתון, מהכא מתניתו לה\u0004 \u0005[אתם, מכאן אתם לומדים אותה],\u0006 \u0003אנן, מהכא מתנינן לה\u0004 \u0005[\u0006ו\u0005אנחנו, מכאן\u0006 מפסוק אחר \u0005לומדים אותה],\u0006 שנאמר: \u0003\"\u0004וסרתם ועבדתם אלהים אחרים... \u0003ועצר את השמים ולא יהיה מטר\u0004 והאדמה לא תתן את יבולה \u0003ואבדתם מהרה\"\u0004 (דברים יא, טז-יז).","\u0003אמר רב חסדא: אין הגשמים נעצרין אלא בשביל ביטול תרומות ומעשרות\u0004 שאין אנשים מפרישים עוד, \u0003שנאמר: \"ציה גם חם יגזלו מימי שלג\".\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כלומר, כיצד נובע רעיון זה מן הפסוק? ומסבירים: שהוא מסתמך על \u0003תנא דבי\u0004 \u0005[\u0006מה ש\u0005שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בשביל דברים שצויתי\u0004 (\"ציה\" כמו צוה) \u0003אתכם בימות החמה\u0004 מתן תרומות ומעשרות מן היבול הגדל בקיץ \u0003ולא עשיתם — יגזלו מכם מימי שלג בימות הגשמים.\u0004","\u0003אמר ר' שמעון בן פזי: אין הגשמים נעצרין אלא בשביל מספרי לשון הרע, שנאמר: \"רוח צפון תחולל גשם ופנים נזעמים לשון סתר\"\u0004 (משלי כה, כג). לומר, שאם לשמים פנים נזעמים (ללא עננים וגשם), הרי זה בגלל לשון הרע הנאמרת בסתר.","\u0003אמר רב סלא אמר רב המנונא: אין הגשמים נעצרין אלא בשביל עזי פנים, שנאמר: \"וימנעו רבבים ומלקוש לוא היה ומצח אשה זונה היה לך\"\u0004 (ירמיהו ג, ג). על אותו פסוק \u0003אמר רב סלא אמר רב המנונא: כל אדם שיש לו עזות פנים — סוף נכשל בעבירה\u0004 של זנות, \u0003שנאמר: \"ומצח אשה זונה היה לך\". רב נחמן אמר:\u0004 לא סופו שיכשל בעבירה זו, אלא \u0003בידוע שנכשל\u0004 כבר \u0003בעבירה, שנאמר: \"היה לך\"\u0004 בלשון עבר \u0003ולא נאמר \"יהיה לך\"\u0004 בלשון עתיד.","\u0003אמר רבה בר רב הונא: כל אדם שיש לו עזות פנים — מותר לקרותו רשע, שנאמר: \"העז איש רשע בפניו\"\u0004 (משלי כא, כט), משמע שאם העז איש בפניו — אפשר לומר לו (\"בפניו\") שהוא רשע. \u0003רב נחמן בר יצחק אמר: מותר לשנאותו שנאמר: \"ועז פניו ישנא\"\u0004 (קהלת ח, א), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"ישנא\" אלא \"ישנא\".\u0004","\u0003אמר רב קטינא: אין הגשמים נעצרין אלא בשביל ביטול תורה, שנאמר: \"בעצלתים ימך המקרה\u0004 ובשפלות ידים ידלוף הבית\u0003\"\u0004 (קהלת י, יח), לומר: \u0003בשביל עצלות שהיה בישראל שלא עסקו בתורה — נעשה שונאו של הקדוש ברוך הוא\u0004 (לשון נקיה, כלומר, הקדוש ברוך הוא) \u0003מך. ואין \"מך\" אלא עני, שנאמר: \"ואם מך הוא מערכך\"\u0004 (ויקרא כז, ח) \u0003ואין \"מקרה\" אלא\u0004 כינוי ל\u0003הקדוש ברוך הוא, שנאמר: \"המקרה במים עליותיו\"\u0004 (תהלים קד, ג).","\u0003רב יוסף אמר: מהכא\u0004 \u0005[מכאן]\u0006 מפסוק זה אפשר ללמוד אותו ענין: \u0003\"ועתה לא ראו אור בהיר הוא בשחקים ורוח עברה ותטהרם\"\u0004 (איוב לז, כא) \u0003ואין \"אור\" אלא תורה, שנאמר: \"כי נר מצוה ותורה אור\"\u0004 (משלי ו, כג), לומר, שכאשר \"לא ראו אור\" — לא עסקו בתורה — אז \u0003\"בהיר הוא בשחקים\",\u0004 שאין עננים בשמים. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על כתוב זה: \u0003אפילו בשעה שרקיע נעשה בהורין בהורין\u0004 (טלאים טלאים, של עננים) \u0003להוריד טל ומטר,\u0004 גם אז \u0003\"רוח עברה ותטהרם\"\u0004 ואין גשם יורד.","\u0003אמר ר' אמי: אין הגשמים נעצרין אלא בעון גזל, שנאמר: \"על כפים כסה אור\u0004 ויצו עליה במפגיע\u0003\"\u0004 (איוב לו, לב), לומר: \u0003בעון כפים\u0004 שגזלו — \u0003כסה אור\u0004 ואין גשמים יורדים. והוא מבאר \u0003ואין \"כפים\" אלא\u0004 רמז עבור חטא \u0003חמס, שנאמר: \"ומן החמס אשר בכפיהם\"\u0004 (יונה ג, ח), \u0003ואין \"אור\" אלא מטר, שנאמר: \"יפיץ ענן אורו\"\u0004 (איוב לז, יא).","\u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 של מי שגרם שאין הגשמים יורדים — \u0003ירבה בתפלה, שנאמר: \"ויצו עליה במפגיע\"\u0004 (איוב לו, לב) \u0003ואין פגיעה אלא\u0004 לשון \u0003תפלה, שנאמר: \"ואתה אל תתפלל בעד העם הזה\u0004 ואל תשא בעדם רינה ותפילה \u0003ואל תפגע בי\"\u0004 (ירמיהו ז, טז).","\u0003ואמר ר' אמי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם קהה הברזל והוא לא פנים קלקל\"\u0004 (קהלת י, י), כתוב זה בא לומר: \u0003אם ראית רקיע שקיהה כברזל מלהוריד טל ומטר,\u0004 דבר זה הוא \u0003בשביל מעשה הדור שהן מקולקלין, שנאמר: \"והוא לא פנים קלקל\",\u0004","\u0003מה תקנתן — יתגברו ברחמים, שנאמר: \"וחילים יגבר ויתרון הכשיר חכמה\"\u0004 (קהלת י, י) — ו\u0003כל שכן אם הוכשרו מעשיהן מעיקרא\u0004 \u0005[מתחילה],\u0006 לא ייעצרו הגשמים.","על אותו פסוק עצמו מביאים דרשה אחרת, \u0003ריש לקיש אמר: אם ראית תלמיד\u0004"],["\u0003שלמודו קשה עליו כברזל\u0004 ואינו מבין כראוי — הטעם הוא \u0003בשביל משנתו שאינה סדורה עליו,\u0004 שכיון שעיקרי הדברים במשנה אינם ברורים לו, הריהו מתבלבל ומתקשה בהם, \u0003שנאמר: \"והוא לא פנים קלקל\"\u0004 (קהלת י, י), שאם לא סידר את לימודו תחילה (\"לא פנים\") — הריהו מקלקל.","\u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 — \u0003ירבה בישיבה\u0004 וילמד עד שיתקן את הדבר, \u0003שנאמר: \"וחילים יגבר\"\u0004 (קהלת י, י), וממילא: \u0003\"ויתרון הכשיר חכמה\"\u0004 (קהלת י, י). ו\u0003כל שכן אם משנתו סדורה לו מעיקרא\u0004 \u0005[מתחילה]\u0006 שאינו מגיע למכשול זה.","\u0003כי הא\u0004 \u0005[כמו זה]\u0006 שמסופר ש\u0003ריש לקיש הוה\u0004 \u0005[היה]\u0006 \u0003מסדר\u0004 את \u0003מתניתיה ארבעין זמנין\u0004 \u0005[משנתו ארבעים פעמים]\u0006 וארבעים דווקא, \u0003כנגד ארבעים יום שניתנה\u0004 בהם \u0003תורה\u0004 למשה בסיני \u0003ו\u0004רק אחר כך \u0003עייל לקמיה\u0004 \u0005[היה נכנס לפני]\u0006 \u0003ר' יוחנן\u0004 ללמוד ממנו. ואגב זה מסופר: \u0003רב אדא בר אהבה\u0004 היה \u0003מסדר\u0004 את \u0003מתניתיה\u0004 \u0005[משנתו]\u0006 וחוזר עליה \u0003עשרים וארבע זמנין\u0004 \u0005[פעמים],\u0006 \u0003כנגד\u0004 עשרים וארבעה ספרים של \u0003תורה נביאים וכתובים, ועייל לקמיה\u0004 \u0005[ו\u0006רק אחר כך היה \u0005נכנס לפני]\u0006 \u0003רבא\u0004 ללמוד.","על אותו פסוק בקהלת, \u0003רבא אמר: אם ראית תלמיד שלמודו קשה עליו כברזל —\u0004 הרי זה \u0003בשביל רבו שאינו מסביר לו פנים,\u0004 אלא מקפיד עליו ולכן מתקשה בלימוד, \u0003שנאמר: \"והוא לא פנים קלקל\".\u0004","\u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 של אותו תלמיד — \u0003ירבה עליו רעים,\u0004 כלומר, ישלח ידידים לפייס את הרב, \u0003שנאמר: \"וחילים יגבר\",\u0004 וממילא: \u0003\"ויתרון הכשיר חכמה\",\u0004 ו\u0003כל שכן אם הוכשרו מעשיו בפני רבו מעיקרא\u0004 \u0005[מתחילה].\u0006","ושוב לענין הגשמים. \u0003אמר ר' אמי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם ישך הנחש בלוא לחש ואין יתרון לבעל הלשון\"\u0004 (קהלת י, יא), כתוב זה בא ללמד, ש\u0003אם ראית דור שהשמים משתכין\u0004 (מחלידים) \u0003כנחשת\u0004 (\"ישוך הנחש\") \u0003מלהוריד טל ומטר —\u0004 הרי זה \u0003בשביל לוחשי לחישות\u0004 (בעלי תפילה) \u0003שאין בדור\u0004 (\"בלא לחש\"),","\u0003מאי תקנתן — ילכו אצל מי שיודע ללחוש\u0004 (להתפלל), \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יגיד עליו רעו\"\u0004 (איוב לו, לג). \u0003\"ואין יתרון לבעל הלשון\"\u0004 (קהלת י, יא), כוונתו: \u0003ומי שאפשר לו ללחוש\u0004 (להתפלל) \u0003ואינו לוחש — מה הנאה יש לו?\u0004","ושואלים: \u0003ואם לחש\u0004 (התפלל) \u0003ולא נענה, מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 \u0003ילך אצל חסיד שבדור, וירבה עליו בתפלה, שנאמר\u0004 בסמוך: \u0003\"ויצו עליה במפגיע\"\u0004 (איוב לו, לב), \u0003ואין פגיעה אלא תפילה, שנאמר: \"ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה ואל תפגע בי\"\u0004 (ירמיהו ז, טז).","\u0003ואם לחש ועלתה בידו,\u0004 שירדו גשמים כבקשתו \u0003ומגיס דעתו עליו\u0004 (ומתגאה) — \u0003מביא אף\u0004 (זעם, כעס) \u0003לעולם, שנאמר: \"מקנה אף על עולה\"\u0004 (איוב לו, לג), שמביא כעס (\"מקנה אף\") בשל גאווה (\"על עולה\").","\u0003רבא אמר\u0004 על אותו כתוב: \u0003שני תלמידי חכמים שיושבים בעיר אחת ואין נוחין זה לזה בהלכה,\u0004 אלא מתקוטטים זה עם זה — הרי הם \u0003מתקנאין באף,\u0004 כלומר, הם גורמים לעצמם להביא קצף לעולם, \u0003ומעלין אותו, שנאמר: \"מקנה אף על עולה\".\u0004","כיון שהוזכר פסוק זה בקהלת, מביאים מה ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם ישך הנחש בלוא לחש ואין יתרון לבעל הלשון\", לעתיד לבוא מתקבצות ובאות כל החיות אצל הנחש, ואומרים לו: ארי דורס\u0004 (בצפרני רגליו) \u0003ואוכל, זאב טורף\u0004 חיה, משסע אותה בפיו \u0003ואוכל, אתה\u0004 שאתה נושך \u0003מה הנאה יש לך?\u0004 שהרי אין הנחש יכול לאכול מאותם יצורים גדולים שהוא נושך והורג! \u0003אמר להם: \"ואין יתרון לבעל הלשון\",\u0004 כלומר, יש שאלה קשה מזו: מה הנאה יש לבעל הלשון הרעה, שמזיק יותר ואינו נהנה?","\u0003אמר ר' אמי: אין תפלתו של אדם נשמעת, אלא אם כן משים נפשו בכפו,\u0004 כלומר, מוסר נפשו ומכוונה לכך שתהיה בכפו, \u0003שנאמר: \"נשא לבבנו אל כפים\"\u0004 (איכה ג, מא). ומקשים: \u0003איני\u0004 \u0005[\u0006האם \u0005כן הוא]?!\u0006 \u0003והא אוקים\u0004 \u0005[והרי העמיד]\u0006 \u0003שמואל אמורא עליה\u0004 \u0005[מתורגמן עליו\u0006 לידו\u0005]\u0006 \u0003ודרש\u0004 דרשה זו, שנאמר: \u0003\"ויפתוהו בפיהם ובלשונם יכזבו לו. ולבם לא נכון עמו ולא נאמנו בבריתו\"\u0004 (תהלים עח, לו-לז), \u0003ואף על פי כן\u0004 נאמר מיד בהמשך \u0003\"והוא רחום יכפר עון\"\u0004 (תהלים עח, לח), משמע שכל תפילה, אף אם נאמרה בפה בלבד הריהי מתקבלת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן — ביחיד,\u0004 שאם אינו מוסר נפשו, אכן אין תפילתו נשמעת, \u0003כאן — בצבור,\u0004 שאף אם לא מסר נפשו עליה תפילתו מתקבלת בזכות הציבור.","\u0003אמר ר' אמי: אין גשמים יורדים אלא בשביל בעלי אמנה,\u0004 כלומר, אנשים נאמנים המקיימים את הבטחותיהם, \u0003שנאמר: \"אמת מארץ תצמח וצדק משמים נשקף\"\u0004 (תהלים פה, יב), ופירוש הפסוק הוא: שאם \"אמת מארץ תצמח\", אזי \"צדק משמים נשקף\", שהוא הגשם היורד משמים.","\u0003ואמר ר' אמי: בא וראה כמה גדולים בעלי אמנה\u0004 וכמה הקדוש ברוך הוא עוזר להם, \u0003מניין — מ\u0004מעשה שהיה ב\u0003חולדה ובור\u0004 שהציל בחור נערה אחת מתוך בור, והבטיחו זה לזה להנשא, וקבעו לעצמם עדים — בור שהיה סמוך להם וחולדה שעברה שם בדרך. לאחר זמן שכח הבחור את הבטחתו ונשא אשה אחרת והוליד ילדים, ומת אחד מהם בבור, והשני טרפתו חולדה, עד שהרגיש בדבר וחזר לנערה הראשונה. \u0003ומה המאמין\u0004 ותולה את אמונתו \u0003בחולדה ובור — כך\u0004 מתקיים בו, \u0003המאמין\u0004 ותולה אמונתו \u0003בהקדוש ברוך הוא\u0004 להיות עד בינו ובין חבירו — \u0003על אחת כמה וכמה.\u0004","\u0003אמר ר' יוחנן: כל המצדיק את עצמו מלמטה,\u0004 שמנסה ככל האפשר להיות צדיק וישר בכל דרכיו — \u0003מצדיקין עליו\u0004 את \u0003הדין מלמעלה\u0004 ומדקדקים עליו, כדי להוסיף ולתקנו, \u0003שנאמר: \"אמת מארץ תצמח וצדק משמים נשקף\",\u0004 משמע, דווקא באמת הצומחת מן הסבל יהיה אף צדק מן השמים. \u0003ר' חייא בר אבין אמר רב הונא: מהכא\u0004 \u0005[מכאן]\u0006 נלמד ענין זה, שנאמר: \u0003\"וכיראתך עברתך\"\u0004 (תהלים צ, יא) — ככל שהאדם ירא יותר מה' כך גדולה יותר עברת ה' אם יחטא במשהו.","\u0003ריש לקיש אמר מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"פגעת את שש ועשה צדק בדרכיך יזכרוך הן אתה קצפת ונחטא בהם עולם ונושע\"\u0004 (ישעיהו סד, ד) שהשמח (\"שש\") לעשות צדק — נוהגים בו כדרכיו, וקוצף ה' עליו אם יחטא. \u0003אמר ר' יהושע בן לוי\u0004 על אותו פסוק: \u0003כל השמח ביסורין שבאין עליו — מביא ישועה לעולם, שנאמר: \"בהם עולם ונושע\".\u0004","ועוד בענין גשמים, \u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ועצר את השמים\"\u0004 (דברים יא, יז) — לשון עצירה מלמדת, כי \u0003בשעה שהשמים נעצרין מלהוריד טל ומטר\u0004 — הרי זה \u0003דומה לאשה שמחבלת\u0004 (שיש לה חבלי לידה) \u0003ואינה יולדת,\u0004 וכביכול אף הם סובלים מעצירה זו. \u0003והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר ריש לקיש משום\u0004 (בשמו) של \u0003בר קפרא: נאמרה עצירה בגשמים ונאמרה עצירה באשה,\u0004"],["\u0003נאמרה עצירה באשה\u0004 שאינה יולדת, \u0003שנאמר: \"כי עצר עצר ה' בעד כל רחם\"\u0004 (בראשית כ, יח), \u0003ונאמרה עצירה בגשמים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועצר את השמים\"\u0004 (דברים יא, יז).","כיוצא בו \u0003נאמר לידה באשה ונאמר לידה בגשמים, נאמר לידה באשה\u0004 כגון האמור ברחל שפתח ה' את רחמה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותהר ותלד בן\"\u0004 (בראשית ל, כג), \u0003ונאמר לידה בגשמים, דכתיב: \"\u0004כי כאשר ירד הגשם והשלג מן השמים ושמה לא ישוב כי אם הרוה את הארץ \u0003והולידה והצמיחה\"\u0004 (ישעיהו נה, י).","וכיוצא בזה \u0003נאמר פקידה באשה, ונאמר פקידה בגשמים. נאמר פקידה באשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וה' פקד את שרה\"\u0004 (בראשית כא, א), \u0003ונאמר פקידה בגשמים, דכתיב: \"פקדת הארץ ותשקקה רבת תעשרנה פלג אלהים מלא מים\"\u0004 (תהלים סה, י).","על פסוק זה שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"פלג אלהים מלא מים\"? תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כמין קובה\u0004 (חדר קטן) \u0003יש ברקיע שממנה גשמים יוצאין.\u0004","\u0003אמר ר' שמואל בר נחמני: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בגשמים: \u0003\"\u0004כל אשר יצום על פני תבל ארצה \u0003אם לשבט אם לארצו אם לחסד ימצאהו\"\u0004 (איוב לז, יב-יג), כוונתו: \u0003\"אם לשבט\",\u0004 אם גזר הדין הוא לרעה — הרי יורד הגשם \u0003בהרים ובגבעות, \"אם לחסד ימצאהו לארצו\" — בשדות ובכרמים.\u0004","או באופן אחר: \u0003\"אם לשבט\" —\u0004 יורד הגשם במטר עז הטוב רק \u0003לאילנות, \"אם לארצו\" —\u0004 יורד \u0003לזרעים, \"אם לחסד ימצאהו\" —\u0004 אלו גשמים היורדים ל\u0003בורות, שיחין\u0004 (בורות מרובעים), \u0003ומערות\u0004 (בורות מקוריים) שהמים מספיקים גם לימות החמה.","מסופר: \u0003בימי ר' שמואל בר נחמני הוה כפנא ומותנא\u0004 \u0005[היה רעב ודבר],\u0006 \u0003אמרי: היכי נעביד\u0004 \u0005[אמרו\u0006 החכמים: \u0005איך נעשה]?\u0006 \u0003ניבעי רחמי אתרתי\u0004 \u0005[נבקש רחמים,\u0006 נתפלל \u0005על שתיהם]\u0006 — \u0003לא אפשר,\u0004 שאין מבקשים על שני דברים כאחד. \u0003אלא ליבעי רחמי אמותנא, וכפנא ניסבול\u0004 \u0005[נבקש רחמים על הדבר ואת הרעב נסבול].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' שמואל בר נחמני: ניבעי רחמי אכפנא, דכי יהיב רחמנא שובעא — לחיי הוא דיהיב\u0004 \u0005[נבקש רחמים על הרעב, שכאשר נותן ה' שובע —\u0006 \u0005לחיים הוא שנותן]\u0006 ואם תישמע תפילתנו, ממילא תיעצר המגפה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פותח את ידך ומשביע לכל חי רצון\"\u0004 (תהלים קמה, טז).","ומסבירים: \u0003ומנלן דלא מצלינן אתרתי\u0004 \u0005[ומניין לנו שאין מתפללים על שתיים]\u0006 בבת אחת — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונצומה ונבקשה מאלהינו על זאת\"\u0004 (עזרא ח, כג) — מן ההדגשה \"על זאת\" נלמד: \u0003מכלל דאיכא אחריתי\u0004 \u0005[מכאן שהיתה\u0006 גם צרה \u0005אחרת]\u0006 אבל לא התפללו עליה וזאת לפי שאין מתפללים אלא על אחת. \u0003במערבא אמרי משמיה\u0004 \u0005[בארץ ישראל\u0006 היו \u0005אומרים משמו]\u0006 של \u0003חגי מהכא\u0004 \u0005[\u0006ראייה \u0005מכאן]:\u0006 \u0003\"ורחמין למבעא מן קדם אלה שמיא על רזא דנא\"\u0004 \u0005[ורחמים לבקש מלפני אלוהי השמים על סוד זה]\u0006 (דניאל ב, יח), וההדגשה הזאת מלמדת: \u0003מכלל דאיכא אחריתי\u0004 \u0005[מכאן שיש אחר]\u0006 שלא התפלל עליו, אלא על זה בלבד.","קצת בדומה לזה מסופר: \u0003בימי ר' זירא גזור שמדא, וגזור דלא למיתב בתעניתא\u0004 \u0005[גזרו שמד על\u0006 ישראל, \u0005וגזרו\u0006 גם \u0005שלא לשבת בתענית]\u0006 וממילא לא יכלו לקבוע תענית ולהתפלל על ביטול הגזירה. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' זירא: נקבליה עילוון, ולכי בטיל שמדא ליתביה\u0004 \u0005[נקבל\u0006 את התענית \u0005עלינו וכאשר יתבטל השמד נחזירנו]\u0006 את יום התענית הזה שקיבלנו עכשיו ולא יכולנו לעשות.","\u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003מנא לך הא\u0004 \u0005[מניין לך\u0006 דבר \u0005זה]\u0006 שתענית שמקבל על עצמו, אף שאינו מתענה עדיין, נחשבת? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אלי אל תירא דניאל כי מן היום הראשון אשר נתת את לבך להבין ולהתענות לפני אלהיך נשמעו דבריך\"\u0004 (דניאל י, יב), הרי שכבר מהיום שנתן לבו להתענות נשמעו דבריו.","ושוב לענין הגשמים. \u0003אמר ר' יצחק: אפילו שנים כשני אליהו\u0004 שגזר הקדוש ברוך הוא שלא ירד גשם, \u0003וירדו\u0004 בהם \u0003גשמים בערבי שבתות — אינן אלא סימן קללה,\u0004 שכן הגשם היורד אז רק מפריע לבריות להכין את צרכי השבת, ונמצא שאינו בא לברכה להם. \u0003היינו\u0004 \u0005[הוא]\u0006 ש\u0003אמר רבה בר שילא: קשה יומא דמיטרא כיומא דדינא\u0004 \u0005[קשה יום המטר כיום הדין].\u0006 ובאותו ענין \u0003אמר אמימר: אי לא דצריך לברייתא\u0004 \u0005[אם לא שהיה צריך\u0006 הגשם \u0005לבריות],\u0006 \u0003בעינן רחמי ומבטלינן ליה\u0004 \u0005[\u0006היינו \u0005מבקשים רחמים ומבטלים אותו]\u0006 שלא ירד גשם, מפני הטרדות שהוא גורם.","\u0003ואמר ר' יצחק: שמש בשבת\u0004 — הרי זו \u0003צדקה לעניים,\u0004 שהם יכולים לצאת ולהתענג בחוץ, ואינם סובלים מן הצינה. \u0003שנאמר: \"וזרחה לכם יראי שמי שמש צדקה ומרפא\"\u0004 (מלאכי ג, כ). \u0003ואמר ר' יצחק: גדול יום הגשמים, שאפילו פרוטה שבכיס מתברכת בו\u0004 ולא גידולי קרקע בלבד. \u0003שנאמר: \"לתת מטר ארצך בעתו ולברך את כל מעשה ידך\"\u0004 (דברים כח, יב).","\u0003ו\u0004בענין ברכה \u0003אמר\u0004 עוד \u0003ר' יצחק: אין הברכה מצויה אלא בדבר הסמוי מן העין\u0004 ולא בדבר הנראה לכל, שנס גלוי לעין כל מתרחש רק במקרים נדירים, \u0003שנאמר: \"יצו ה' אתך את הברכה באסמיך\"\u0004 (דברים כח, ח), משמע: אין הברכה חלה אלא בדבר המצוי באסם ולא גלוי לכל. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אין הברכה מצויה אלא בדבר שאין העין שולטת בו, שנאמר: \"יצו ה' אתך את הברכה באסמיך\".\u0004","וכיוצא בו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנכנס למוד\u0004 (למדוד) \u0003את גרנו אומר: \"יהי רצון מלפניך ה' אלהינו שתשלח ברכה במעשה ידנו\",\u0004 שתתרבה התבואה ממה שהיתה. \u0003התחיל למוד אומר: \"ברוך השולח ברכה בכרי הזה\". מדד ואחר כך בירך\u0004 ברכה זו — \u0003הרי זו תפלת שוא\u0004 והברכה לא תבוא, \u0003לפי שאין הברכה מצויה לא בדבר השקול, ולא בדבר המדוד, ולא בדבר המנוי,\u0004 שהרי באלה יהא הריבוי בכלל נס גלוי, \u0003אלא בדבר הסמוי מן העין.\u0004","המימרות הבאות של ר' יוחנן — \u0003קבוץ\u0004 (גלויות), (ביטול) \u0003גייסות,\u0004 (פוסקי) \u0003צדקה, (מעשה) מעשר,\u0004 מינוי \u0003פרנס\u0004 הוא ה\u0003סימן\u0004 להם. \u0003אמר ר' יוחנן: גדול יום הגשמים כיום קבוץ גליות, שנאמר: \"שובה ה' את שביתנו כאפיקים בנגב\"\u0004 (תהלים קכו, ד), \u0003ואין \"אפיקים\" אלא מטר, שנאמר: \"ויראו אפקי ים\"\u0004 (שמואל ב' כב, טז).","\u0003ואמר ר' יוחנן: גדול יום הגשמים, שאפילו גייסות\u0004 (חילות צבא) \u0003פוסקות בו,\u0004 שהרי אין אנשי הצבא מהלכים בימות הגשם ובבוץ, \u0003שנאמר: \"תלמיה רוה נחת גדודיה\"\u0004 (תהלים סה, יא), שהוא מפרשו, שכאשר רווים התלמים מים הגדודים נחים במקומם. \u0003ואמר ר' יוחנן: אין הגשמים נעצרין אלא בשביל פוסקי צדקה ברבים ו\u0004לבסוף \u0003אין נותנין, שנאמר: \"נשיאים ורוח וגשם אין איש מתהלל במתת שקר\"\u0004 (משלי כה, יד)","\u0003ואמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006"],["\u0003\"עשר תעשר\u0004 את כל תבואת זרעך\u0003\"\u0004 (דברים יד, כב), יש לדרשו: \u0003עשר בשביל שתתעשר\u0004 בזכות המצוה.","מסופר: \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003ר' יוחנן לינוקא\u0004 \u0005[את בנו הקטן]\u0006 של \u0003ריש לקיש, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא לי פסוקיך\u0004 \u0005[אמור לי את פסוקך]\u0006 שלמדת היום בבית הספר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 הילד: \u0003\"עשר תעשר\". אמר ליה\u0004 \u0005[לו]\u0006 הילד: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"עשר תעשר\"? אמר ליה\u0004 \u0005[לו]\u0006 רבי יוחנן: פירושו \u0003עשר בשביל שתתעשר, אמר ליה\u0004 \u0005[לו]\u0006 הילד: \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003לך\u0004 שכך הוא? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003זיל נסי\u0004 \u0005[לך\u0006 ו\u0005נסה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומי שרי לנסוייה\u0004 \u0005[והאם מותר לנסות]\u0006 את \u0003הקדוש ברוך הוא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתורה: \u0003\"לא תנסו את ה'\u0004 אלהיכם\u0003\"\u0004 (דברים ו, טז)! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' הושעיא: חוץ מזו\u0004 שבה מותר לנסות, \u0003שנאמר: \"הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר ה' צבאות אם לא אפתח לכם את ארבות השמים והריקתי לכם ברכה עד בלי די\"\u0004 (מלאכי ג, י).","ואגב שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד בלי די\"? אמר רמי בר חמא אמר רב: עד שיבלו\u0004 (יתעייפו, כאילו ייעשו בלאות, שכך דרש \"בלי\") \u0003שפתותיכם מלומר \"די\". אמר ליה\u0004 \u0005[לו]\u0006 התינוק לר' יוחנן: \u0003אי הות מטי התם להאי פסוקא, לא הוית צריכנא לך ולהושעיא רבך\u0004 \u0005[אם הייתי מגיע לשם לפסוק זה, לא הייתי צריך אותך ואת הושעיא רבך],\u0006 שהרי הדבר מפורש שם, ואין צורך בדבריו.","ומסופר עוד על חריפותו של ילד זה: \u0003ותו אשכחיה\u0004 \u0005[ועוד,\u0006 ושוב \u0005מצאו]\u0006 \u0003ר' יוחנן לינוקיה\u0004 \u0005[את בנו הקטן]\u0006 של \u0003ריש לקיש דיתיב ואמר\u0004 \u0005[שהוא יושב ואומר]\u0006 פסוק זה בתוך לימודו: \u0003\"אולת אדם תסלף דרכו ועל ה' יזעף לבו\"\u0004 (משלי יט, ג), שכשאדם חוטא, באים עליו כל מיני פגעים (\"תסלף דרכו\"), וכועס ותמה מפני מה אירע לו כזאת (\"ועל ה' יזעף לבו\").","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' יוחנן וקא מתמה\u0004 \u0005[והיה תמה]\u0006 ומעיין בדבר; \u0003אמר: מי איכא מידי דכתיבי בכתובי דלא רמיזי באורייתא\u0004 \u0005[האם יש דבר הכתוב בכתובים ואינו רמוז\u0006 כלל \u0005בתורה]?\u0006 שהרי דבר זה אין לו רמז בתורה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 התינוק: \u0003אטו הא מי לא רמיזי\u0004 \u0005[האם\u0006 דבר \u0005זה איננו רמוז],\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויצא לבם ויחרדו איש אל אחיו לאמר מה זאת עשה אלהים לנו\"\u0004 (בראשית מב, כח) והרי זו דוגמה לאותו ענין; שאדם שחטא, כאשר אירעה לו קלקלה תמה מפני מה עשה לו דבר זה.","התפעל רבי יוחנן מחכמתו של הילד \u0003דל עיניה וחזא ביה\u0004 \u0005[נשא עיניו והסתכל בו],\u0006 \u0003אתיא אימיה אפיקתיה\u0004 \u0005[באה אמו והוציאה אותו]\u0006 משם, \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לילד: \u0003תא מקמיה\u0004 \u0005[בוא,\u0006 לך \u0005מלפניו]\u0006 ש\u0003לא ליעבד\u0004 \u0005[יעשה]\u0006 \u0003לך כדעבד לאבוך\u0004 \u0005[יעשה לך כפי שעשה לאביך].\u0006 שמסופר שכעס רבי יוחנן על גיסו ריש לקיש ונתן עיניו בו, וגרם לו על ידי כך שימות (ב\"מ פד,א), ופחדה אמו שמא יארע אף לבן כעין זה.","לאחר הפסקה זו, חוזרים למאמר נוסף שאמר רבי יוחנן בענין הגשם. \u0003ואמר ר' יוחנן: מטר\u0004 יורד אפילו \u0003בשביל יחיד,\u0004 שבשביל דרישתו של אדם יחיד הצריך למטר יורד הגשם, ואילו \u0003פרנסה\u0004 וברכה באה \u0003בשביל רבים.\u0004 וראיה לדבר: \u0003מטר בשביל יחיד — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יפתח ה' לך את אוצרו הטוב\u0004 את השמים \u0003לתת מטר ארצך\"\u0004 (דברים כח, יב) האמור בלשון יחיד, \u0003פרנסה\u0004 באה \u0003בשביל רבים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנני ממטיר לכם לחם\u0004 מן השמים\u0003\"\u0004 (שמות טז, ד) בלשון רבים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מברייתא, \u0003ר' יוסי בר' יהודה אומר: שלשה פרנסים\u0004 (מנהיגים) \u0003טובים עמדו לישראל\u0004 בצאתם ממצרים, ו\u0003אלו הן: משה ואהרן ומרים. ושלש מתנות טובות ניתנו\u0004 משמים \u0003על ידם, ואלו הן: באר\u0004 המים, \u0003וענן\u0004 הכבוד, \u0003ומן. באר\u0004 ניתנה לישראל \u0003בזכות מרים,\u0004 ו\u0003עמוד ענן\u0004 — \u0003בזכות אהרן, ומן\u0004 — \u0003בזכות משה.\u0004 ועל כן כאשר \u0003מתה מרים נסתלק הבאר, שנאמר: \"ותמת שם מרים\"\u0004 (במדבר כ, א), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"ולא היה מים לעדה\"\u0004 (במדבר כ, ב), \u0003וחזרה\u0004 הבאר לישראל \u0003בזכות שניהן,\u0004 משה ואהרן.","\u0003מת אהרן נסתלקו ענני כבוד, שנאמר: \"וישמע הכנעני מלך ערד\"\u0004 (במדבר לג, מ), \u0003מה שמועה שמע — שמע שמת אהרן ונסתלקו ענני כבוד, וכסבור\u0004 שאין לישראל עוד הגנה משמים ולכן \u0003ניתנה לו רשות להלחם בישראל. והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"ויראו כל העדה כי גוע אהרן\"\u0004 (במדבר כ, כט),","ו\u0003אמר ר' אבהו: אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"ויראו\" אלא \"וייראו\"\u0004 (נראו, התגלו), משום שעמוד הענן שהסתירם, סר מעליהם לפי שעה. ו\u0003כ\u0004פי \u0003דדריש\u0004 \u0005[שדרש]\u0006 \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש:\u0004 המלה \u0003\"כי\" משמש בארבע לשונות\u0004 (בארבעה מובנים): במובן \u0003אי\u0004 \u0005[אם],\u0006 במובן \u0003דלמא\u0004 \u0005[שמא],\u0006 במובן \u0003אלא,\u0004 ובמובן \u0003דהא\u0004 \u0005[שכן, מפני ש...],\u0006 וכאן יש לפרש \"כי גוע אהרן\" — במובן של דהא = מפני, מפני שמת אהרן, לכן — \"ויראו כל העדה\".","\u0003חזרו שניהם\u0004 הבאר וענני הכבוד \u0003בזכות משה, מת משה נסתלקו כולן, שנאמר: \"ואכחד את שלשת הרעים בירח אחד\"\u0004 (זכריה יא, ח), \u0003וכי בירח\u0004 (בחודש) \u0003אחד מתו\u0004 שלושת הרועים? \u0003והלא מרים מתה ב\u0004חודש \u0003ניסן, ואהרן באב, ומשה באדר! אלא, מלמד שנתבטלו\u0004 עם מות משה \u0003שלש מתנות טובות שנתנו על ידן, ונסתלקו כולן\u0004 כל המתנות \u0003בירח אחד\u0004 ולכן נראה להם כאילו מתו כולם יחד.","ולענייננו: \u0003אלמא אשכחן\u0004 \u0005[מכאן\u0006 ש\u0005מוצאים אנו]\u0006 ש\u0003פרנסה\u0004 באה \u0003בשביל יחיד,\u0004 שהרי אמרו שהפרנסה במן באה בשביל משה! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003משה, כיון\u0004 ש\u0003לרבים הוא בעי\u0004 \u0005[מבקש] —\u0006 \u0003כרבים דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ולא כאדם יחיד.","אגב הזכרת הפסוק בזכריה, מסופר: \u0003רב הונא בר מנוח, ורב שמואל בר אידי, ורב חייא\u0004 מן המקום \u0003ווסתניא, הוו שכיחי קמיה\u0004 \u0005[היו מצויים לפני]\u0006 \u0003רבא,\u0004 שהיו תלמידיו החשובים. \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבא, אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב פפא\u0004 ללמוד, אולם כיון שהיו תלמידי חכמים גדולים, \u0003כל אימת דהוה אמר להו שמעתא ולא הוה מסתברא להו\u0004 \u0005[כל זמן שהיה אומר להם הלכה ולא היתה מסתברת בעיניהם],\u0006 \u0003הוו מרמזי אהדדי\u0004 \u0005[היו מרמזים זה לזה]\u0006 שאין זה כרבם הראשון הגדול רבא. \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 התבייש\u0005].\u0006"],["\u0003אקרויה בחלמיה\u0004 \u0005[הקריאו לו בחלומו]\u0006 פסוק זה: \u0003\"ואכחד את שלשת הרעים\u0004 בירח אחד\u0003\"\u0004 (זכריה יא, ח). \u0003למחר כי הוו מיפטרו מיניה\u0004 \u0005[למחרת כאשר נפרדו ממנו]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ליזלו רבנן בשלמא\u0004 \u0005[ילכו חכמים בשלום]\u0006 שהתכוון בכך לפרידה אחרונה מהם, משום שסבר שכעונש שציערוהו ימותו ולא יראה אותם יותר.","בדומה לזה מסופר: \u0003רב שימי בר אשי הוה שכיח קמיה\u0004 \u0005[היה מצוי לפני]\u0006 \u0003רב פפא, הוה מקשי ליה טובא\u0004 \u0005[\u0006ו\u0005היה מקשה לו הרבה].\u0006 \u0003יומא חד חזייה\u0004 \u0005[יום אחד ראה אותו]\u0006 רב שימי את רב פפא \u0003דנפל על אפיה\u0004 \u0005[שנופל\u0006 על \u0005פניו]\u0006 אחר התפילה, \u0003שמעיה דאמר\u0004 \u0005[\u0006ו\u0005שמע אותו שאומר]\u0006 בתפילתו: \u0003רחמנא ליצלן מכיסופא\u0004 \u0005[ה' יצילנו מן הבושה]\u0006 של \u0003שימי. קביל עליה שתיקותא, ותו לא אקשי ליה\u0004 \u0005[קיבל עליו שתיקה, ושוב לא הקשה לו]\u0006 שראה שהדבר גורם צער לרבו.","ומעירים בהקשר לענין הראשון, \u0003ואף ריש לקיש סבר\u0004 ש\u0003מטר\u0004 יורד \u0003בשביל יחיד,\u0004 ש\u0003אמר ריש לקיש: מנין למטר\u0004 שהוא יורד \u0003בשביל\u0004 ה\u0003יחיד — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שאלו מה' מטר בעת מלקוש ה' עשה חזיזים ומטר גשם יתן להם לאיש עשב בשדה\"\u0004 (זכריה י, א).","\u0003יכול\u0004 שיורד הגשם \u0003לכל — תלמוד לומר \"לאיש\". ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לאיש, יכול לכל שדותיו — תלמוד לומר\u0004 באותו פסוק: \u0003\"שדה\",\u0004 שפעמים ראוי שירד רק בשדה אחד. \u0003אי\u0004 \u0005[אם]\u0006 \u0003שדה יכול לכל השדה — תלמוד לומר \"עשב\",\u0004 שעשוי שיירד גשם עבור עשב אחד באותו שדה.","\u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב דניאל בר קטינא הוה ליה ההיא גינתא\u0004 \u0005[היתה לו גינה אחת],\u0006 \u0003כל יומא הוה אזיל סייר לה\u0004 \u0005[כל יום היה הולך ומסייר בה]\u0006 לבדוק מה היא צריכה. \u0003אמר: הא מישרא בעיא מיא, והא מישרא לא בעיא מיא\u0004 \u0005[ערוגה זאת צריכה מים, וערוגה זו אינה צריכה מים],\u0006 \u0003ואתא מיטרא וקמשקי כל היכא דמיבעי ליה מיא\u0004 \u0005[והיה הגשם בא ומשקה כל מקום שהיה צריך לו מים]\u0006 ולא במקום אחר.","כיון שהוזכר אותו פסוק בזכריה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב: \u0003\"ה' עשה חזיזים\"? אמר ר' יוסי בר' חנינא: מלמד שכל צדיק וצדיק הקדוש ברוך הוא עושה לו חזיז בפני עצמו,\u0004 שבזמן מתן השכר מקבל כל צדיק את שכרו ואת עולמו לעצמו. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חזיזים\"? אמר רב יהודה: פורחות. אמר ר' יוחנן: סימן למטר — פורחות.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003פורחות? אמר רב פפא: עיבא קלישא תותי עיבא סמיכתא\u0004 \u0005[עב קלוש מתחת לעב סמיך],\u0006 הוא הקרוי פורחות.","סימן אחר לגשמים העתידים לבוא \u0003אמר רב יהודה: נהילא מקמי מיטרא\u0004 \u0005[טיפטוף\u0006 קל \u0005לפני הגשם]\u0006 כשעדיין לא ירד גשם, משמעו: \u0003אתי מיטרא\u0004 \u0005[\u0006ש\u0005יבוא גשם]\u0006 עז לאחר מכן. ואם \u0003בתר מיטרא\u0004 \u0005[אחרי הגשם]\u0006 יש טיפטוף, מלמד הדבר ש\u0003פסיק מיטרא\u0004 \u0005[פסק הגשם]\u0006 וסימן לדבר: \u0003מקמי מיטרא אתי מיטרא\u0004 \u0005[\u0006כש\u0005לפני הגשם יבוא גשם]\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003מהולתא\u0004 \u0005[נפה],\u0006 שקודם מתחיל לצאת מעט מעט, ואחר כך יוצאות כמויות גדילות והולכות, וכך אף בגשם. \u0003דבתר מיטרא פסיק מיטרא\u0004 \u0005[שלאחר הגשם פוסק הגשם]\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003חריא דעיזי\u0004 \u0005[גללי עיזים],\u0006 שקודם מטילות גללים גסים יותר ואחר כך גללים דקים.","אגב אותם עניינים מסופר: \u0003עולא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל, חזא\u0004 \u0005[\u0006ו\u0005ראה]\u0006 שם \u0003פורחות, אמר להו\u0004 \u0005[להם]:\u0006 \u0003פנו מאני, דהשתא אתי מיטרא\u0004 \u0005[פנו את הכלים, שעכשיו יבוא הגשם].\u0006 \u0003לסוף\u0004 \u0005[לבסוף]\u0006 \u0003לא אתי מיטרא\u0004 \u0005[בא הגשם],\u0006 למרות הפורחות. \u0003אמר: כי היכי דמשקרי בבלאי הכי משקרי מיטרייהו\u0004 \u0005[כפי שמשקרים הבבליים, כך משקרים גשמיהם],\u0006 שהרי פורחות הם סימן לגשמים בארץ ישראל ואין סימן זה יפה בבבל.","אגב סיפור זה מספרים עוד: \u0003עולא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל\u0004 במסעותיו, \u0003חזי מלא צנא דתמרי בזוזא\u0004 \u0005[ראה\u0006 שמוכרים \u0005מלוא הטנא תמרים בזוז].\u0006 \u0003אמר: מלא צנא דדובשא בזוזא ובבלאי לא עסקי באורייתא\u0004 \u0005[מלוא הטנא דבש\u0006 תמרים \u0005בזוז\u0006 אחד, \u0005והבבליים אינם עוסקים בתורה]?\u0006 שאם המזונות המשובחים הללו זולים כל כך, יכולים אנשים לעסוק בתורה, שאינם צריכים לעמול קשה לפרנסתם. ואף הוא עצמו אכל תמרים הרבה. \u0003בליליא צערוהו\u0004 \u0005[בלילה ציערו אותו],\u0006 שהתמרים גרמו לו לשילשול, \u0003אמר: מלא צנא דסכינא בזוזא, ובבלאי עסקי באורייתא\u0004 \u0005[מלוא הטנא סכינים בזוז\u0006 מוכרים בבבל, \u0005והבבליים\u0006 בכל זאת \u0005עוסקים בתורה]!\u0006 וגדול כוחם שהם לומדים, שהרי אי אפשר לחיות על תמרים בלבד.","ודברים כלליים בענין מוצא הגשמים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל העולם כולו ממימי אוקיינוס הוא שותה,\u0004 שאין הגשמים אלא מימי אוקיינוס היורדים על הארץ, \u0003שנאמר: \"ואד יעלה מן הארץ והשקה את כל פני האדמה\"\u0004 (בראשית ב, ו). \u0003אמר לו ר' יהושע: והלא מימי אוקיינוס מלוחין הן\u0004 ומי הגשמים הם מים מתוקים! \u0003אמר לו: ממתקין\u0004 המים \u0003בעבים,\u0004 ומשם יורדים מים מתוקים.","ואילו \u0003ר' יהושע אומר: כל העולם כולו ממים העליונים הוא שותה, שנאמר: \"למטר השמים תשתה מים\"\u0004 (דברים יא, יא), ושואלים: \u0003אלא מה אני מקיים\u0004 (מפרש) לשיטת ר' יהושע את הפסוק \u0003\"ואד יעלה מן הארץ\"? מלמד שהעננים מתגברים ועולים לרקיע, ופותחין פיהן כנוד, ומקבלין מי מטר\u0004 מלמעלה, \u0003שנאמר: \"\u0004כי יגרע נטפי מים \u0003יזקו מטר לאדו\"\u0004 (איוב לו, כז) (וזיקא הוא בארמית נאד) שהאד העולה מן הארץ הוא כנאד המכיל את המטר,","\u0003ומנוקבות הן\u0004 העננות \u0003ככברה\u0004 המלאה חורים, \u0003ובאות ומחשרות\u0004 (ומשליכות) \u0003מים על גבי קרקע, שנאמר: \"חשרת מים עבי שחקים\"\u0004 (שמואל ב' כב, יב). \u0003ואין בין טיפה לטיפה אלא כמלא נימא\u0004 (חוט) ואף על פי כן כל טיפה יוצאת לחוד, \u0003ללמדך שגדול יום הגשמים כיום שנבראו בו שמים וארץ,\u0004 שפלא ירידת הגשם כבריאת העולם,","\u0003שנאמר\u0004 לגבי בריאת העולם: \u0003\"עשה גדלות עד אין חקר\"\u0004 (איוב ט, י) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"\u0004עושה גדולות ואין חקר נפלאות עד אין מספר. \u0003הנתן מטר על פני ארץ\"\u0004 (איוב ה, ט-י) \u0003וכתיב להלן\u0004 \u0005[ונאמר הלאה]:\u0006 \u0003\"הלוא ידעת אם לא שמעת אלהי עולם ה'\u0004 בורא קצות הארץ לא ייעף ולא ייגע \u0003אין חקר לתבונתו\"\u0004 (ישעיהו מ, כח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפרק המדבר בירידת גשמים: \u0003\"מכין הרים בכחו\u0004 נאזר בגבורה\u0003\"\u0004 (תהלים סה, ז), משמע שירידת הגשם אף היא דבר שהוא גדול עד אין חקר, כבריאת העולם.","ומעירים: \u0003כמאן אזלא הא דכתיב\u0004 \u0005[כ\u0006שיטת \u0005מי הולך\u0006 דבר \u0005זה שנאמר]\u0006 במקרא: \u0003\"משקה הרים מעליותיו\"\u0004 (תהלים קד, יג), \u0003ואמר ר' יוחנן:\u0004 הכוונה היא — \u0003מעליותיו של הקדוש ברוך הוא, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 \u0003כ\u0004שיטת \u0003ר' יהושע\u0004 שהגשמים באים מלמעלה.","ושואלים: \u0003ור' אליעזר\u0004 כיצד מסביר הוא לשיטתו פסוק זה? ומשיבים: הוא סבור, \u0003כיון דסלקי להתם\u0004 \u0005[שעולים לשם]\u0006 כלפי מעלה \u0005—\u0006 \u0003\"משקה מעליותיו\" קרי להו\u0004 \u0005[קוראים להם].\u0006 \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 הכתוב \u0003\"אבק עפר מן השמים\"\u0004 (דברים כח, כד) \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה],\u0006 וכי בשמים אבק ועפר? \u0003אלא, כיון דמדלי להתם\u0004 \u0005[שעולה לשם]\u0006 האבק ויורד לארץ מלמעלה — \u0003\"מן השמים\" קרי ליה\u0004 \u0005[קורא אותו],\u0006 \u0003הכא נמי דסלקי להתם\u0004 \u0005[כאן גם כן,\u0006 כיון \u0005שעולים לשם\u0006 העננים\u0005]\u0006 לכך \u0003\"מעליותיו\" קרי ליה\u0004 \u0005[קורא אותם].\u0006","ושואלים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו]\u0006 ש\u0003אמר ר' חנינא: \"כנס כנד מי הים נתן באוצרות תהומות\"\u0004 (תהלים לג, ז), פירושו: \u0003מי גרם לאוצרות שיתמלאו בר — תהומות,\u0004 שמהם באו המים, הרי זו \u0003כ\u0004שיטת \u0003ר' אליעזר.\u0004 ושואלים: \u0003ור' יהושע,\u0004 מה אומר הוא על כתוב זה? ומשיבים: הכתוב \u0003ההוא\u0004"],["\u0003בברייתו של עולם\u0004 הוא עוסק, שאז היה כל העולם מוצף במים והקדוש ברוך הוא כנסם למקום אחד שהוא התהומות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארץ ישראל נבראת תחילה וכל העולם כולו נברא לבסוף, שנאמר: \"עד לא עשה ארץ וחוצות\"\u0004 (משלי ח, כו), תחילה ארץ ישראל ואחר כך חוצה לארץ (\"חוצות\"). \u0003ארץ ישראל משקה אותה הקדוש ברוך הוא בעצמו, וכל העולם כולו\u0004 אינו משקה אלא \u0003על ידי שליח, שנאמר: \"הנתן מטר על פני ארץ ושלח מים על פני חוצות\"\u0004 (איוב ה, י).","\u0003ארץ ישראל שותה מי גשמים וכל העולם כולו מתמצית,\u0004 כלומר, משאריות הגשמים הנשארים בעננים, \u0003שנאמר: \"הנתן מטר על פני ארץ\",\u0004 ואחר כך \"ושולח מים\", כלומר, מה שנשאר מהם \"על פני חוצות\". \u0003ארץ ישראל שותה תחילה, וכל העולם כולו לבסוף, שנאמר: \"הנתן מטר על פני ארץ ושלח מים על פני חוצות\". משל\u0004 לכל אלה \u0003לאדם שמגבל את הגבינה,\u0004 כאשר היא מתגבשת בחלב החמוץ, \u0003נוטל\u0004 הוא \u0003את האוכל ומניח את הפסולת.\u0004","שנינו ש\u0003אמר מר\u0004 \u0005[החכם,\u0006 ר' אליעזר\u0005]:\u0006 \u0003ממתקין הן\u0004 מי האוקיינוס \u0003בעבים,\u0004 ושואלים: \u0003מנליה\u0004 \u0005[מניין לו]\u0006 דבר זה? ומשיבים: ש\u0003אמר ר' יצחק בר יוסף אמר ר' יוחנן: כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"חשכת מים עבי שחקים\"\u0004 (תהלים יח, יב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אותו פסוק עצמו בנוסח אחר: \u0003\"חשרת מים עבי שחקים\"\u0004 (שמואל ב' כב, יב), ואם נצרף את שתי הנוסחות","\u0003שקול\u0004 \u0005[קח]\u0006 את האות \u0003כף\u0004 שבנוסח אחד \u0003ושדי\u0004 \u0005[והטל]\u0006 אותה, צרף אותה עם האות \u0003ריש\u0004 שבפסוק השני \u0003וקרי ביה\u0004 \u0005[וקרא בו]\u0006 \u0003\"חכשרת\"\u0004 כלומר: הכשרת מים היא בעבי שחקים.","ושואלים: \u0003ור' יהושע, בהני קראי מאי דריש בהו\u0004 \u0005[בכתובים אלה מה דורש הוא בהם]?\u0006 \u0003סבר לה כי הא\u0004 \u0005[סובר הוא כמו זו]\u0006 שאמרו, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]:\u0006 כאשר \u0003נהור ענני\u0004 \u0005[בהירים העננים]\u0006 \u0003— זעירין מוהי\u0004 \u0005[מעטים המים\u0006 שבהם\u0005].\u0006 וכאשר \u0003חשוך ענני\u0004 \u0005[חשוכים העננים] —\u0006 \u0003סגיין מוהי\u0004 \u0005[מרובים מימיהם].\u0006 וכך הוא מפרש: כשיש \"חשכת מים\" בעננים — יש גם חשרת (זרם) מים בגשמים היוצאים מהם.","ושואלים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו]\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מים העליונים, במאמר הם תלוים.\u0004 שאינם עומדים במקום מסויים אלא תלויים בחלל, במאמרו של הקדוש ברוך הוא, \u0003ופירותיהן\u0004 של מים אלה הם \u0003מי גשמים, שנאמר: \"\u0004משקה הרים מעליותיו \u0003מפרי מעשיך תשבע הארץ\"\u0004 (תהלים קד, יג)? \u0003כמאן —\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003כ\u0004שיטת \u0003ר' יהושע. ור' אליעזר:\u0004 מה הוא אומר על כך — הפסוק \u0003ההוא, במעשה ידיו של הקדוש ברוך הוא דכתיב\u0004 \u0005[שנאמר],\u0006 ואינו מתכוון למים של מעלה.","באותו נושא של עיקר ותמצית \u0003אמר ר' יהושע בן לוי: כל העולם כולו מתמצית גן עדן הוא שותה, שנאמר: \"ונהר יוצא מעדן\u0004 להשקות את הגן\u0003\"\u0004 (בראשית ב, י). \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003מתמצית בית כור שותה תרקב.\u0004 כלומר, מן המים המתמצים ושותתים מן הכלי שבו השקו שטח גדול כבית כור (שלושים סאה), ניתן להשקות שטח קטן שהוא בית תרקב (חצי סאה) ומכאן אפשר להבין שגן עדן היא פי ששים מן העולם.","כיוצא בו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארץ מצרים הויא\u0004 \u0005[היא]\u0006 \u0003ארבע מאות פרסה על ארבע מאות פרסה, והוא אחד מששים בכוש, וכוש אחד מששים בעולם\u0004 כולו, \u0003ועולם\u0004 — \u0003אחד מששים בגן, וגן\u0004 — \u0003אחד מששים לעדן, ועדן אחד מששים לגיהנם,\u0004 נמצא ש\u0003כל העולם כולו ככיסוי קדרה לגיהנם\u0004 שהרי העולם, ובכללו גן ועדן, הוא רק כאחד מששים לו. \u0003ויש אומרים: גיהנם אין לה שיעור\u0004 כלל, \u0003ויש אומרים: עדן אין לה שיעור.\u0004","\u0003אמר ר' אושעיא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 על בבל: \u0003\"שכנת על מים רבים רבת אוצרת\"\u0004 (ירמיהו נא, יג), \u0003מי גרם לבבל שיהו אוצרותיה מלאות בר — הוי אומר מפני ששוכנת על מים רבים\u0004 של נהרות, ולכן אפשר להשקות את אדמתה בקלות. כיוצא בו \u0003אמר רב: עתירה\u0004 \u0005[עשירה]\u0006 \u0003בבל דחצדא בלא מיטרא\u0004 \u0005[ש\u0006היא \u0005קוצרת בלי מטר],\u0006 שהרי אפשר לגדל בה יבול בלא מי גשמים. \u0003אמר אביי: נקיטינן, טובעני ולא יובשני\u0004 \u0005[מוחזק בידינו\u0006 שבבל היא \u0005טובענית ואיננה יבשה]\u0006 ולכן ראויה היא לגידול תבואה בכל עת.","\u0003בשלשה במרחשון שואלין\u0004 (מבקשים) \u0003את הגשמים\u0004 בברכת השנים, שמבקשים \"ותן טל ומטר\". \u0003רבן גמליאל אומר: בשבעה בו\u0004 מתחילים לבקש, שהם \u0003חמשה עשר יום אחר החג\u0004 (סוכות). וקבעו הפסק זמן זה, בין חג הסוכות ליום התחלת שאילת הגשמים, \u0003כדי שיגיע אחרון שבישראל\u0004 שעלה לרגל בחג הסוכות \u0003לנהר פרת,\u0004 בלא שהגשם יפריע לו בחזרתו לביתו.","\u0003אמר ר' אלעזר: הלכה כ\u0004שיטת \u0003רבן גמליאל,\u0004 שיש להתחיל בשאלת גשמים בשבעה במרחשון. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003חנניה אומר: ובגולה\u0004 אין מתחילים לשאול את הגשמים מוקדם כל כך, אלא \u0003עד ששים בתקופה,\u0004 שמתחילים לשאול שישים יום לאחר תקופת תשרי (יום שויון היום והלילה בסתיו). \u0003אמר רב הונא בר חייא אמר שמואל: הלכה כ\u0004שיטת \u0003חנניה.\u0004","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא בעו מיניה\u0004 \u0005[והרי שאלו ממנו]\u0006 \u0003משמואל: מאימת מדכרינן\u0004 \u0005[ממתי מזכירים אנו]\u0006 \u0003\"ותן טל ומטר\"? אמר להו\u0004 \u0005[להם]:\u0006 \u0003מכי מעיילי ציבי לבי טבות רישבא\u0004 \u0005[מ\u0006אותו זמן שבו מתחילים \u0005להכניס את העצים לבית טבות הצייד],\u0006 משמע שיש שיעור אחר! ודוחים: \u0003דילמא אידי ואידי חד שיעורא\u0004 \u0005[שמא זה וזה שיעור אחד]\u0006 \u0003הוא,\u0004 ורק נתן סימן ליום התקופה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003יום ששים\u0004 עצמו האם דינו \u0003כלפני ששים, או כלאחר ששים? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שנחלקו בכך; \u0003רב אמר: יום ששים כלאחר ששים, ושמואל אמר: יום ששים כלפני ששים.\u0004","\u0003אמר ר' נחמן בר יצחק: וסימנך\u0004 כדי שתזכור את שיטות החולקים \u0003עלאי בעו מיא, תתאי לא בעו מיא\u0004 \u0005[העליונים צריכים מים, התחתונים אינם צריכים מים],\u0006 שהרי המים זורמים למטה, והגרים במקום נמוך מקבלים מים מלמעלה ואינם זקוקים להם כל כך. ואף כאן סימן הוא, כי שמואל שהיה בבלי, ובבל מקום נמוך היא ואינה זקוקה כל כך לגשמים, ולכן שמואל אכן מאחר את זמן השאלה. ואילו רב שלמד בארץ ישראל, הגבוהה וזקוקה לגשמים, אמר שצריך להקדים אותה. \u0003אמר רב פפא: הלכתא\u0004 \u0005[\u0006ו\u0005ההלכה\u0006 היא\u0005]:\u0006 \u0003יום ששים כלאחר ששים,\u0004 כשיטת רב, שמתחילים לשאול מיום שישים.","\u0003הגיע שבעה עשר במרחשון ולא ירדו\u0004 עדיין \u0003גשמים\u0004 — \u0003התחילו היחידים\u0004 (אבל לא הציבור) \u0003מתענין שלש תעניות\u0004 על הגשם. וכיצד דרכן של תעניות אלה? \u0003אוכלין ושותין משחשיכה,\u0004 שהצום מתחיל רק בבוקר, ומותר לאכול בלילה, \u0003ומותרין\u0004 גם ביום הצום עצמו \u0003במלאכה וברחיצה ובסיכה\u0004 בשמן \u0003ובנעילת הסנדל ובתשמיש המטה. הגיע ראש חדש כסליו ולא ירדו\u0004 עדיין \u0003גשמים — בית דין גוזרין שלש תעניות על הצבור\u0004 כולו, אלא שאף הן תעניות קלות: \u0003אוכלין ושותין משחשיכה, ומותרין במלאכה וברחיצה ובסיכה ובנעילת הסנדל ובתשמיש המטה.\u0004","שואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003\"יחידים\"\u0004 אלה שנזכרו? \u0003אמר רב הונא: רבנן\u0004 \u0005[חכמים]\u0006 שהם הקרויים יחידים, שהם המיוחדים שבציבור. \u0003ואמר רב הונא: יחידים מתענין שלש תעניות.\u0004 וסידרן של תעניות אלה הוא: ביום \u0003שני\u0004 וביום \u0003חמישי\u0004 וביום \u0003שני\u0004 שבשבוע שאחר מכן.","ושואלים: \u0003מאי קמשמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב הונא בדבריו? הלא \u0003תנינא\u0004 \u0005[שנינו\u0006 כבר\u0005]:\u0006 \u0003אין גוזרין תענית על הצבור בתחילה בחמישי שלא להפקיע את השערים,\u0004 כי ביום השישי של אחר התענית יבואו רבים לקנות הרבה בבת אחת, גם מפני התענית וגם לצורך השבת, ועלולים החנוונים לנצל את הדוחק כדי להעלות את המחירים. \u0003אלא שלש תעניות הראשונות\u0004 קובעים אותן בימים \u0003שני וחמישי ושני.\u0004 ואם כן מפורש הדבר, ואין צורך בדברי רב הונא!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003צבור\u0004 מפני חשש הפקעת המחירים, \u0003אבל יחידים — לא,\u0004 ויכולים להתחיל תעניותיהם גם ביום חמישי, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם היחידים מתחילים בשני. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשהתחילו היחידים להתענות,\u0004 הרי הם \u0003מתענין שני וחמישי ושני. ומפסיקין\u0004 את התענית, אם נזדמן שיום אחד מימי התענית חל \u0003בראשי חדשים\u0004"],["\u0003ובימים טובים הכתובין במגילת תענית\u0004 שגזרו חכמים לא להתענות בהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אל יאמר אדם תלמיד\u0004 בלבד \u0003אני,\u0004 ולכך \u0003איני ראוי להיות יחיד\u0004 ואין עלי לצום, \u0003אלא: כל תלמידי חכמים יחידים\u0004 הם לענין זה. ומגדירים: \u0003אי זהו יחיד ואיזהו תלמיד? יחיד\u0004 הוא אדם שגדול בתורה \u0003כל שראוי למנותו פרנס על הצבור\u0004 ומורה לרבים, ו\u0003תלמיד\u0004 חכם הוא \u0003כל ששואלין אותו דבר הלכה בתלמודו ואומר, ואפילו\u0004 שאינו יודע אלא \u0003במסכת דכלה,\u0004 שהיא המסכת שלומדים באותה שנה בציבור — הרי הוא כבר נחשב לתלמיד חכם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003לא כל הרוצה לעשות עצמו יחיד\u0004 ולנהוג כמנהג יחיד \u0003עושה,\u0004 ולא כל הרוצה לעשות עצמו \u0003תלמיד — עושה,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: עושה, ו\u0004אף \u0003זכור\u0004 הוא \u0003לטוב, לפי\u0004 שהמנהגים שנוהגים בהם תלמידי חכמים לא \u0003שבח הוא לו אלא צער הוא לו\u0004 ויכול אדם לקבל על עצמו חובות אלה, ואין חוששים שהוא נוהג בדבר שאינו ראוי לו.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא כל הרוצה לעשות עצמו יחיד — עושה,\u0004 ולא כל מי שרוצה לעשות עצמו \u0003תלמיד\u0004 — \u0003עושה,\u0004 אלו \u0003דברי ר' שמעון בן אלעזר. רבן שמעון בן גמליאל אומר\u0004 יש לחלק: \u0003במה דברים אמורים — בדבר של שבח,\u0004 כגון להתנאות בבגד של תלמיד חכם, \u0003אבל בדבר של צער,\u0004 שתלמידי חכמים מקפידים בו — \u0003עושה, וזכור לטוב. שאין שבח הוא לו אלא צער הוא לו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מי שהיה מתענה על הצרה ועברה\u0004 אותה צרה, או שהיה מתענה \u0003על החולה\u0004 כדי שיבריא \u0003ונתרפא\u0004 החולה — \u0003הרי זה מתענה ומשלים\u0004 את תעניתו, ואינו מבטל את תעניתו אף שכבר עברה הצרה. ועוד: \u0003ההולך ממקום שאין מתענין למקום שמתענין\u0004 שיש בו צרה שהציבור מתענה עליה — \u0003הרי זה מתענה עמהן.\u0004 וכן ההולך \u0003ממקום שמתענין למקום שאין מתענין — הרי זה מתענה ומשלים\u0004 כמנהג מקומו שלו.","\u0003שכח ואכל ושתה — אל יתראה בפני הצבור\u0004 שהוא שבע \u0003ואל ינהיג עידונין בעצמו\u0004 ואל יחשוב שאם כבר אכל — בטלה ממנו תענית ורשאי לנהוג כביום אחר, אלא יצמצם לפחות באכילתו, \u0003שנאמר: \"ויאמר יעקב לבניו למה תתראו\"\u0004 (בראשית מב, א), ש\u0003אמר להם יעקב לבניו: אל תראו עצמכם כשאתם שבעין לא בפני עשו ולא בפני ישמעאל, כדי שלא יתקנאו בכם,\u0004 שהרי הם זקוקים לאוכל וסובלים מן הרעב. ומכאן למדו שאין לאדם להראות עצמו שבע כאשר בני מקומו רעבים.","אגב הזכרת כתוב זה בעצת יעקב לבניו, מזכירים עצה אחרת שניתנה להם, שאמר להם יוסף: \u0003\"אל תרגזו בדרך\"\u0004 (בראשית מה, כד); \u0003אמר ר' אלעזר: אמר להם יוסף לאחיו: אל תתעסקו בדבר הלכה, שמא תרגזו עליכם הדרך\u0004 שאם אתם נושאים ונותנים בהלכה שמא תבואו לידי קטטה על הלכה זו, ומוטב שלא תגיעו למחלוקת.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעאי בר ברכיה: שני תלמידי חכמים שמהלכים בדרך ואין ביניהן דברי תורה — ראויין לישרף, שנאמר: \"ויהי המה הלכים הולך ודבר והנה רכב אש וסוסי אש ויפרדו בין שניהם\"\u0004 (מלכים ב' ב, יא), \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שיש]\u0006 \u0003דיבור\u0004 תורה ביניהם, ולכן לא הזיקו סוסי האש לאלישע, \u0003הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003דיבור\u0004 — \u0003ראויין\u0004 היו \u0003לישרף\u0004 על שהם הולכים ואינם עוסקים בתורה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003למיגרס\u0004 \u0005[לגרוס\u0006 לחזור\u0005]\u0006 מותר, וראוי לעשות זאת בדרך, \u0003הא\u0004 \u0005[\u0006ו\u0005זה] —\u0006 \u0003לעיוני\u0004 \u0005[לעיין]\u0006 בהלכה, שמתוך העיון יכולים לבוא לחילוקי דעות.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה],\u0006 שכך אמר להם יוסף: \u0003אל תפסיעו פסיעה גסה\u0004 (פסיעות גדולות ומהירות) \u0003והכניסו חמה לעיר,\u0004 כלומר, היכנסו לעיר ללון בה בעוד החמה זורחת. ומסבירים: \u0003אל תפסיעו פסיעה גסה — ש\u0004\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003פסיעה גסה נוטלת אחד מחמש מאות ממאור עיניו של אדם\u0004 וכיון שהיא מזיקה לעינים מוטב שלא להתאמץ ולמהר.","\u0003והכניסו חמה לעיר —\u0004 הרי הוא \u0003כ\u0004פי שאמר \u0003רב יהודה אמר רב.\u0004 ש\u0003אמר רב יהודה אמר רב: לעולם יצא אדם\u0004 ממקום שהוא לן בו \u0003ב\"כי טוב\",\u0004 כלומר, בזמן האור שנאמר בו \"כי טוב\" (בראשית א, ד) \u0003ו\u0004כן \u0003יכנס\u0004 ללון \u0003ב\"כי טוב\", שנאמר: \"הבקר אור והאנשים שלחו\"\u0004 (בראשית מד, ג), משמע שאין מן הראוי לצאת לדרך לפני אור הבוקר.","וכיוצא בו \u0003אמר רב יהודה אמר ר' חייא: המהלך בדרך\u0004 — \u0003אל יאכל יותר משני רעבון\u0004 (ממה שאוכל אדם בשנים של רעב). ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל, \u0005הסבירו]:\u0006 \u0003משום מעיינא\u0004 \u0005[בני המעיים],\u0006 שטלטול הדרך יכול להזיק למעיים המלאים, ומוטב לאכול פחות ככל האפשר. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל אמרו]\u0006 והסבירו: \u0003משום מזוני\u0004 \u0005[מזונות],\u0006 שמא יכלו המזונות באמצע הדרך ולא יהיה לו מזון לאחר כך, ולכן כדאי לאכול רק מעט שבמעט. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 אם כך או כך הוא הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]:\u0006"],["\u0003דיתיב בארבא\u0004 \u0005[שיושב בספינה],\u0006 שמשום חסרון מזונות יש לו לחשוש, אבל לא משום טלטול הדרך. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לומר הבדל באופן \u0003דקאזיל מאוונא לאוונא\u0004 \u0005[שהוא הולך מתחנה לתחנה]\u0006 שטילטול הדרך יש שם, אבל אין חשש למזונות, שהרי בתחנות הדרכים יש מזונות.","מסופר, כי בכל זאת \u0003רב פפא כל פרסה ופרסה\u0004 כשהיה הולך \u0003אכיל חדא ריפתא\u0004 \u0005[\u0006היה \u0005אוכל לחם\u0006 אחד\u0005]\u0006 \u0003קסבר\u0004 \u0005[סבור]\u0006 היה, שהטעם הוא \u0003משום מעיינא\u0004 \u0005[בני המעיים],\u0006 והוא לא חשש לכך, כיון שהיה בריא בגופו, ולא חשש לטלטול הדרך.","\u0003אמר רב יהודה אמר רב: כל המרעיב עצמו בשני\u0004 (בשנות) \u0003רעבון,\u0004 אף שלו עצמו יש אוכל — \u0003ניצל ממיתה משונה, שנאמר: \"ברעב פדך ממות\"\u0004 (איוב ה, כ). ולומדים זאת מדקדוק הלשון, שהרי לשון \u0003\"מרעב\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 לפי משמעו הפשוט של הכתוב, \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 הכתוב: \u0003בשכר שמרעיב עצמו בשני רעבון ניצול ממיתה משונה.\u0004","ובאותו ענין \u0003אמר ריש לקיש: אסור לאדם לשמש מטתו בשני רעבון\u0004 שיש לו לאדם לצער את עצמו בשנים קשות אלה, ורמז לדבר — \u0003שנאמר: \"וליוסף ילד שני בנים בטרם תבוא שנת הרעב\"\u0004 (בראשית מא, נ). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 אף על פי כן \u0003חסוכי\u0004 (חסרי) \u0003בנים משמשין מטותיהן בשני רעבון,\u0004 שכיון שאין להם בנים, צריכים הם להשתדל לקיים מצות פריה ורביה.","באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בזמן שישראל שרויין בצער ופירש אחד מהן\u0004 ואינו משתתף בצער הרבים, \u0003באין שני מלאכי השרת שמלוין לו לאדם\u0004 בכל דרכיו \u0003ומניחין לו ידיהן על ראשו\u0004 כמו שסומכים ומתוודים על קרבן, \u0003ואומרים: פלוני זה שפירש מן הצבור — אל יראה בנחמת צבור.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו נושא: \u0003בזמן שהצבור שרוי בצער, אל יאמר אדם: אלך לביתי, ואוכל ואשתה, ושלום עליך נפשי. ואם עושה כן — עליו הכתוב אומר: \"והנה ששון ושמחה הרג בקר ושחט צאן אכל בשר ושתות יין אכול ושתו כי מחר נמות\"\u0004 (ישעיהו כב, יג), ו\u0003מה כתיב בתריה\u0004 \u0005[נאמר אחריו],\u0006 אחרי פסוק זה המדבר באנשים השמחים בזמן שיש צער לציבור — \u0003\"ונגלה באזני ה' צבאות אם יכפר העון הזה לכם עד תמתון\"\u0004 (ישעיהו כב, יד).","ומעירים: \u0003עד כאן מידת בינונים,\u0004 שהציבור מצטער והם אינם משתפים עצמם בצער. \u0003אבל במדת רשעים מה כתיב\u0004 \u0005[נאמר]\u0006 — גרוע מזה: \u0003\"אתיו אקחה יין ונסבאה שכר והיה כזה יום מחר\"\u0004 (ישעיהו נו, יב), כלומר: הם מקוים לעוד ימים כאלה שיבואו, משום שהם נהנים מצרתם של אחרים, ו\u0003מה כתיב בתריה\u0004 \u0005[נאמר אחריו]:\u0006 \u0003\"הצדיק אבד ואין איש שם על לב... כי מפני הרעה נאסף הצדיק\"\u0004 (ישעיהו נז, א), שהצדיקים מתים כדי שלא יראו ברעה אשר תבוא על רשעים אלה.","\u0003אלא, יצער אדם\u0004 עצמו \u0003עם הצבור, שכן מצינו במשה רבינו שציער עצמו עם הצבור, שנאמר\u0004 בזמן מלחמת עמלק: \u0003\"וידי משה כבדים ויקחו אבן וישימו תחתיו וישב עליה\"\u0004 (שמות יז, יב), \u0003וכי לא היה לו למשה כר אחד או כסת אחת לישב עליה\u0004 שישב על אבן דווקא? \u0003אלא כך אמר משה: הואיל וישראל שרויין בצער\u0004 של מלחמה — \u0003אף אני אהיה עמהם בצער\u0004 ככל שאני יכול, אף על פי שאינני נלחם. \u0003וכל המצער עצמו עם הצבור — זוכה ורואה בנחמת צבור.\u0004","ומוסיפים: \u0003ושמא יאמר אדם: מי מעיד בי\u0004 ביום הדין? שהרי הוא עושה מה שעושה בחשאי! — \u0003אבני ביתו של אדם וקורות ביתו של אדם\u0004 הם \u0003מעידים בו, שנאמר: \"כי אבן מקיר תזעק וכפיס מעץ יעננה\"\u0004 (חבקוק ב, יא). \u0003דבי\u0004 \u0005[\u0006בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003שני מלאכי השרת המלוין לו לאדם, הן\u0004 ה\u0003מעידין עליו, שנאמר: \"כי מלאכיו יצוה לך\u0004 לשמרך בכל דרכיך\u0003\"\u0004 (תהלים צא, יא).","\u0003ר' חידקא אומר: נשמתו של אדם\u0004 עצמו \u0003היא מעידה עליו, שנאמר: \"משכבת חיקך שמר פתחי פיך\"\u0004 (מיכה ז, ה). \u0003ויש אומרים: אבריו של אדם מעידים בו, שנאמר: \"אתם עדי נאם ה'\"\u0004 (ישעיהו מג, י).","ובענין הדין נאמר: \u0003\"אל אמונה ואין עול\u0004 צדיק וישר הוא\u0003\"\u0004 (דברים לב, ד), ומסבירים את דברי הכתוב: \u0003\"אל אמונה\"\u0004 כוונתו: \u0003כשם שנפרעין מן הרשעים לעולם הבא אפילו על עבירה קלה שעושין — כך נפרעין מן הצדיקים בעולם הזה על עבירה קלה שעושין,\u0004 שהצדיקים סובלים בעולם הזה כעונש לעבירות המעטות שעשו כדי למרק ולתקן אותם לעולם הבא.","\u0003\"ואין עול\" — כשם שמשלמין שכר לצדיקים לעולם הבא אפילו על מצוה קלה שעושין — כך משלמין שכר לרשעים בעולם הזה אפילו על מצוה קלה שעושין,\u0004 כדי לתת להם את הטוב המגיע להם בשל אותם מעט מצוות שעשו כבר בעולם הזה, כדי שלא יהיה להם חלק כלשהו בעולם הבא.","ומה שנאמר \u0003\"צדיק וישר הוא\" אמרו: בשעת פטירתו של אדם לבית עולמו כל מעשיו נפטרין לפניו\u0004 ונראים לו שוב, \u0003ואומרים לו: כך וכך עשית במקום פלוני ביום פלוני, והוא אומר: הן\u0004 \u0005[כן]\u0006 כך היה, \u0003ואומרים לו: חתום! וחותם. שנאמר: \"ביד כל אדם יחתום\"\u0004 (איוב לז, ז). \u0003ולא עוד אלא שמצדיק עליו את הדין,\u0004 לאחר שמראים לו את כל מעשיו, \u0003ואומר להם: יפה דנתוני, לקיים מה שנאמר \"למען תצדק בדברך\u0004 תזכה בשפטך\u0003\"\u0004 (תהלים נא, ו).","ומכאן שבים אנו לעיקרה של המסכת, לענין תענית. \u0003אמר שמואל: כל היושב בתענית נקרא חוטא.\u0004 שאין ראוי לאדם לצער את עצמו יתר מן הדין. ומעירים: \u0003סבר כי האי תנא\u0004 \u0005[סבור הוא כ\u0006שיטתו של \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר הקפר ברבי\u0004 (כלומר, ר' אלעזר גדול הדור) \u0003אומר: מה תלמוד לומר: \"וכפר עליו מאשר חטא על הנפש\"\u0004 (במדבר ו, יא) שנאמר בנזיר, \u0003וכי באיזה נפש חטא זה? אלא שציער עצמו מן היין\u0004 על ידי נזירותו.","\u0003והלא דברים קל וחומר: ומה זה שלא ציער עצמו אלא מן היין נקרא חוטא\u0004 וצריך כפרה, \u0003המצער עצמו מכל דבר ודבר — על אחת כמה וכמה.\u0004","ואילו \u0003ר' אלעזר אומר:\u0004 היושב בתענית \u0003נקרא קדוש, שנאמר\u0004 בנזיר: \u0003\"קדש יהיה גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), וצריך ללמוד קל וחומר: \u0003ומה זה\u0004 הנזיר \u0003שלא ציער עצמו אלא מדבר אחד\u0004 מן היין בלבד שהרי כל שאר הדברים מותרים לו, מכל מקום \u0003נקרא קדוש, המצער עצמו מכל דבר\u0004 ודבר — \u0003על אחת כמה וכמה\u0004 שנקרא קדוש.","ושואלים: ו\u0003ל\u0004דעת \u0003שמואל הא איקרי\u0004 \u0005[הרי\u0006 הנזיר \u0005נקרא]\u0006 \u0003קדוש,\u0004 ומדוע אומר הוא שנקרא חוטא? ומשיבים: הכתוב \u0003ההוא\u0004 המציין את ענין הקדושה, על ענין \u0003גידול\u0004 ה\u0003פרע קאי\u0004 \u0005[הוא עומד,\u0006 מדבר\u0005]\u0006 ששיער הנזיר יש בו קדושה, אבל בנזיר עצמו לא נאמרה כל קדושה. ושואלים: \u0003ולר' אלעזר, הא\u0004 \u0005[הרי]\u0006 \u0003נקרא חוטא!\u0004 ומשיבים: הכתוב \u0003ההוא\u0004 נאמר דווקא בנזיר \u0003דסאיב נפשיה\u0004 \u0005[שטימא\u0006 את \u0005עצמו],\u0006 שכיון שנזיר אסור לו להיטמא למתים והוא עשה כן — צריך להביא קרבן לכפר על חטא שחטא על הנפש — שנטמאה בנפש מת.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר הכי\u0004 \u0005[כך]\u0006 שיפה לו לאדם שיתענה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: לעולם ימוד\u0004 (יחשוב, יעריך) \u0003אדם\u0004 את \u0003עצמו\u0004"],["\u0003כאילו קדוש שרוי בתוך מעיו,\u0004 ואסור לו לצער את הקדוש הזה, \u0003שנאמר: \"בקרבך קדוש ולא אבוא בעיר\"\u0004 (הושע יא, ט), משמע שאסור לו לאדם להתענות! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דמצי לצעורי נפשיה\u0004 \u0005[ש\u0006הוא \u0005יכול לצער\u0006 את \u0005עצמו]\u0006 בלא להינזק, הרי כאשר הוא צם ומתענה נקרא קדוש. \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דלא מצי לצעורי נפשיה\u0004 \u0005[זה שאיננו יכול לצער את נפשו]\u0006 ובכל זאת מתענה ומזיק לעצמו, הוא שר' אלעזר דיבר בגנותו.","\u0003ריש לקיש אמר:\u0004 מי שמתענה \u0003נקרא חסיד, שנאמר: \"גמל נפשו איש חסד ועכר שארו\u0004 אכזרי\u0003\"\u0004 (משלי יא, יז), שכל מי שגומל עצמו ממזון, נקרא חסיד (\"איש חסד\"). כיוצא בו \u0003אמר רב ששת: האי בר בי רב דיתיב בתעניתא\u0004 \u0005[בן בית הרב,\u0006 תלמיד חכם, \u0005שיושב בתענית] —\u0006 \u0003ליכול כלבא לשירותיה\u0004 \u0005[שיאכל הכלב את מנתו],\u0006 כלומר, תלמיד חכם המתענה לא הועיל כלום, והרי זה כמי שלא היה לו אוכל מפני שהכלב אכל את מנתו.","\u0003אמר ר' ירמיה בר אבא: אין תענית צבור בבבל\u0004 לכל הדינים הנוהגים בתענית ציבור \u0003אלא תשעה באב בלבד,\u0004 וממילא נבין שכל שאר התעניות אפילו הקבועות לציבור יש לנהוג בהן כבתענית יחיד, הן לגבי דיני התענית, והן לגבי החובה להתענות בה. \u0003ואמר ר' ירמיה בר אבא אמר ריש לקיש: אין תלמיד חכם רשאי לישב בתענית, מפני ש\u0004על ידי התענית \u0003ממעט במלאכת שמים,\u0004 שהרי מלאכתו היא בתורה ובמצוות, ואם מחליש כוחו — ממעט באלה.","שנינו במשנה שבתעניות הראשונות \u0003אוכלין ושותין משחשיכה\u0004 ואין התענית מתחילה אלא בבוקר. \u0003אמר ר' זעירא אמר רב הונא: יחיד שקיבל עליו תענית, אפילו אכל ושתה כל הלילה\u0004 כולו — \u0003למחר\u0004 בבוקר \u0003הוא מתפלל תפלת תענית\u0004 בשמונה עשרה, שמוסיף לומר \"עננו ביום צום תעניתנו\". ואם אחר שהתענה \u0003לן בתעניתו\u0004 ולא אכל כל הלילה — \u0003אינו מתפלל\u0004 תפילה \u0003של תענית\u0004 בבוקר המחרת.","\u0003אמר רב יוסף: מאי קסבר\u0004 \u0005[מה\u0006 בעצם \u0005סבר]\u0006 \u0003רב הונא\u0004 כשאמר את דבריו אלה? האם \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אין מתענין לשעות,\u0004 ושתענית שאינה עד סוף היום איננה נחשבת כתענית ולכן שעות הלילה אין נחשבות כלל לתענית, \u0003או דלמא\u0004 \u0005[שמא]\u0006 סבור הוא ש\u0003מתענין לשעות,\u0004 אבל \u0003המתענה לשעות אינו מתפלל תפלת תענית?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לעולם\u0004 תאמר כי \u0003קסבר\u0004 \u0005[\u0006ש\u0005סבור]\u0006 \u0003רב הונא מתענין לשעות, והמתענה לשעות\u0004 גם \u0003מתפלל תפלת תענית, ושאני הכא דאיכא\u0004 \u0005[ושונה כאן שיש]\u0006 אף \u0003שעות דליליא\u0004 \u0005[של הלילה]\u0006 ש\u0003לא קביל עליה מעיקרא\u0004 \u0005[קיבל על עצמו מתחילה],\u0006 שכן תענית יחיד צריך אדם לקבל על עצמו לפני כן, ואם לן בתעניתו בלא לקבלה עליו מראש נמצא שלא חלה עליו חובת התענית ולכן אינו מוסיף למחרת בתפילתו לומר \"עננו\".","אגב הלכה זו מסופר: \u0003מר עוקבא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003גינזק, בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 בין השאר שלוש שאלות שלא ידע להשיב עליהן תשובה: \u0003מתענין לשעות או אין מתענין לשעות? לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003קנקנין\u0004 של חרס \u0003של גוים\u0004 שהשתמשו בהם גוים כבית קיבול ליין, האם \u0003אסורין\u0004 הקנקנים לעולם \u0003או מותרין? לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003במה,\u0004 באילו בגדים, \u0003שימש משה כל שבעת ימי המלואים\u0004 כאשר שימש ככהן וקידש את אהרן ובניו לכהונה? \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה.","\u0003אזל ושאיל בי מדרשא\u0004 \u0005[הלך ושאל בבית המדרש],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הלכתא\u0004 \u0005[ההלכה\u0006 היא\u0005]\u0006 \u0003מתענין לשעות, ומתפללין תפלת תענית. והלכתא\u0004 \u0005[וההלכה]:\u0006 \u0003קנקנין של גוים לאחר שנים עשר חדש\u0004 שלא השתמשו בהם לכל שימוש — \u0003מותרין.\u0004 ו\u0003במה שימש משה כל שבעת ימי המלואים — בחלוק לבן,\u0004 כלומר, לא בבגדיו ולא בבגדי כהונה רגילים אלא בחלוק לבן מיוחד. \u0003רב כהנא מתני\u0004 \u0005[היה שונה]:\u0006 \u0003בחלוק לבן שאין לו אימרא\u0004 שאין קיפול בשפתו למטה,","\u0003אמר רב חסדא:\u0004"],["\u0003הא דאמרת\u0004 \u0005[זה שאמרת]\u0006 כי \u0003מתענין לשעות — והוא שלא טעם כלום עד הערב,\u0004 כלומר, שקיבל על עצמו תענית לחצי יום, והשלים את תעניתו עד הערב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הא תענית מעלייתא\u0004 \u0005[הרי תענית מעולה]\u0006 \u0003היא,\u0004 שהרי התענה יום שלם! \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר אלא במקרה \u0003דאימלך אימלוכי\u0004 \u0005[שנמלך\u0006 בדעתו\u0005],\u0006 כלומר, שמתחילה לא התכוון להתענות, אבל כיון שמסיבות שונות לא אכל כמה שעות החליט שיהא כבר בתענית כל אותו יום.","\u0003ואמר רב חסדא: כל תענית שלא שקעה עליו חמה — לא שמיה\u0004 \u0005[אין שמה]\u0006 \u0003תענית,\u0004 שאם אכל באמצע היום — אין זו תענית כלל. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003אנשי משמר\u0004 הכהנים והלויים הצריכים לעבוד במקדש באותו שבוע, \u0003מתענין\u0004 בתענית ציבור (כמו אנשי המעמד הישראלים הקשורים למשמר כהנים זה), אבל \u0003לא משלימין\u0004 את תעניתם עם הציבור. ומכאן שאף תענית שעות קרויה תענית! ומשיבים: \u0003התם לצעורי נפשיה בעלמא\u0004 \u0005[שם לצער\u0006 את \u0005עצמו בלבד]\u0006 \u0003הוא\u0004 ואין הדבר נחשב כתענית, אלא קיבלו על עצמם צער מסויים, שהם משתתפים בצום עם כלל הציבור.","ומביאים ראייה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר ר' אליעזר בר' צדוק: אני מבני בניו של סנאה בן בנימין\u0004 (משבט בנימין), \u0003ופעם אחת חל תשעה באב להיות בשבת, ודחינוהו\u0004 את יום הצום \u0003לאחר השבת,\u0004 שהשבת דוחה את צום תשעה באב, \u0003והתענינו בו ולא השלמנוהו, מפני שיום טוב שלנו הוא.\u0004 שכן עשרה באב הוא יום טוב של משפחה זו, כאשר יבואר בפרק שלישי (להלן תענית כו,א), ולא צמו ביום חגם. הרי שגם תענית לשעות נחשבת כתענית! ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003לצעורי נפשיה בעלמא\u0004 \u0005[לצער עצמו בלבד]\u0006 \u0003הוא,\u0004 ובאמת אין זו נחשבת תענית.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממנהגו של ר' יוחנן, ש\u0003אמר ר' יוחנן\u0004 לפעמים: \u0003אהא בתענית עד שאבוא לביתי.\u0004 משמע שאדם יכול לקבל על עצמו תענית אף לשעות אחדות בלבד! ודוחים: \u0003התם לשמוטיה נפשיה מבי נשיאה\u0004 \u0005[שם להשמיט עצמו מבית הנשיא]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה],\u0006 שפעמים לא היה רוצה לאכול שם, וכדי להימנע מלאכול בלא להעליב את מזמיניו היה אומר שקיבל על עצמו תענית, ואחר כך היה אוכל בביתו, ולא היתה זאת תענית באמת. ואם כן לא מצאנו הוכחה לתענית למקצת היום בלבד.","\u0003אמר שמואל: כל תענית שלא קיבל עליו מבעוד יום — לאו שמיה\u0004 \u0005[אין שמה,\u0006 אינה נחשבת\u0005]\u0006 \u0003תענית.\u0004 ושואלים: \u0003ואי יתיב מאי\u0004 \u0005[ואם\u0006 בכל זאת \u0005ישב\u0006 בתענית באותו יום, \u0005מה]\u0006 נחשב הדבר? \u0003אמר רבה בר שילא: דמי למפוחא דמליא זיקא\u0004 \u0005[דומה\u0006 הוא \u0005למפוח שמלא רוח],\u0006 כלומר, אין הדבר נחשב לו, ואינו אלא כנאד מלא רוח בלא דבר מאכל בתוכו.","ושואלים: \u0003אימת מקביל ליה\u0004 \u0005[מתי\u0006 הזמן שהוא \u0005מקבל אותה]\u0006 את התענית על עצמו? \u0003רב אמר: ב\u0004זמן ה\u0003מנחה,\u0004 מחצות היום והלאה, יכול לקבל תענית על עצמו. \u0003ושמואל אמר: בתפלת המנחה,\u0004 שבסיום תפילתו אומר שמקבל על עצמו לצום למחרת. \u0003אמר רב יוסף: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003שמואל מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003במגילת תענית\u0004 לאחר שנמנו בה כל הימים הטובים שקבעו חכמים לזכר מאורעות שונים: \u0003להן, כל איניש דייתי עלוהי מקדמת דנא ייסר\u0004 \u0005[לכן, כל אדם שיבוא עליו\u0006 חיוב תענית \u0005מקודם לכן —\u0006 \u0005יהא קשור]\u0006 במה שכתוב במגילת תענית.","\u0003מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 \u0003ייסר עצמו בצלו\u0004 \u0005[יקשור את עצמו\u0006 בהתחייבות \u0005ב\u0006זמן \u0005התפילה]\u0006 ואם לא עשה זאת בתפילה — אינו חל! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003יאסר עצמו,\u0004 לשנות ממה שכתוב במגילה,","ומעירים: \u0003פליגי בהא\u0004 \u0005[חלוקים בזה]\u0006 \u0003ר' חייא ור' שמעון ברבי; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 שהגירסה היא \u0003ייסר, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: יאסר. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003ייסר — כדאמרינן\u0004 \u0005[כמו שאמרנו].\u0006 אבל \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003יאסר מאי\u0004 \u0005[מה\u0006 פירושו\u0005]\u0006 של דבר?","ומסבירים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003במגילת תענית: כל איניש דייתי עלוהי מקדמת דנא יאסר\u0004 \u0005[כל אדם שיבוא עליו מלפני כן שיהא אסור]\u0006 ומבואר שם: \u0003כיצד? יחיד שקיבל עליו\u0004 לצום \u0003שני וחמישי ושני של כל השנה כולה, ואירעו בם ימים טובים הכתובין במגילת תענית, אם נדרו קודם לגזרתנו\u0004 (גזירת חכמים שקבעו ימים טובים אלה) — \u0003יבטיל נדרו את גזרתנו\u0004 ויצום, \u0003ואם גזרתנו קודמת לנדרו — תבטל גזרתנו את נדרו\u0004 ובאותו יום לא יצום.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עד מתי אוכל ושותה\u0004 בתעניות הקלות — \u0003עד שיעלה עמוד השחר,\u0004 אלו \u0003דברי רבי.\u0004 ואילו \u0003ר' אליעזר בר שמעון אומר: עד קרות הגבר\u0004 (קריאת התרנגול), שהוא לפני עלות עמוד השחר. \u0003אמר אביי: לא שנו\u0004 שרשאי לאכול בלילה \u0003אלא שלא גמר סעודתו\u0004 מהערב, שכיון שלא גמר יכול הוא להמשיך ולסעוד עד הבוקר, \u0003אבל גמר סעודתו — אינו אוכל.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא\u0004 מברייתא: \u0003גמר\u0004 סעודתו \u0003ועמד\u0004 — \u0003הרי זה אוכל,\u0004 הרי שרשאי לאכול גם לאחר הסעודה! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003כשלא סילק\u0004 את השלחן או את כלי האוכל עדיין, והרי זה כאילו לא גמר סעודתו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר רבא: לא שנו אלא כשלא ישן\u0004 לאחר האוכל, \u0003אבל ישן — אינו אוכל\u0004 עוד בלילה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי,\u0004 הרי שנינו באותו ענין: \u0003ישן ועמד\u0004 משנתו בלילה — \u0003הרי זה אוכל!\u0004 ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003במתנמנם\u0004 ולא בישן ממש.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מתנמנם? אמר רב אשי:\u0004"],["\u0003נים\u0004 \u0005[ישן]\u0006 \u0003ולא נים\u0004 \u0005[ישן],\u0006 \u0003תיר\u0004 \u0005[ער]\u0006 \u0003ולא תיר\u0004 \u0005[ער],\u0006 \u0003דקרו ליה ועני ולא ידע אהדורי סברא\u0004 \u0005[שקוראים אותו\u0006 בשמו \u0005ועונה\u0006 אבל \u0005אינו יודע לענות דבר בטעם]\u0006 \u0003וכי מדכרי ליה מדכר\u0004 \u0005[וכאשר מזכירים לו\u0006 דבר שאירע באותה שעה \u0005נזכר] —\u0006 הוא הקרוי מתנמנם.","\u0003אמר רב כהנא אמר רב: יחיד שקיבל עליו תענית — אסור בנעילת הסנדל\u0004 באותו יום, \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תענית צבור קיבל עליו,\u0004 ובתענית ציבור אסור בנעילת הסנדל. ושואלים: \u0003היכי ליעבד\u0004 \u0005[כיצד יעשה]\u0006 שלא לבוא לחשש זה? \u0003אמר רבה בר רב שילא: לימא הכי\u0004 \u0005[שיאמר כך],\u0006 במפורש: \u0003למחר אהא לפניך בתענית יחיד.\u0004","מסופר: \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב ששת,\u0004 שהיה עיוור: \u0003הא קא חזינן רבנן דמסיימי מסנייהו ואתו לבי תעניתא\u0004 \u0005[והרי אנו רואים חכמים שנועלים\u0006 את \u0005נעליהם והולכים לבית התענית]\u0006 בתענית ציבור, משמע שאין צורך לחשוש לכך! \u0003איקפד\u0004 \u0005[הקפיד]\u0006 על אלה \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003דלמא מיכל נמי אכול\u0004 \u0005[שמא גם כן אכלו],\u0006 שהרי רואים שהם מזלזלים בתענית.","מסופר: \u0003אביי ורבא מעיילי כי מסיימי אפנתא\u0004 \u0005[היו נכנסים\u0006 בסנדלים \u0005שהיו לובשים על עור הנעל],\u0006 כלומר, הפוכות מלמעלה למטה. \u0003מרימר ומר זוטרא מחלפי דימינא לשמאלא, ודשמאלא לימינא\u0004 \u0005[היו מחליפים\u0006 נעל \u0005ימין לשמאל ושל שמאל לימין]\u0006 ואילו \u0003רבנן דבי\u0004 \u0005[חכמים שבבית\u0006 מדרשו\u0005]\u0006 של \u0003רב אשי נפקי כי אורחייהו\u0004 \u0005[היו יוצאים כדרכם]\u0006 בנעלים, \u0003סברי כי הא\u0004 \u0005[סבורים היו כמו זו]\u0006 ש\u0003אמר שמואל: אין תענית צבור בבבל אלא תשעה באב בלבד\u0004 ובבבל על כל פנים אין לחשוש שמא קיבל עליו תענית ציבור.","ועוד לענין תענית, \u0003אמר רב יהודה אמר רב: לוה אדם תעניתו ופורע,\u0004 שאם אירעה סיבה שאיננו יכול להתענות ביום שקיבל עליו, הריהו מבטל את התענית באותו יום (\"לווה\"), ומקבל על עצמו להתענות ביום אחר (\"פורע\"). וסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה\u0006 את ההלכה הזו \u0005לפני]\u0006 \u0003שמואל, אמר לי: וכי נדר קבל עליה\u0004 \u0005[עליו]\u0006 ש\u0003לא סגי\u0004 \u0005[די]\u0006 לו כש\u0003לא משלם\u0004 \u0005[ישלים\u0006 אותו\u0005]?\u0006 הלא \u0003לצעורי נפשיה קביל עליה\u0004 \u0005[לצער את עצמו קיבל עליו]\u0006 \u0003אי מצי\u0004 \u0005[אם\u0006 הוא \u0005יכול] —\u0006 \u0003מצער נפשיה\u0004 \u0005[יצער עצמו],\u0006 \u0003אי לא מצי\u0004 \u0005[אם אינו יכול] —\u0006 \u0003לא מצער נפשיה\u0004 \u0005[לא יצער עצמו],\u0006 ודי לו במה שהצטער עד אז ואם אינו יכול להשלים את תעניתו — אינו צריך לפרוע תענית זו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר, \u0003אמר רב יהודה אמר רב: לוה אדם תעניתו ופורע. כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה\u0006 את ההלכה הזו \u0005לפני]\u0006 \u0003שמואל, אמר לי: פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003לא יהא\u0004 זה \u0003אלא נדר,\u0004 וכי \u0003נדר מי לא מצי בעי לשלומי ומיזל למחר וליומא אחרינא\u0004 \u0005[האם איננו צריך לשלם אותו למחר וליום אחר]\u0006 ואף תענית כיון שהיא נדר, חייב לפרוע אותה באחד הימים.","מסופר, \u0003רב יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי איקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003רב אסי, עבדו ליה עגלא תילתא\u0004 \u0005[עשו לו,\u0006 לכבודו \u0005עגל משולש],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליטעום מר מידי\u0004 \u0005[יטעם אדוני דבר\u0006 מה\u0005].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בתעניתא יתיבנא\u0004 \u0005[בתענית אני יושב]\u0006 ואיני יכול לאכול. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ולוזיף מר וליפרע\u0004 \u0005[ושילוה אדוני ויפרע\u0006 את התענית\u0005],\u0006 וכי \u0003לא סבר מר להא\u0004 \u0005[סבור אדוני כמו זו]\u0006 ש\u0003אמר רב יהודה אמר רב: לוה אדם תעניתו ופורע? אמר להו\u0004 \u0005[להם]:\u0006 \u0003תענית חלום הוא,\u0004 כלומר, שהיא תענית שאדם מתענה כדי לבטל ממנו חלום רע שחלם בלילה.","\u0003ואמר רבה בר מחסיא אמר רב חמא בר גוריא אמר רב: יפה תענית\u0004 לבטל \u0003חלום\u0004 רע, \u0003כ\u0004מו \u0003אש\u0004 שבוערת ומכלה את ה\u0003נעורת\u0004 של פשתן. \u0003ואמר רב חסדא: ובו ביום.\u0004 כלומר, דווקא אם מתענה ביום שלאחר החלום. וכיון שתענית זו אינה משום נדר, אינו יכול ללוות במקרה זה ולשלם ביום אחר. \u0003ו\u0004באותו ענין \u0003אמר רב יוסף: ואפילו בשבת\u0004 יש לצום כדי לבטל חלום רע שחלם בליל שבת. ושואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 של זה אשר זילזל בכבוד השבת על ידי תענית בה? \u0003ליתיב תעניתא לתעניתא\u0004 \u0005[שישב עוד תענית\u0006 אחרת לכפר \u0005על תעניתו]\u0006 ביום השבת.","\u0003עברו\u0004 ימים \u0003אלו\u0004 שהתענו בהם שלוש תעניות קלות \u0003ולא נענו,\u0004 שלא ירדו גשמים — \u0003בית דין גוזרין שלש תעניות אחרות על הצבור.\u0004 ותעניות אלה חמורות הן: \u0003אוכלין ושותין\u0004 רק \u0003מבעוד יום\u0004 שלפני תחילת ליל התענית, \u0003ואסורין\u0004 ביום הצום \u0003במלאכה וברחיצה ובסיכה\u0004 בשמן, \u0003ובנעילת הסנדל ובתשמיש המטה, ונועלין את המרחצאות\u0004 שלא יבואו אנשים להתרחץ באותו יום.","\u0003עברו\u0004 שלושה ימי תעניות \u0003אלו ו\u0004עדיין \u0003לא נענו — בית דין גוזרין עליהן עוד שבע\u0004 תעניות, \u0003שהן\u0004 בסך הכל \u0003שלוש עשרה תעניות\u0004 שגזרו \u0003על הצבור\u0004 כולו (שהרי היחידים התענו כבר שלוש קודם לכן). \u0003הרי אלו\u0004 שבע אחרונות \u0003יתרות על הראשונות, שבאלו\u0004 נוסף לכל החומרות הקודמות \u0003מתריעין\u0004 (צועקים, משמיעים קול, כאשר יבואר בגמרא) \u0003ונועלין את החנויות.\u0004 ואף שצריכים לנעול את החנויות, בכל זאת \u0003ב\u0004יום \u0003שני\u0004 שהיתה בו תענית \u0003מטין\u0004 (פותחים מעט את החנויות) \u0003עם חשיכה\u0004 שאפשר יהא לקנות צרכי אוכל לאחר הצום, \u0003ובחמישי מותרין\u0004 לפתוח \u0003מפני כבוד השבת,\u0004 שהרי צריך לקנות צרכי מזון עבור השבת הקרובה.","\u0003עברו\u0004 ימים \u0003אלו ולא נענו\u0004 — אין בית דין גוזרים עוד תעניות, אבל כל הציבור צריך לנהוג מנהג אבל: \u0003ממעטין במשא ומתן, בבנין, ובנטיעה, באירוסין, ובנישואין, ובשאילת שלום בין אדם לחבירו,\u0004 והכל נוהגים \u0003כבני אדם הנזופין\u0004 (שקיבלו נזיפה) \u0003למקום\u0004 (מאת הקדוש ברוך הוא), ו\u0003היחידים\u0004 (תלמידי חכמים) \u0003חוזרין ומתענין\u0004 בשני וחמישי \u0003עד שיצא\u0004 (יגמר) חודש \u0003ניסן.\u0004 יותר מכאן אין מבקשים עוד על הגשמים, כי לאחר ש\u0003יצא ניסן וירדו גשמים\u0004 הרי זה \u0003סימן קללה, שנאמר: \"הלוא קציר חטים היום\u0004 אקרא אל ה' ויתן קולות ומטר ודעו וראו כי רעתכם רבה\u0003\"\u0004 (שמואל א' יב, יז).","תחילה שואלים ביחס לדברים שנאסרו בתעניות ציבור: \u0003בשלמא כולהו\u0004 \u0005[נניח כולם],\u0006 שאר הדברים שאסרו, \u0003אית בהו\u0004 \u0005[יש בהם]\u0006 \u0003תענוג; רחיצה וסיכה ותשמיש המטה, אבל\u0004 עשיית \u0003מלאכה\u0004 הלא \u0003צער הוא\u0004 ומדוע גזרו שיתבטלו ממלאכה? \u0003אמר רב חסדא אמר רב ירמיה בר אבא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"קדשו צום קראו עצרה אספו זקנים\"\u0004 (יואל א, יד), משמע שהצום הוא \u0003כעצרת, מה עצרת\u0004 (יום חג) \u0003אסור בעשיית מלאכה — אף תענית אסור בעשיית מלאכה.\u0004","ושואלים: \u0003אי\u0004 \u0005[או]\u0006 נאמר: \u0003מה עצרת,\u0004 חג, אסורה במלאכה כבר \u0003מאורתא\u0004 \u0005[מהערב],\u0006 \u0003אף תענית נמי מאורתא\u0004 \u0005[גם כן\u0006 תהא אסורה במלאכה כבר \u0005מהערב]!\u0006 \u0003אמר ר' זירא: לדידי מיפרשא לי מיניה\u0004 \u0005[לי\u0006 עצמי \u0005נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' ירמיה בר אבא\u0004 עצמו, כך: ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004קדשו צום... \u0003אספו זקנים\",\u0004 לומר, שאיסור מלאכה הוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003אסיפת זקנים, מה אסיפת זקנים\u0004 זמנה \u0003ביום — אף צום נמי\u0004 \u0005[גם כן]\u0006 זמנו \u0003ביום,\u0004 ושואלים: \u0003ואימא מטיהרא\u0004 \u0005[ואמור\u0006 שהדבר מתחיל \u0005מן הצהרים]?\u0006 \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 הדבר \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב הונא,\u0004 ש\u0003אמר: מצפרא כינופיא\u0004 \u0005[מן הבוקר האסיפה],\u0006 שזמן אסיפת העם בתענית הוא משעות הבוקר.","ושואלים: \u0003היכי עבדי\u0004 \u0005[כיצד עושים]\u0006 בפועל? \u0003אמר אביי: מצפרא עד פלגא דיומא מעיינינן במילי דמתא\u0004 \u0005[מן הבוקר עד חצי היום מעיינים אנו בעסקי העיר]\u0006 ובודקים אם יש פגמים וקילקולים מוסריים ואחרים בעיר, ומנסים לתקן אותם, שמא דבר זה גרם להם לעונש. \u0003מכאן ואילך, רבעא דיומא קרינן בספרא ואפטרתא\u0004 \u0005[רבע יום אנו קוראים בספר\u0006 התורה \u0005והפטרה]\u0006 ו\u0003מכאן ואילך בעינן רחמי\u0004 \u0005[מבקשים רחמים,\u0006 מתפללים\u0005],\u0006 \u0003שנאמר: \"ויקומו על עמדם ויקראו בספר תורת ה' אלהיהם רבעית היום ורבעית מתודים ומשתחוים לה' אלהיהם\"\u0004 (נחמיה ט, ג)."],["\u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 שחצי היום הראשון יתפללו, וחצי היום השני יעסקו בענייני הציבור! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך]\u0006 לומר כך, \u0003דכתיב\u0004 \u0005[\u0006כיון \u0005שנאמר]\u0006 באותו ענין: \u0003\"ואלי יאספו כל חרד בדברי אלהי ישראל על מעל הגולה\"\u0004 (עזרא ט, ד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ובמנחת הערב קמתי מתעניתי\u0004 ובקרעי בגדי ומעילי ואכרעה על ברכי \u0003ואפרשה כפי אל ה'\u0004 אלהי\u0003\"\u0004 (עזרא ט, ה), משמע: תחילה עוסקים בענייני הציבור, ואחר כך מתפללים.","\u0003אמר רפרם בר פפא אמר רב חסדא: כל\u0004 יום \u0003שהוא משום אבל, כגון תשעה באב ואבל\u0004 באבלו הפרטי — \u0003אסור\u0004 לרחוץ \u0003בין בחמין בין בצונן,\u0004 ו\u0003כל שהוא משום תענוג,\u0004 כלומר, יום שרק אסור להתענג בו \u0003כגון תענית צבור, בחמין — אסור\u0004 לרחוץ, שיש בכך משום תענוג, אולם לרחוץ לשם נקיון \u0003בצונן\u0004 — \u0003מותר.\u0004","\u0003אמר רב אידי בר אבין: אף אנן נמי תנינא\u0004 \u0005[אף אנחנו גם כן שנינו]\u0006 ראייה לדבר, ששנינו במשנתנו: \u0003ונועלין את המרחצאות,\u0004 משמע שרק בחמין אסור לרחוץ. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ואי\u0004 \u0005[ואם]\u0006 אף \u0003בצונן\u0004 היה \u0003אסור\u0004 לרחוץ, וכי \u0003\"סוכרין\u0004 \u0005[סותמים]\u0006 \u0003את הנהרות\" מבעי ליה למיתני\u0004 \u0005[צריך היה לו לשנות]?!\u0006 שהרי את הנהרות אי אפשר לסתום שלא יוכל אדם להתרחץ בהם כלל, ולכן אין מכאן ראייה, שהרי יתכן שאסור לרחוץ גם בצונן, אלא שאין דרך למנוע מן הכל לרחוץ בצונן.","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 להסביר את דברי אביו, \u0003אבא,\u0004 רב אידי בר אבין, \u0003הכי קשיא ליה\u0004 \u0005[כך\u0006 היה \u0005קשה לו]:\u0006 \u0003מכדי תנן\u0004 \u0005[הלא שנינו\u0006 במשנה\u0005]:\u0006 \u0003אסור ברחיצה,\u0004 ואם כן \u0003נועלין את המרחצאות למה לי\u0004 לומר, מה למדים אנו מכאן להלכה? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שבא הדבר ללמדנו כי \u0003בחמין — אסור,\u0004 ואילו \u0003בצונן מותר.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם\u0006 נאמר שאפשר \u0005לסייע לו]\u0006 לרב חסדא האומר כי אבל אסור בטבילה אף בצונן, מברייתא זו: \u0003כל חייבי טבילות — טובלין כדרכן בין\u0004 שחל יום הטבילה \u0003בתשעה באב, בין ביום הכפורים.\u0004 ונברר, \u0003במאי\u0004 \u0005[במה]\u0006 טובלים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שטובלים \u0003בחמין,\u0004 אולם \u0003טבילה בחמין מי איכא\u0004 \u0005[האם ישנה]?\u0006 והלא מים \u0003שאובין נינהו\u0004 \u0005[הם],\u0006 שאפשר לחמם מים רק כאשר שואבים אותם ומחממים אותם בכלים, ומים שאובים פסולים למקווה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן על מי שהוא טובל \u0003בצונן,\u0004 ואם כן נדייק: \u0003וחייבי טבילות — אין\u0004 \u0005[כן]\u0006 הם שמותרים לטבול בצונן בתשעה באב וביום הכיפורים, אולם \u0003איניש אחרינא\u0004 \u0005[אדם אחר],\u0006 וכגון שהוא אבל — \u0003לא. אמר רב חנא בר קטינא:\u0004 אין ראייה מכאן, כי אפשר לומר ש\u0003לא נצרכה אלא לחמי טבריה\u0004 שחמים הם מעצמם ואינם שאובים, ואפשר איפוא לטבול בהם.","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור\u0006 את \u0005סופה]\u0006 של אותה משנה: \u0003אמר ר' חנינא סגן הכהנים: כדי\u0004 (ראוי) \u0003הוא בית אלהינו לאבד עליו טבילה פעם אחת בשנה,\u0004 שמפני אבל החורבן בתשעה באב ראוי לדחות את זמן הטבילה. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003בצונן מותר — ירחץ\u0004 (יטבול) \u0003בצונן,\u0004 ולא ייבטל מהטבילה ואף לא יבטל איסור שבתענית! \u0003אמר רב פפא:\u0004 אפשר לומר שמדובר \u0003באתרא דלא שכיח\u0004 \u0005[במקום שאין מצוי]\u0006 \u0003צונן,\u0004 כלומר, מקום שבו מצויים מעיינות חמים בלבד, ואין שם צונן, ובמקרה זה אמרו שלא יטבול אלא ימתין למחר.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה אחרת, ממה ששנינו: \u0003כשאמרו\u0004 שבתענית \u0003אסור במלאכה — לא אמרו אלא ביום, אבל בלילה — מותר. וכשאמרו\u0004 ש\u0003אסור בנעילת הסנדל — לא אמרו אלא בעיר. אבל בדרך — מותר. הא כיצד?\u0004 כאשר \u0003יוצא לדרך נועל\u0004 נעליו, ומש \u0003נכנס לעיר,\u0004 בסוף דרכו — \u0003חולץ. וכשאמרו אסור ברחיצה — לא אמרו אלא\u0004 לרחוץ את \u0003כל גופו, אבל\u0004 לרחוץ את \u0003פניו ידיו ורגליו\u0004 בלבד — \u0003מותר, וכן אתה מוצא\u0004 אותו דין גם \u0003במנודה ו\u0004גם \u0003באבל,\u0004 שאף הם אסורים בסיכה ברחיצה ובנעילת הסנדל.","ומבארים את ההוכחה: \u0003מאי לאו אכולהו\u0004 \u0005[האם לא\u0006 מדובר \u0005על כולם],\u0006 גם על מנודה וגם על האבל, בכל פרטי האיסורים הללו. ונבאר: \u0003ובמאי עסקינן\u0004 \u0005[ובמה אנו עוסקים]\u0006 לענין רחיצה, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר פה ברחיצה \u0003בחמין,\u0004 אם כן, רחיצת \u0003פניו ידיו ורגליו מי שרו\u0004 \u0005[האם מותרים]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ששת: אבל אסור להושיט\u0004 אפילו \u0003אצבעו בחמין\u0004 כדי לרחוץ אותה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר פה ברחיצה \u0003בצונן,\u0004 ונלמד מכאן שאבל אסור ברחיצת גופו כל עיקר, אפילו בצונן, בניגוד לדברי רב חסדא שהתיר בצונן!","ודוחים: \u0003לא, לעולם\u0004 תפרש שמדובר ברחיצה \u0003בחמין, ודקא קשיא לך\u0004 \u0005[ומה שקשה לך]\u0006 \u0003\"וכן אתה מוצא במנודה ובאבל\",\u0004 לא לענין רחיצה נאמרו הדברים אלא — \u0003אשארא\u0004 \u0005[על שאר]\u0006 הדברים, שאסורים הם במלאכה ובנעילת הסנדל.","ומציעים עוד ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מברייתא, ש\u0003אמר ר' אבא הכהן משום\u0004 (בשם) \u0003ר' יוסי הכהן: מעשה ומתו בניו של ר' יוסי בן ר' חנינא, ורחץ בצונן כל שבעה\u0004 ימים של אבלותו. משמע שרחיצה מותרת לאבל! ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 היה מקרה מיוחד \u0003כשתכפוהו אבליו,\u0004 שאירעו לו אסונות אלה, מיתת בניו, בזה אחר זה, ונמשכה תקופת האבל זמן מרובה ולכן הותר לו לרחוץ כדי שלא יבוא לידי סבל מרובה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 כעין זה: \u0003תכפוהו אבליו זה אחר זה,\u0004 אף שאבל אסור בתספורת, אם \u0003הכביד שערו\u0004 ביותר — \u0003מיקל\u0004 ומספר משיער ראשו \u0003בתער, ומכבס כסותו במים.\u0004 ולכן אף לענין רחיצה התירו במקרה כזה.","ו\u0003אמר רב חסדא\u0004 בפירושה של ברייתא זו: מיקל שערו \u0003בתער אבל לא במספרים\u0004 כדרך תספורת רגילה, רוחץ כסותו \u0003במים ולא בנתר\u0004 (כעין סבון) \u0003ולא בחול\u0004 שרוחצים בו.","\u0003אמר רבא: אבל מותר לרחוץ בצונן כל שבעה\u0004 ימים של אבילות, \u0003מידי דהוה אבשרא וחמרא\u0004 \u0005[כפי שהוא\u0006 הדין לגבי \u0005בשר ויין]\u0006 שמותר לו לאכול מהם, ואף בצונן לא אסרו עליו, למרות שיש בכך הנאה מסויימת. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך:"],["\u0003אין הבוגרת,\u0004 כלומר, נערה שכבר בגרה והיא ראויה כבר לנישואין \u0003רשאה לנוול את עצמה בימי אבל אביה\u0004 כדי שלא תימאס בעיני הבריות ולא תוכל להינשא. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003נערה\u0004 שעדיין לא בגרה \u0003רשאה\u0004 לנוול עצמה.","ונברר: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004כך שהיא נמנעת מ\u0003רחיצה, ובמאי\u0004 \u0005[ובמה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאסורה הנערה לרחוץ \u0003ב\u0004מים \u0003חמין\u0004 והבוגרת מותרת, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: אבל אסור להושיט אצבעו בחמין! אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ודאי \u0003בצונן,\u0004 שבצוננים מותר לבוגרת לרחוץ, ומכאן נלמד שנערה אינה רשאה לרחוץ אפילו בצונן! ודוחים: \u0003לא,\u0004 אין מדובר כאן ברחיצה כלל אלא על \u0003כיחול ופירכוס\u0004 (צביעת העינים והפנים וסידור השערות), שהבוגרת איננה חייבת להימנע מאלה אפילו בימי אבלה.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ש\u0003אמר ר' אבא הכהן משום ר' יוסי הכהן: מעשה ומתו בניו של ר' יוסי בר חנינא, ורחץ בצונן כל שבעה\u0004 ימים של אבל. הרי שאבל מותר ברחיצה בצונן!","ודוחים, אין זו ראייה, כי \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בשתכפוהו אבליו\u0004 (ימי אבלו) \u0003זה אחר זה,\u0004 שמתו בניו בזה אחר זה ולא היה פסק זמן בין ימי אבל האחד לימי אבל אחיו ומתוך שנמשכה אבלותו זמן רב ולא היה יכול לרחוץ עצמו במשך תקופה ארוכה, לכך הקל על עצמו ורחץ בצונן כל שבעה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תכפוהו אבליו זה אחר זה,\u0004 ו\u0003הכביד שערו — מיקל בתער, ו\u0004כמו כן, אם צריך, הריהו \u0003מכבס כסותו במים.\u0004 ו\u0003אמר רב חסדא:\u0004 מספר \u0003בתער — אבל לא במספרים\u0004 כרגיל, כובס \u0003במים ולא בנתר ולא בחול ולא באהל\u0004 (חומר סבוני מן הצומח). כל זה היה נוסח אחד של דברי רבא והמשא והמתן בדבריו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הסוגיה הזו בנוסח שונה, \u0003אמר רבא: אבל אסור\u0004 ברחיצה אפילו \u0003בצונן כל שבעה.\u0004 ושאלו: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מבשר ויין\u0004 שמותר לו לאכול? ומשיבים: \u0003התם לפכוחי פחדיה הוא דעביד\u0004 \u0005[שם לפכח,\u0006 לבטל \u0005מפחדו הוא שעושה],\u0006 כלומר, שכיון שהוא מלא חרדה ודכדוך בגלל המוות התירו חכמים שיחזק עצמו במאכלים טובים ומעוררים, כדי שיוכל להתגבר.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר ש\u0006אפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003אין הבוגרת רשאה לנוול\u0004 את \u0003עצמה.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003נערה רשאה!\u0004 ונברר: \u0003במאי\u0004 \u0005[במה]\u0006 מדובר, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי דין זה שהנערה אסורה לרחוץ והבוגרת מותרת הרי זה \u0003ב\u0004מים \u0003חמין? והאמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב חסדא: אבל אסור להושיט אצבעו בחמין,\u0004 ואיך אם כן התירו לבוגרת? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בצונן,\u0004 וראייה לדברי רבא, שסתם אבל אסור לו להתרחץ בצונן! ודוחים: \u0003לא,\u0004 כל זה מדובר על \u0003כיחול ופירכוס.\u0004","\u0003אמר רב חסדא, זאת אומרת,\u0004 ממה שהתירו לאבל שתכפוהו אבליו לכבס במים, כי בדרך כלל \u0003אבל אסור בתכבוסת כל שבעה. והלכתא\u0004 \u0005[וההלכה]\u0006 למעשה: \u0003אבל אסור לרחוץ כל גופו בין בחמין בין בצונן כל שבעה, אבל\u0004 רחיצת \u0003פניו ידיו ורגליו\u0004 בלבד, \u0003בחמין — אסור, בצונן — מותר. אבל לסוך\u0004 בשמן \u0003אפילו כל שהוא — אסור. ואם\u0004 סך רק כדי \u0003לעבר\u0004 (להסיר) \u0003את הזוהמא — מותר.\u0004","קודם דנו בשאלה באיזו מן התעניות מתפללים תפילת התענית, ולעיקר הדבר שואלים: \u0003צלותא דתעניתא היכי מדכרינן\u0004 \u0005[תפילת התענית איך מזכירים אנו],\u0006 איך מזכירים את תענית היחיד בתפילה? \u0003אדבריה\u0004 \u0005[נתן לו רשות]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]\u0006 לדרוש ברבים, ואמר לו את תוכן הדברים שיאמר: \u0003יחיד שקיבל עליו תענית\u0004 — \u0003מתפלל\u0004 תפילה \u0003של תענית, והיכן אומרה\u0004 לתפילה יתירה זו — \u0003בין\u0004 ברכת \u0003\"גואל\" ל\u0004ברכת \u0003\"רופא\"\u0004 שמוסיף עוד ברכה — תפילה לתענית.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יצחק: וכי יחיד קובע ברכה\u0004 שלימה \u0003לעצמו\u0004 שלא בסדר הברכות? \u0003אלא אמר רב יצחק:\u0004 מזכיר את התענית \u0003ב\u0004ברכת \u0003\"שומע תפלה\",\u0004 שבברכה זו שכל עניינה בקשה שישמע ה' תפילתנו בכלל, יכול אדם להזכיר את כל בקשותיו הנוספות, יתר על הסדר הקבוע ובכלל זה גם את תפילת התענית. \u0003וכן אמר רב ששת:\u0004 מזכיר את תפילת התענית \u0003ב\u0004ברכת \u0003\"שומע תפלה\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 ממה ששנינו בברייתא: \u0003אין בין יחיד לצבור\u0004 בתענית \u0003אלא שזה\u0004 היחיד \u0003מתפלל שמונה עשרה\u0004 ברכות \u0003וזה\u0004 הציבור \u0003מתפלל תשע עשרה.\u0004 ונברר, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יחיד\" ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"צבור\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שה\u0003יחיד\u0004 הוא \u0003יחיד ממש, וצבור\u0004 כוונתו \u0003שליח צבור\u0004 המתפלל בתפילת תענית של רבים, וכי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003תשע עשרה\u0004 ברכות בלבד הן? הלא \u0003עשרין וארבע הוו\u0004 \u0005[הן]!\u0006 כמבואר להלן, שמוסיפים בתעניות הציבור עוד שש ברכות.","\u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר],\u0006 כך יש להבין את הברייתא: \u0003אין בין יחיד\u0004 ש\u0003קבל עליו תענית יחיד ליחיד שקבל עליו תענית צבור, אלא שזה\u0004 שקיבל על עצמו תענית יחיד \u0003מתפלל שמונה עשרה\u0004 ברכות ומזכיר את התענית בברכת \"שומע תפילה\", \u0003וזה\u0004 שקיבל עליו תענית ציבור \u0003מתפלל תשע עשרה\u0004 ברכות, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שה\u0003יחיד קובע ברכה לעצמו!\u0004","ודוחים: \u0003לא, לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 שמדובר פה ב\u0003שליח צבור, ודקא קשיא לך\u0004 \u0005[ומה שהיה קשה לך]\u0006 שהרי \u0003שליח צבור עשרין וארבע\u0004 ברכות \u0003מצלי\u0004 \u0005[\u0006הוא \u0005מתפלל],\u0006 כאן מדובר \u0003בשלש תעניות ראשונות, דליכא\u0004 \u0005[שאין\u0006 בהן\u0005]\u0006 \u0003עשרים וארבע\u0004 ברכות, ומתפללים שמונה עשרה ומוסיפים רק ברכה אחת לתענית.","ומקשים: \u0003ולא?\u0004 וכי אין מזכירים בתעניות הציבור הראשונות עשרים וארבע ברכות? \u0003והא\u0004 \u0005[והלא]\u0006 \u0003\"אין בין\" קתני\u0004 \u0005[שנינו],\u0006 שהרי כך שנינו: \u0003אין בין שלש\u0004 תעניות \u0003ראשונות לשלש אמצעיות, אלא שבאלו\u0004 בראשונות \u0003מותרין בעשיית מלאכה, ובאלו\u0004 באמצעיות \u0003אסורין בעשיית מלאכה.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ל\u0004ענין \u0003עשרים וארבע\u0004 ברכות \u0003זה וזה שוין!\u0004","ודוחים: מכאן אין ראייה, כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר,\u0004 שלא מנה התנא את כל ההבדלים בין התעניות. ומקשים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד שאתה יכול לומר \u0003דהאי\u0004 \u0005[ש\u0006את דבר \u0005זה]\u0006 \u0003שייר\u0004 בדווקא? \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אין בין\" קתני\u0004 \u0005[שנה],\u0006 משמע שהוא מדייק בדברים, שלא רק מנה את הדברים של הבדל, אלא הדגיש שזהו ההבדל היחיד! \u0003אלא\u0004 יש לתרץ בצורה אחרת ולומר כי ה\u0003תנא באיסורי קא מיירי\u0004 \u0005[באיסורים הוא עוסק],\u0006 \u0003בתפלות לא מיירי\u0004 \u0005[איננו עוסק],\u0006 שההבדלים שמנה היו לענין חומרת איסורי התעניות, ולא לשאר ההבדלים. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 יתר על כן: \u0003באמצעייתא נמי לא מצלי\u0004 \u0005[ב\u0006תעניות \u0005האמצעיות גם כן אינו מתפלל]\u0006 \u0003עשרים וארבעה\u0004 ברכות, שמה שאמרו שמתפלל עשרים וארבע הוא רק בתעניות האחרונות בלבד.","ותוהים: \u0003ולא?!\u0004 והאם אינו מתפלל? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בין שלש שניות לשבע אחרונות אלא שבאלו\u0004 באחרונות \u0003מתריעין ונועלין את החנויות,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לכל\u0004 שאר \u0003דבריהן זה וזה שוין! וכי תימא הכא נמי תנא\u0004 \u0005[ואם תאמר כאן גם כן שנה]\u0006 \u0003ושייר? והא\u0004 \u0005[והרי]\u0006 \u0003\"אין בין\" קתני\u0004 \u0005[שנה],\u0006 משמע שלא שייר דבר פרט למה שציין במפורש!","את ההוכחה זו דוחים: \u0003ותסברא\u0004 \u0005[והאם סבור אתה]\u0006 שלשון \u0003\"אין בין\" דוקא\u0004 \u0005[מדוייקת]\u0006 ואין עוד הבדלים?"]]};
